window.QBANK={"1":[{"y":2015,"e":"국가직 9급","qn":1,"i":"N92015-01-1","t":"중국인이 일본 국적의 원양어선에서 한국인 선원을 살해한 경우 우리 형법이 적용된다.","ox":"O","m":"①","c":"A","tp":"형법 의 적용범위"},{"y":2015,"e":"국가직 9급","qn":1,"i":"N92015-01-2","t":"영국인이 뉴욕항에 정박 중인 대한민국 국적의 화물선에서 미국인을 살해한 경우 우리 형법이 적용되지 않는다.","ox":"X","m":"②","c":"A","tp":"형법 의 적용범위"},{"y":2015,"e":"국가직 9급","qn":1,"i":"N92015-01-3","t":"독일인이 프랑스에서 대한민국 국민의 주민등록증을 위조한 경우 우리 형법이 적용되지 않는다.","ox":"X","m":"③","c":"A","tp":"형법 의 적용범위"},{"y":2015,"e":"국가직 9급","qn":1,"i":"N92015-01-4","t":"한국인과 중국인이 미국인을 살해하기로 국내에서 공모하고 미국에서 실행행위를 한 경우 우리 형법이 적용되지 않는다.","ox":"X","m":"④","c":"A","tp":"형법 의 적용범위"},{"y":2016,"e":"국가직 9급","qn":15,"i":"N92016-15","t":"형법 의 적용범위에 대한 설명으로 옳은 것만을 모두 고른 것은?","c":"A","mc":{"s":"형법 의 적용범위에 대한 설명으로 옳은 것만을 모두 고른 것은?","d":"(다툼이 있는 경우 판례에 의함)\nㄱ. 속지주의 원칙에서 범죄지의 결정기준은 범죄 결과 발생지뿐만 아니라 구성요건적 실행행위가 이루어진 곳도 포함된다.\nㄴ. 외국인이 독일에서 북한의 지령을 받아 베를린 주재 북한이익대표부를 방문하여 북한공작원을 만나 반국가 단체를 이롭게 한 행위에 대하여 우리나라 형법 이 적용된다.\nㄷ. 한반도의 평시상태에서 미군의 군속 중 ‘통상적으로 대한민국에 거주하고 있는 자’는 ‘대한민국과 아메리카 합중국 간의 상호방위조약 제4조에 의한 시설과 구역 및 대한민국에서의 합중국 군대의 지위에 관한 협정’ (SOFA)이 적용되는 군속의 개념에서 배제되므로 우리나라 법원에 재판권이 있다.\nㄹ. 대한민국 영역 외에서 형법 제289조 제1항의 구성요건인 사람을 매매한 행위를 한 외국인에 대해서는 우리나라 형법 이 적용된다.","o":["ㄱ, ㄷ","ㄴ, ㄷ","ㄱ, ㄴ, ㄹ","ㄱ, ㄷ, ㄹ"],"a":4}},{"y":2017,"e":"국가직 9급","qn":1,"i":"N92017-01-1","t":"형벌법규를 하위법령에 위임할 때 처벌법규의 기본사항에 관하여 구체적 기준이나 범위를 정함이 없이 포괄적으로 하위법령에 위임하였다면 명확성의 원칙에 위배되어 죄형 법정주의에 반한다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"국가직 9급","qn":1,"i":"N92017-01-2","t":"구성요건에 대한 확장적 유추해석은 금지되지만 위법성 및 책임의 조각사유나 소추조건 또는 처벌조각사유인 형면제 사유에 관하여 그 범위를 제한적으로 유추해석하는 것은 허용된다.","ox":"X","m":"②","c":"A","tp":"죄형법정주의"},{"y":2017,"e":"국가직 9급","qn":1,"i":"N92017-01-3","t":"죄형법정주의의 핵심적 내용의 하나인 소급처벌금지의 원칙은 대법원 양형위원회가 설정한 양형기준에도 적용되므로, 그 양형기준이 발효하기 전에 이미 공소가 제기된 범죄에 대하여는 그 양형기준을 참고하여 형을 양정할 수 없다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"국가직 9급","qn":1,"i":"N92017-01-4","t":"보안처분 중 신상정보공개명령, 위치추적전자장치부착명령에는 소급처벌금지의 원칙이 적용된다.","ox":"X","m":"④","c":"A","tp":"죄형법정주의"},{"y":2018,"e":"국가직 9급","qn":1,"i":"N92018-01-1","t":"공모공동정범의 경우 공모지도 범죄지로 보아야 한다.","ox":"O","m":"①","c":"A","tp":"형법의 적용범위"},{"y":2018,"e":"국가직 9급","qn":1,"i":"N92018-01-2","t":"외국인 甲이 외국에서 대한민국 국적 주식회사의 인장을 위조한 경우 대한민국의 재판권이 없다.","ox":"O","m":"②","c":"A","tp":"형법의 적용범위"},{"y":2018,"e":"국가직 9급","qn":1,"i":"N92018-01-3","t":"외국인 甲이 외국에서 장기적출을 목적으로 외국인 A를 매매한 경우 대한민국 형법이 적용될 수 있다.","ox":"O","m":"③","c":"A","tp":"형법의 적용범위"},{"y":2018,"e":"국가직 9급","qn":1,"i":"N92018-01-4","t":"한국인 甲이 외국에서 미결구금 되었다가 무죄판결을 받은 경우 그 미결구금일수는 국내에서 동일한 행위로 인하여 선고받은 형에 산입하여야 한다.","ox":"X","m":"④","c":"A","tp":"형법의 적용범위"},{"y":2018,"e":"국가직 9급","qn":7,"i":"N92018-07-1","t":"법률의 시행령이 형사처벌에 관한 사항을 규정하면서 법률의 명시적인 위임 범위를 벗어나 그 처벌 대상을 확장하는 것은 죄형법정주의의 원칙에 어긋난다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"국가직 9급","qn":7,"i":"N92018-07-2","t":"구 가정폭력범죄의 처벌 등에 관한 특례법의 사회봉사명령은 그 성질이 보안처분이지만 소급효금지의 원칙이 적용된다.","ox":"O","m":"②","c":"A","tp":"죄형법정주의"},{"y":2018,"e":"국가직 9급","qn":7,"i":"N92018-07-3","t":"반의사불벌죄에서 처벌을 희망하지 않는다는 의사표시 또는 처벌희망 의사표시의 철회는 이른바 소극적 소송조건에 해당하고, 소송조건에는 유추해석금지의 원칙이 적용되지 않는다.","ox":"X","m":"③","c":"A","tp":"죄형법정주의"},{"y":2018,"e":"국가직 9급","qn":7,"i":"N92018-07-4","t":"성폭력범죄의 처벌 등에 관한 특례법 제13조의 통신매체 이용음란죄에서 통신매체를 이용하지 아니한 채 ‘직접’ 상대방에게 물건 등을 도달하게 하는 행위까지 포함하여 위 규정으로 처벌할 수 있다고 보는 것은 유추해석금지의 원칙에 위반된다.","ox":"O","m":"④","c":"A","tp":"죄형법정주의"},{"y":2019,"e":"국가직 9급","qn":4,"i":"N92019-04-1","t":"특수상해죄(형법 제258조의2제1항)를 신설하면서 그 법정형을 구 폭력행위 등 처벌에 관한 법률 제3조제1항보다 낮게 규정한 것은 종전의 형벌규정이 과중하다는 데에서 나온 반성적 조치로서 형법 제1조제2항의 ‘범죄 후 법률의 변경에 의하여 형이 구법보다 경한 때’에 해당한다.","ox":"O","m":"①","c":"A","tp":"형법의 시간적 적용범위"},{"y":2019,"e":"국가직 9급","qn":4,"i":"N92019-04-2","t":"피해자의 의사에 상관없이 처벌할 수 있었던 근로기준법위반죄가 반의사불벌죄로 개정되었으나 부칙에는 그 적용과 관련한 경과규정이 없다면, 개정 전의 행위에 대해서는 형법 제1조제1항에 의하여 행위시의 법률이 적용되어야 한다.","ox":"X","m":"②","c":"A","tp":"형법의 시간적 적용범위"},{"y":2019,"e":"국가직 9급","qn":4,"i":"N92019-04-3","t":"포괄일죄로 되는 개개의 범죄행위가 법 개정의 전후에 걸쳐서 행하여진 경우에는 신·구법의 법정형에 대한 경중을 비교하여 볼 필요도 없이 범죄 실행 종료시의 법인 신법을 적용하여 포괄일죄로 처단하여야 한다.","ox":"O","m":"③","c":"A","tp":"형법의 시간적 적용범위"},{"y":2019,"e":"국가직 9급","qn":4,"i":"N92019-04-4","t":"형의 경중의 비교는 원칙적으로 법정형을 표준으로 하고, 병과형 또는 선택형이 있을 때에는 그중 가장 중한 형을 기준으로 하여 다른 형과 경중을 정하는 것이 원칙이다.","ox":"O","m":"④","c":"A","tp":"형법의 시간적 적용범위"},{"y":2020,"e":"국가직 9급","qn":15,"i":"N92020-15-1","t":"위임입법은 수권법률이 처벌대상 행위가 어떠한 것인지를 예측할 수 있을 정도로 구체적으로 정하고, 형벌의 종류 및 그 상한과 폭을 명확히 규정하는 것을 전제로 한다.","ox":"O","m":"①","c":"A","tp":"죄형법정주의"},{"y":2020,"e":"국가직 9급","qn":15,"i":"N92020-15-2","t":"법규범의 문언은 어느 정도 가치개념을 포함할 수밖에 없지만 가급적 일반적·규범적 개념을 사용하지 않는 것이 바람직하다는 의미에서, 명확성의 원칙이란 기본적으로 최대한의 명확성을 요구하는 것으로 볼 수 있다.","ox":"X","m":"②","c":"A","tp":"죄형법정주의"},{"y":2020,"e":"국가직 9급","qn":15,"i":"N92020-15-3","t":"법관의 보충적인 해석을 필요로 하더라도 통상의 해석방법에 의하여 당해 처벌법규의 보호법익과 금지된 행위 및 처벌의 종류와 정도를 알 수 있다면 명확성의 요구에 배치된다고 보기 어렵다.","ox":"O","m":"③","c":"A","tp":"죄형법정주의"},{"y":2020,"e":"국가직 9급","qn":15,"i":"N92020-15-4","t":"법률의 시행령이 형사처벌에 관한 사항을 규정하면서 법률의 명시적인 위임 범위를 벗어나 그 처벌의 대상을 확장하는 것은 죄형법정주의의 원칙에 어긋난다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"국가직 9급","qn":5,"i":"N92021-05","t":"형벌법규의 의미를 피고인에게 불리한 방향으로 지나치게 확장해석하거나 유추해석하는 것은 죄형법정주의 원칙에 반한다.","c":"A","mc":{"s":"형벌법규의 의미를 피고인에게 불리한 방향으로 지나치게 확장해석하거나 유추해석하는 것은 죄형법정주의 원칙에 반한다.","d":"죄형법정주의에 대한 설명으로 옳은 것만을 모두 고르면? (다툼이 있는 경우 판례에 의함)\nㄱ. 형법 상 내란선동죄에서 ‘선동’은 단지 언어적인 표현 행위일 뿐이므로 그 행위에 대한 평가 여하에 따라서는 적용범위가 무한히 확장될 가능성이 있어 죄형법정주의 원칙에 반한다.\nㄴ. 형사처벌에 관련된 모든 법규를 예외 없이 형식적 의미의 법률에 의하여 규정한다는 것은 사실상 불가능할 뿐만 아니라 실제에 적합하지도 않다.\nㄷ. 위임명령에 규정될 내용 및 범위의 기본사항은 구체적이고 분명하게 규정되어 있어야 하므로, 법률이나 상위명령 으로부터 위임명령에 규정될 내용의 대강만을 예측할 수 있는 경우에는 죄형법정주의 원칙에 반한다. ㄹ.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":3}},{"y":2023,"e":"국가직 9급","qn":1,"i":"N92023-01-1","t":"범죄 후 법률의 변경이 있더라도 형의 변경이 없는 경우에는 형법 제1조제1항에 따라 행위시법을 적용해야 한다.","ox":"O","m":"①","c":"A","tp":"형법 제1조제2항"},{"y":2023,"e":"국가직 9급","qn":1,"i":"N92023-01-2","t":"형의 경중의 비교는 원칙적으로 법정형을 표준으로 하고, 처단형이나 선고형에 의할 것은 아니다.","ox":"O","m":"②","c":"A","tp":"형법 제1조제2항"},{"y":2023,"e":"국가직 9급","qn":1,"i":"N92023-01-3","t":"범죄 후 형벌법규의 위임을 받은 법령의 변경에 따라 범죄를 구성하지 아니하게 된 경우, 종전 법령이 범죄로 정하여 처벌한 것이 부당하였다는 반성적 고려에 따라 변경된 경우에 한하여 형법 제1조제2항이 적용된다.","ox":"X","m":"③","c":"A"},{"y":2023,"e":"국가직 9급","qn":1,"i":"N92023-01-4","t":"행위 시 양벌규정에는 법인에 대한 면책규정이 없었으나 법률 개정으로 면책규정이 추가된 경우, 법원은 형법 제1조제2항에 따라 피고인에게 개정된 양벌규정을 적용해야 한다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"국가직 9급","qn":6,"i":"N92024-06-1","t":"의료법인 명의로 개설된 의료기관의 개설자격 위반 여부를 판단할 때, 비의료인의 주도적 자금 출연 내지 주도적 관여 사정만을 근거로 비의료인이 실질적으로 의료기관을 개설ㆍ운영하였다고 판단하였다면, 이는 허용되는 행위와 허용되지 않는 행위를 구별할 수 있는 기준에 따라 판단한 것으로서 죄형법정주의 원칙에 반하지 않는다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"국가직 9급","qn":6,"i":"N92024-06-2","t":"범죄의 성립과 처벌에 관하여 규정한 형벌법규 자체 또는 그로부터 수권 내지 위임을 받은 법령의 변경에 따라 범죄를 구성하지 아니하게 되거나 형이 가벼워진 경우에는, 종전 법령이 범죄로 정하여 처벌한 것이 부당하였다거나 과형이 과중하였다는 반성적 고려에 따라 변경된 것인지 여부를 따지지 않고 원칙적으로 형법 제1조제2항이 적용된다.","ox":"O","m":"②","c":"A","tp":"죄형법정주의"},{"y":2024,"e":"국가직 9급","qn":6,"i":"N92024-06-3","t":"가정폭력범죄의 처벌 등에 관한 특례법이 정한 보호처분 중 하나인 사회봉사명령은 가정폭력범죄행위에 대하여 형사처벌 대신 부과되는 것으로서, 가정폭력범죄를 범한 자에게 의무적 노동을 부과하고 여가시간을 박탈하여 실질적으로는 신체적 자유를 제한하게 되므로, 이에 대하여는 원칙적으로 형벌불소급의 원칙에 따라 행위시법을 적용함이 상당하다.","ox":"O","m":"③","c":"A","tp":"죄형법정주의"},{"y":2024,"e":"국가직 9급","qn":6,"i":"N92024-06-4","t":"유기징역형에 대한 법률상 감경을 하면서 형법 제55조제1항제3호에서 정한 것과 같이 장기와 단기를 모두 2분의 1로 감경하는 것이 아닌 장기 또는 단기 중 어느 하나만을 2분의 1로 감경하는 방식이나 2분의 1보다 넓은 범위의 감경을 하는 방식 등은 죄형 법정주의 원칙상 허용될 수 없다.","ox":"O","m":"④","c":"A"}],"10":[{"y":2015,"e":"국가직 9급","qn":2,"i":"N92015-02-1","t":"중간생략등기형 명의신탁의 수탁자가 자기 명의로 신탁된 부동산을 임의처분한 경우 신탁자에 대한 횡령죄가 성립한다.","ox":"O","m":"①","c":"A","tp":"횡령죄 또는 배임죄"},{"y":2015,"e":"국가직 9급","qn":2,"i":"N92015-02-2","t":"계약명의신탁의 명의수탁자가 악의의 소유자로부터 취득한 부동산을 임의처분한 경우 명의신탁자에 대한 횡령죄는 성립 하지 않지만 배임죄는 성립한다.","ox":"X","m":"②","c":"A","tp":"횡령죄 또는 배임죄"},{"y":2015,"e":"국가직 9급","qn":2,"i":"N92015-02-3","t":"명의신탁부동산을 임의처분한 수탁자의 재차의 처분행위가 선행처분행위에서 당연히 예상될 수 있는 범위를 넘어 새로운 법익침해의 위험을 추가시켰다면 그 행위는 별도의 횡령죄를 구성한다.","ox":"O","m":"③","c":"A","tp":"횡령죄 또는 배임죄"},{"y":2015,"e":"국가직 9급","qn":2,"i":"N92015-02-4","t":"부동산이중매매와는 달리 동산이중매매의 경우는 배임죄가 성립하지 않는다.","ox":"O","m":"④","c":"A","tp":"횡령죄 또는 배임죄"},{"y":2015,"e":"국가직 9급","qn":4,"i":"N92015-04-1","t":"채무의 존재가 명백할 뿐만 아니라 채권자의 상속인이 존재 하고 그 상속인에게 채권의 존재를 확인할 방법이 확보되어 있는 경우 그 채무를 면탈할 의사로 채권자를 살해하더라도 강도살인죄가 성립하지 않는다.","ox":"O","m":"①","c":"A"},{"y":2015,"e":"국가직 9급","qn":4,"i":"N92015-04-2","t":"타인의 휴대전화기를 무단으로 사용해서 통화요금 및 정보 이용료를 발생시킨 경우는 통신회사에 대한 기망행위에 해당 하므로 사기죄가 성립한다.","ox":"X","m":"②","c":"A"},{"y":2015,"e":"국가직 9급","qn":4,"i":"N92015-04-3","t":"위험한 물건을 휴대해서 공갈죄를 범한 경우에는 폭력 행위 등 처벌에 관한 법률에 의해 가중처벌되고 그 경우에는 친족상도례의 규정이 적용되지 않는다.","ox":"X","m":"③","c":"A"},{"y":2015,"e":"국가직 9급","qn":4,"i":"N92015-04-4","t":"일반교통방해죄는 일반공중의 교통안전이 보호법익이며 교통방해 결과가 현실적으로 발생한 때가 기수이다.","ox":"X","m":"④","c":"A"},{"y":2015,"e":"국가직 9급","qn":6,"i":"N92015-06-1","t":"피고인이 피해자로부터 술값의 지급을 요구받자 그 지급을 면하여 재산상 이익을 취득하고자 피해자를 폭행하고 도주한 경우 준강도죄가 성립한다.","ox":"X","m":"①","c":"A"},{"y":2015,"e":"국가직 9급","qn":6,"i":"N92015-06-2","t":"증거인멸죄에서 ‘증거’라 함은 타인의 형사사건 또는 징계사건에 관하여 수사기관이나 법원 또는 징계기관이 국가의 형벌권 또는 징계권의 유무를 확인하는 데 관계있다고 인정되는 일체의 자료를 의미하고, 타인에게 유리한 것이건 불리한 것이건 가리지 아니하며 또 증거가치의 유무 및 정도를 불문한다.","ox":"O","m":"②","c":"A"},{"y":2015,"e":"국가직 9급","qn":6,"i":"N92015-06-3","t":"피고인이 사립대학교 교수들로 하여금 징계처분을 받게 할 목적으로 국민권익위원회의 범정부 국민포털인 국민신문고에 민원을 제기한 행위는 무고죄에 해당하지 않는다.","ox":"O","m":"③","c":"A"},{"y":2015,"e":"국가직 9급","qn":6,"i":"N92015-06-4","t":"경영상 판단과 관련하여 배임죄의 고의를 인정할 수 있는지는 문제된 경영 판단에 이르게 된 경위·동기, 판단대상인 사업의 내용, 기업이 처한 경제적 상황, 손실발생·이익획득의 개연성 등 제반 사정에 비추어 자기 또는 제3자가 재산상 이익을 취득하고 본인에게 손해를 가한다는 인식하의 의도적 행위임이 인정되는 경우인지에 따라 개별적으로 판단하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2015,"e":"국가직 9급","qn":8,"i":"N92015-08-1","t":"‘정보처리’는 사기죄에서 피해자의 처분행위에 상응하므로 입력된 허위의 정보 등에 의하여 계산이나 데이터의 처리가 이루어짐으로써 직접적으로 재산처분의 결과가 초래되어야 한다.","ox":"O","m":"①","c":"A","tp":"컴퓨터등 사용사기죄"},{"y":2015,"e":"국가직 9급","qn":8,"i":"N92015-08-2","t":"피고인이 A회사에서 운영하는 전자복권구매시스템에서 일정한 조건하에 복권 구매명령을 입력하면 가상계좌로 복권 구매 요청금과 동일 액수의 가상현금이 입금되는 프로그램 오류를 이용하여 복권 구매명령 입력 행위를 반복함으로써 자신의 가상계좌로 구매요청금 상당의 금액이 입금되게 하였다면 ‘부정한 명령의 입력’에 해당한다.","ox":"O","m":"②","c":"A","tp":"컴퓨터등 사용사기죄"},{"y":2015,"e":"국가직 9급","qn":8,"i":"N92015-08-3","t":"평상시 여·수신업무를 처리할 권한이 있는 금융기관직원이 범죄의 목적으로 전산단말기를 이용하여 다른 공범들이 지정한 특정계좌에 무자원 송금의 방식으로 거액을 입금한 것은 ‘권한 없이 정보를 입력하여 정보처리를 하게 한 경우’에 해당하지 않는다.","ox":"X","m":"③","c":"A","tp":"컴퓨터등 사용사기죄"},{"y":2015,"e":"국가직 9급","qn":8,"i":"N92015-08-4","t":"아들이 아버지 소유 A은행 예금통장을 절취하여 이를 현금 자동지급기에 넣고 조작하여 예금 잔고를 자신의 거래 은행 계좌로 이체한 경우 컴퓨터등 사용사기죄의 피해자는 A은행 이므로 친족상도례를 적용할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"국가직 9급","qn":7,"i":"N92016-07","t":"형법 상 배임죄가 성립하지 않는 경우는?","c":"A","mc":{"s":"형법 상 배임죄가 성립하지 않는 경우는?","d":"","o":["채무자 甲이 채권자에 대하여 소비대차 등으로 인한 채무를 부담하고 이를 담보하기 위하여 장래에 부동산의 소유권을 이전하기로 하는 내용의 대물변제예약을 하였는데 甲이 당해 부동산을 제3자에게 처분한 경우","부동산의 매도인으로서 매수인에 대하여 그 앞으로의 소유권 이전등기절차에 협력할 의무 있는 甲이 같은 부동산을 매수인 이외의 제3자에게 이중으로 매도하고 제3자 앞으로 소유권 이전청구권 보전을 위한 가등기를 마쳐 준 경우","甲이 부동산에 A명의의 근저당권을 설정하여 줄 의사가 없음에도 A를 속이고 근저당권 설정을 약정하여 금원을 편취한 이후 그 부동산에 관하여 제3자 명의로 근저당권설정등기를 마친 경우","甲이 A에게 전세권설정계약을 맺고 전세금의 중도금을 지급받은 후 당해 부동산에 임의로 제3자에게 근저당권설정등기를 경료해 주어 담보능력상실의 위험이 발생한 경우"],"a":1}},{"y":2016,"e":"국가직 9급","qn":14,"i":"N92016-14","t":"절도죄에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"절도죄에 대한 설명으로 옳은 것은?","d":"","o":["타인의 예금통장을 무단 사용하여 상당액의 예금을 인출한 후 바로 반환한 경우 그 예금통장에 대한 절도죄가 성립한다.","타인의 인감도장을 몰래 가지고 가서 차용금증서의 연대보증인란에 찍고 난 후 바로 제자리에 넣어 둔 경우 그 인감도장에 대한 절도죄가 성립한다.","타인의 직불카드를 무단 사용하여 그 타인의 예금계좌에서 자기의 예금계좌로 돈을 이체시킨 후 바로 반환한 경우 그 직불카드에 대한 절도죄가 성립한다.","타인의 신용카드를 무단 사용하여 현금자동지급기에서 현금을 인출한 후 바로 반환한 경우 그 신용카드에 대한 절도죄가 성립한다. 형 법 2 책형 3 쪽"],"a":1}},{"y":2017,"e":"국가직 9급","qn":11,"i":"N92017-11-1","t":"점유이탈물횡령죄는 위탁관계에 의한 신뢰배반이 없다는 점에서 횡령죄와 구별된다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"국가직 9급","qn":11,"i":"N92017-11-2","t":"타인이 송금절차의 착오로 인해 잘못 송금하여 자신의 계좌에 입금된 돈은 점유이탈물에 해당한다.","ox":"X","m":"②","c":"A","tp":"점유이탈물횡령죄"},{"y":2017,"e":"국가직 9급","qn":11,"i":"N92017-11-3","t":"착오로 인하여 점유한 물건이나 타인이 놓고 간 물건, 일실한 가축도 점유이탈물에 포함될 수 있다.","ox":"O","m":"③","c":"A","tp":"점유이탈물횡령죄"},{"y":2017,"e":"국가직 9급","qn":11,"i":"N92017-11-4","t":"여관이나 목욕탕, PC방 등에서는 주인의 배타적 지배가 인정 되기 때문에 손님이 잃어버린 물건은 점유이탈물이 되지 않고 주인의 점유가 인정된다.","ox":"O","m":"④","c":"A","tp":"점유이탈물횡령죄"},{"y":2017,"e":"국가직 9급","qn":14,"i":"N92017-14","t":"다음 사례에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"다음 사례에 대한 설명으로 옳지 않은 것은?","d":"(다툼이 있는 경우 판례에 의하며, 특별법 위반은 논외로 함) 甲의 보이스피싱에 속은 V가 자신의 현금 1,000만 원을 甲이 양도받아 가지고 있던 乙명의의 통장으로 송금하였고 乙이 현금 140만 원을 인출하였는데, 이 통장은 乙이 누군가의 보이스피싱에 사용될 것임을 알면서 자기 명의로 발급받아 현금카드 및 비밀번호와 함께 돈을 받고 판 것이었고, 통장 발급 금융기관에서 SMS 문자서비스로 계좌에 1,000만 원이 입금되었음을 알려주자 乙이 직불카드를 이용하여 甲보다 먼저 인출하였다.","o":["甲에게는 사기죄가 성립한다.","乙에게는 사기죄의 방조범이 성립한다.","이 사례에서 사기범행으로 취득된 것은 乙의 통장에 입금된 1,000만 원이라는 재산상 이익이다.","乙에게는 장물취득죄가 성립하지 않는다."],"a":3}},{"y":2018,"e":"국가직 9급","qn":6,"i":"N92018-06-1","t":"부동산의 계약명의신탁에서 수탁자 甲이 그 부동산을 임의로 처분한 경우 매도인이 명의신탁사실을 몰랐다면 그 소유권이 甲에게 있으므로 甲에게 횡령죄가 성립하지 않는다.","ox":"O","m":"①","c":"A","tp":"재산범죄"},{"y":2018,"e":"국가직 9급","qn":6,"i":"N92018-06-2","t":"중간생략등기형 명의신탁에서 수탁자 甲이 그 부동산을 임의로 처분한 경우 그 소유권은 신탁자에게 있을 수 없으므로 甲에게 횡령죄가 성립하지 않는다.","ox":"O","m":"②","c":"A","tp":"재산범죄"},{"y":2018,"e":"국가직 9급","qn":6,"i":"N92018-06-3","t":"부동산양도담보권자 甲이 변제기 경과 후에 담보권을 실행하기 위하여 담보목적물을 부당하게 염가로 처분한 경우 甲에게 배임죄가 성립하지 않는다.","ox":"O","m":"③","c":"A","tp":"재산범죄"},{"y":2018,"e":"국가직 9급","qn":6,"i":"N92018-06-4","t":"종중 토지의 명의신탁에서 수탁자 甲이 그 토지에 근저당권을 설정하여 횡령한 이후 기존의 근저당권과 관계없이 그 토지를 매도한 경우 甲에게 별개의 횡령죄가 성립하지 않는다.","ox":"X","m":"④","c":"A","tp":"재산범죄"},{"y":2018,"e":"국가직 9급","qn":13,"i":"N92018-13-1","t":"직원 甲이 회사 컴퓨터에 저장되어 있는 신제품시스템의 설계도면을 자신의 USB 저장장치에 저장하여 가지고 나온 경우 설계도면에 대한 절도죄가 성립한다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"국가직 9급","qn":13,"i":"N92018-13-2","t":"甲이 A 소유의 토지에 권원 없이 식재한 감나무에서 감을 수확한 경우 감에 대한 절도죄가 성립한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"국가직 9급","qn":13,"i":"N92018-13-3","t":"임차인 甲이 임대계약 종료 후 식당건물에서 퇴거하면서 종전부터 사용하던 냉장고의 전원을 켜 둔 채 그대로 두었다가 약 1개월 후 철거해 가는 바람에 그 기간 동안 전기가 소비되게 한 경우 전기에 대한 절도죄가 성립하지 않는다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"국가직 9급","qn":13,"i":"N92018-13-4","t":"甲이 내리막길에 주차된 자동차를 절취할 목적으로 조수석 문을 열고 시동을 걸려고 차 안의 기기를 만지다가 핸드 브레이크를 풀게 되어 시동이 걸리지 않은 상태에서 약 10미터 전진하다가 가로수를 들이받은 경우 자동차에 대한 절도죄의 기수범이 성립하지 않는다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"국가직 9급","qn":15,"i":"N92018-15-1","t":"부동산 입찰절차에서 甲, 乙, 丙이 대금을 분담하되 그중 1인인 甲 명의로 낙찰받기로 약정하고 낙찰을 받은 후 甲이 그 부동산을 임의로 처분한 경우 甲에게는 (업무상)횡령죄가 성립한다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"국가직 9급","qn":15,"i":"N92018-15-2","t":"학교법인을 운영하는 甲이 A사립학교의 교비회계자금을 같은 학교법인에 속하는 B사립학교의 교비회계에 사용한 경우 甲에게는 (업무상)횡령죄가 성립한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"국가직 9급","qn":15,"i":"N92018-15-3","t":"甲이 A에게 금전을 대여하면서 A로부터 그 담보로 동산을 교부받아 보관하고 있던 중 담보권의 범위를 벗어나서 그 동산 담보물을 처분한 경우 甲에게는 횡령죄가 성립한다.","ox":"O","m":"③","c":"A","tp":"(업무상)횡령죄"},{"y":2018,"e":"국가직 9급","qn":15,"i":"N92018-15-4","t":"프랜차이즈 계약을 맺은 가맹점주 甲이 물품판매대금의 일부를 본사로 송금하지 않고 임의로 소비한 경우 甲에게는 (업무상) 횡령죄가 성립하지 않는다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"국가직 9급","qn":17,"i":"N92018-17-1","t":"절취한 타인의 신용카드를 이용하여 현금자동지급기에서 자신의 예금계좌로 돈을 이체시킨 후 그 예금계좌에서 현금을 인출한 경우 현금에 대한 절도죄는 성립하지 않는다.","ox":"O","m":"①","c":"A","tp":"신용카드 범죄"},{"y":2018,"e":"국가직 9급","qn":17,"i":"N92018-17-2","t":"타인의 명의를 모용하여 발급받은 신용카드를 이용하여 현금자동지급기에서 현금대출을 받은 경우 현금에 대한 절도죄가 성립한다.","ox":"O","m":"②","c":"A","tp":"신용카드 범죄"},{"y":2018,"e":"국가직 9급","qn":17,"i":"N92018-17-3","t":"타인의 명의를 모용하여 발급받은 신용카드 번호와 그 비밀번호를 이용하여 ARS전화서비스나 인터넷 등을 통하여 신용대출을 받는 방법으로 재산상 이익을 취득하는 경우 컴퓨터 등 사용 사기죄가 성립한다.","ox":"O","m":"③","c":"A","tp":"신용카드 범죄"},{"y":2018,"e":"국가직 9급","qn":17,"i":"N92018-17-4","t":"신용카드를 절취한 사람이 물품 대금의 결제를 위해 신용카드를 제시하고 카드회사의 승인까지 받았다면 매출전표에 서명한 사실이 없고 도난카드임이 밝혀져 최종적으로 매출취소로 거래가 종결되었다 하더라도 여신전문금융업법의 신용카드 부정사용죄의 기수범이 성립한다.","ox":"X","m":"④","c":"A","tp":"신용카드 범죄"},{"y":2019,"e":"국가직 9급","qn":3,"i":"N92019-03-1","t":"부동산 매도인이 매수인으로부터 중도금을 지급받은 후 그 부동산을 제3자에게 이중으로 양도하였다면 배임죄가 성립한다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"국가직 9급","qn":3,"i":"N92019-03-2","t":"채권담보를 위한 대물변제예약의 채무자가 대물로 변제 하기로 한 부동산을 제3자에게 처분하였더라도 배임죄가 성립하는 것은 아니다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"국가직 9급","qn":3,"i":"N92019-03-3","t":"동산매매계약에서 매도인이 목적물을 매수인에게 인도하지 아니하고 이를 제3자에게 처분하였더라도 배임죄가 성립하는 것은 아니다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"국가직 9급","qn":3,"i":"N92019-03-4","t":"채무자가 채권자 A와 B에게 순차적으로 그 소유의 동산에 대하여 점유개정의 방식으로 이중의 양도담보 설정계약을 체결한 후 그 목적물을 임의로 제3자에게 처분하였다면 A는 물론 B에 대한 관계에서도 배임죄가 성립한다.","ox":"X","m":"④","c":"A"},{"y":2019,"e":"국가직 9급","qn":11,"i":"N92019-11-1","t":"甲이 사실상의 부(父)인 乙의 예금증서를 절취한 후 乙이 甲을 친생자로 인지한 경우에는 친족상도례가 적용되어 형이 면제된다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"국가직 9급","qn":11,"i":"N92019-11-2","t":"조부(祖父)의 예금통장을 절취하여 현금자동지급기에 넣고 조작하는 방법으로 계좌의 예금잔고 중 57만 원을 자신의 은행계좌로 이체한 손자 甲의 컴퓨터등사용사기 범행에는 친족상도례가 적용되지 않는다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"국가직 9급","qn":11,"i":"N92019-11-3","t":"甲이 친구 乙을 교사하여 甲의 아버지 丙의 지갑을 절취하게 한 경우 甲에게만 친족상도례가 적용되어 형이 면제되고 乙은 형이 면제되지 않는다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"국가직 9급","qn":11,"i":"N92019-11-4","t":"甲이 법원을 기망하여 乙의 재물을 편취한 경우 甲과 乙이 직계혈족의 관계에 있다고 하더라도 친족상도례가 적용되지 않는다.","ox":"X","m":"④","c":"A"},{"y":2019,"e":"국가직 9급","qn":19,"i":"N92019-19","t":"다음 사례에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"다음 사례에 대한 설명으로 옳지 않은 것은?","d":"(다툼이 있는 경우 판례에 의함) 甲과 乙은 주간에 함께 A의 집에 침입하여 도품을 물색하던 중, A에게 발각되어 각자 다른 길로 도주했다. 도주 중 甲은 자신을 추적해 오는 A를 발로 차서 넘어지게 하였다. 한편 乙은 순찰 중에 “도둑이야!”라는 소리를 듣고 범인을 체포 하려고 달려온 사복 경찰관을 집주인 A라고 생각하고 체포를 면탈하기 위해 각목을 주워 그의 머리를 내리쳐 전치 8주의 상처를 입혔다.","o":["甲과 乙이 A의 집에 침입한 행위는 공동주거침입에 해당한다.","甲과 乙이 A의 집에서 도품을 물색한 행위는 합동절도의 실행의 착수에 해당한다.","甲이 자신을 추적해 오는 A를 폭행한 행위는 준강도죄를 구성한다.","乙이 경찰관에게 상해를 가한 행위는 강도상해죄와 특수공무 집행방해치상죄를 구성한다."],"a":4}},{"y":2019,"e":"국가직 9급","qn":20,"i":"N92019-20","t":"다음 사례 중 괄호 안의 범죄가 인정되지 않는 것은?","c":"A","mc":{"s":"다음 사례 중 괄호 안의 범죄가 인정되지 않는 것은?","d":"","o":["채권자가 빚 독촉을 하다가 시비 중 멱살을 잡고 대드는 채무자의 손을 뿌리치고 그를 뒤로 밀어 넘어뜨려 아래로 뒹굴게 하여 그 순간 채무자의 등에 업힌 그의 딸에게 두개골 골절상을 입혀 사망하게 한 경우(폭행치사죄)","피해자 법인이나 단체의 대표자 또는 실질적으로 의사결정을 하는 최종결재권자 등 기망의 상대방이 기망행위자와 동일인 이거나 기망행위자와 공모하는 등 기망행위를 알고 있었던 경우(사기죄)","회사직원이 영업비밀 등을 적법하게 반출한 후, 퇴사 시에 그 영업비밀 등을 회사에 반환하거나 폐기할 의무가 있음에도 경쟁업체에 유출할 목적으로 이를 반환하거나 폐기하지 아니한 경우(업무상배임죄)","사법경찰관이 내사단계에서 수사의 대상, 방법 등에 관하여 검사가 자신에게 지휘한 내용이 기재된 수사지휘서를 잠재적 피의자에게 교부하고 이에 관계된 수사상황을 알려준 경우 (공무상비밀누설죄)"],"a":2}},{"y":2020,"e":"국가직 9급","qn":4,"i":"N92020-04-1","t":"재건축사업으로 철거예정이고 그 입주자들이 모두 이사하여 아무도 거주하지 않은 채 비어 있는 아파트라도 재산적 이용가치 내지 효용이 있는 경우에는 재물손괴죄의 재물에 포함된다.","ox":"O","m":"①","c":"A","tp":"손괴의 죄"},{"y":2020,"e":"국가직 9급","qn":4,"i":"N92020-04-2","t":"자동문을 자동으로 작동하지 않고 수동으로만 개폐가 가능하게 하여 자동잠금장치로서 역할을 할 수 없도록 한 경우에도 재물손괴죄가 성립한다.","ox":"O","m":"②","c":"A","tp":"손괴의 죄"},{"y":2020,"e":"국가직 9급","qn":4,"i":"N92020-04-3","t":"홍보를 위해 1층 로비에 설치해 둔 홍보용 배너와 거치대를 훼손 없이 그 장소에서 제거하여 컨테이너로 된 창고로 옮겨 놓아 사용할 수 없게 한 행위는 재물의 효용을 해하는 행위에 해당한다.","ox":"O","m":"③","c":"A","tp":"손괴의 죄"},{"y":2020,"e":"국가직 9급","qn":4,"i":"N92020-04-4","t":"해고노동자 등이 복직을 요구하는 집회를 개최하던 중 래커 스프레이를 이용하여 회사 건물 외벽과 1층 벽면 등에 낙서한 행위와 계란 30여 개를 건물에 투척한 행위는 모두 건물의 효용을 해한 것으로 볼 수 있다.","ox":"X","m":"④","c":"A","tp":"손괴의 죄"},{"y":2020,"e":"국가직 9급","qn":13,"i":"N92020-13","t":"점원에게 금고 열쇠와 오토바이 열쇠를 맡기고 금고 안의 돈을 배달될 가스대금으로 지급할 것을 지시한 후 외출하자 점원이 금고 안에서 현금을 꺼내 도주한 행위는 ( )를 구성한다.","c":"A","mc":{"s":"점원에게 금고 열쇠와 오토바이 열쇠를 맡기고 금고 안의 돈을 배달될 가스대금으로 지급할 것을 지시한 후 외출하자 점원이 금고 안에서 현금을 꺼내 도주한 행위는 ( )를 구성한다.","d":"재산범죄와 관련한 다음 문장에서 괄호 안 어느 곳에도 들어갈 수 없는 죄명은? (다툼이 있는 경우 판례에 의함)\nㄱ. 피해자를 살해한 방에서 사망한 피해자 곁에 4시간 30분쯤 있다가 그곳 피해자의 자취방 벽에 걸려 있던 피해자가 소지하는 물건들을 영득의 의사로 가지고 나온 행위는 ( )를 구성한다.\nㄴ.\nㄷ. 다른 사람이 PC방에 두고 간 핸드폰을 PC방 주인 등 관리자가 아닌 제3자가 취거해 간 행위는 ( )를 구성한다.\nㄹ. 계주가 계원들로부터 월불입금을 모두 징수하였음에도 불구하고 정당한 사유 없이 이를 지정된 계원에게 지급하지 아니한 행위는 다른 특별한 사정이 없는 한 ( )를 구성한다.\nㅁ. 자기 명의의 은행 계좌에 착오로 송금된 돈을 다른 계좌로 이체하는 등 임의로 사용한 행위는 ( )를 구성한다.","o":["절도죄","횡령죄","점유이탈물횡령죄","배임죄"],"a":3}},{"y":2021,"e":"국가직 9급","qn":14,"i":"N92021-14","t":"다음 사례에서 (업무상)횡령죄가 성립하는 경우는?","c":"A","mc":{"s":"다음 사례에서 (업무상)횡령죄가 성립하는 경우는?","d":"","o":["적법한 종중총회의 결의가 없는 상태에서 종중의 회장으로부터 담보 대출을 받아달라는 부탁과 함께 종중 소유의 임야를 이전 받은 자가 임야를 담보로 금원을 대출받아 임의로 사용한 경우 (종중에 대한 관계에서)","법인의 임직원이 법인의 운영에 필요한 자금을 조달하기 위하여 법인의 무자료 거래를 통해 비자금을 조성한 경우(법인에 대한 관계에서)","전기통신금융사기 공범인 계좌명의인이 자신이 개설한 예금계좌에 사기 피해자가 사기 피해금을 송금․이체하자 그 돈을 영득할 의사로 인출한 경우(전기통신금융사기의 범인에 대한 관계에서)","부동산의 공유자 중 1인이 구분소유자 전원의 공유에 속하는 공용부분인 지하주차장 일부를 독점 임대하고 임차료를 수령한 경우(다른 공유자에 대한 관계에서)"],"a":1}},{"y":2021,"e":"국가직 9급","qn":19,"i":"N92021-19","t":"각 사례에서 甲의 죄책으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"각 사례에서 甲의 죄책으로 옳은 것만을 모두 고르면?","d":"(다툼이 있는 경우 판례에 의함)\nㄱ. 골동품상 甲이 주의의무를 게을리하여 절도품인 줄 모르고 절도범이 매각해 달라고 부탁한 고려청자를 보관하던 중 친구로부터 금원을 차용하면서 이를 담보로 제공하였다. －업무상과실장물보관죄와 횡령죄\nㄴ. 甲은 피해자가 사망한 다음 날 마치 피해자가 작성한 것처럼 피해자 명의의 예금청구서 1통을 위조하고, 이를 은행에 제출하였다. －사문서위조죄와 동행사죄 (사기죄는 제외)\nㄷ. 甲은 피해자에 대하여 채권이 있다는 이유로 권리행사를 빙자하여 사회통념상 용인되기 어려운 정도를 넘는 협박을 수단으로 피해자를 외포케 하여 채권을 변제 받았다. －협박죄와 공갈죄\nㄹ. 甲은 타인에게 폭행을 행사하여 그의 업무를 방해하였다. －폭행죄와 업무방해죄","o":["ㄱ, ㄷ","ㄴ, ㄹ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":2}},{"y":2023,"e":"국가직 9급","qn":12,"i":"N92023-12-1","t":"장물범과 피해자 간에 동거친족의 신분관계가 있는 때에는 형을 면제하지만, 장물범과 본범 간에 동거친족의 신분관계가 있는 때에는 형을 감경 또는 면제한다.","ox":"O","m":"①","c":"A","tp":"친족상도례"},{"y":2023,"e":"국가직 9급","qn":12,"i":"N92023-12-2","t":"손자가 할아버지 소유 예금통장을 절취하여 이를 현금자동지급기에 넣고 조작하는 방법으로 예금 잔고를 자신의 거래 은행 계좌로 이체한 경우, 계좌이체 행위에 대해서는 친족상도례를 적용할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"국가직 9급","qn":12,"i":"N92023-12-3","t":"친족상도례의 친족관계는 원칙적으로 범행 당시에 존재하여야 하는 것이지만, 범행 이후 피해자인 부(父)가 피고인인 혼인 외의 출생자를 인지한 경우 인지의 소급효에 따라 친족상도례가 적용된다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"국가직 9급","qn":12,"i":"N92023-12-4","t":"피고인이 백화점 내 점포에 입점시켜 주겠다고 속여 피해자로부터 입점비 명목으로 돈을 편취하여 사기죄로 기소된 경우, 피고인의 딸과 피해자의 아들이 혼인하여 피고인과 피해자가 사돈지간이라면 친족상도례가 적용된다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"국가직 9급","qn":17,"i":"N92023-17-1","t":"피고인이 허위의 채권을 피보전권리로 삼아 가압류를 하였다 하더라도 본안소송을 제기하지 아니한 채 가압류를 한 것만으로는 사기죄의 실행에 착수하였다고 할 수 없다.","ox":"O","m":"①","c":"A","tp":"소송사기"},{"y":2023,"e":"국가직 9급","qn":17,"i":"N92023-17-2","t":"피고인이 허위의 채권으로 법원에 지급명령을 신청하였으나 이에 대해 상대방이 이의신청을 하면 지급명령은 이의의 범위 안에서 그 효력을 잃게 되므로 사기죄의 실행의 착수는 인정되지 아니한다.","ox":"X","m":"②","c":"A","tp":"소송사기"},{"y":2023,"e":"국가직 9급","qn":17,"i":"N92023-17-3","t":"피고인이 허위의 증거를 조작하는 등의 적극적인 사술을 사용하지 아니한 채 기한 미도래의 채권에 대해 단지 즉시 지급을 구하는 취지의 지급명령신청을 한 경우, 이는 법원에 대한 기망행위에 해당하지 아니한다.","ox":"O","m":"③","c":"A","tp":"소송사기"},{"y":2023,"e":"국가직 9급","qn":17,"i":"N92023-17-4","t":"부동산등기부상 소유자로 등기된 적이 있는 자가 자기 이후 소유권이전등기를 경료한 등기명의인들을 상대로 허위 사실을 주장하면서 그들 명의의 소유권이전등기의 말소를 구하는 소송을 제기한 경우 사기죄의 실행의 착수가 인정된다.","ox":"O","m":"④","c":"A","tp":"소송사기"},{"y":2023,"e":"국가직 9급","qn":19,"i":"N92023-19-1","t":"본범 이외의 자인 피고인이 본범이 절취한 차량이라는 정을 알면서도 본범의 강도행위를 위하여 그 차량을 운전해 준 경우, 강도예비죄의 고의는 별론으로 장물운반의 고의는 인정되지 않는다고 봄이 상당하다.","ox":"X","m":"①","c":"A","tp":"재산범죄"},{"y":2023,"e":"국가직 9급","qn":19,"i":"N92023-19-2","t":"채권 담보를 위하여 장래에 부동산의 소유권을 이전하기로 하는 내용의 대물변제예약에서, 채무자가 약정의 내용에 좇은 이행을 하여야 할 채무는 특별한 사정이 없는 한 자기의 사무에 해당하는 것이 원칙이다.","ox":"O","m":"②","c":"A","tp":"재산범죄"},{"y":2023,"e":"국가직 9급","qn":19,"i":"N92023-19-3","t":"피고인이 중간생략등기형 명의신탁의 방식으로 자신의 처에게 등기명의를 신탁하여 놓은 점포에 자물쇠를 채워 점포의 임차인을 출입하지 못하게 한 경우, 그 점포는 권리행사방해죄의 객체인 자기의 물건에 해당하지 아니한다.","ox":"O","m":"③","c":"A","tp":"재산범죄"},{"y":2023,"e":"국가직 9급","qn":19,"i":"N92023-19-4","t":"경리직원이 회사의 기존 장부를 새로운 장부로 이기하는 과정에서 누계 등을 잘못 기재하자 그 부분을 찢어버리고 계속하여 종전장부의 기재내용을 모두 이기한 경우, 특별한 사정이 없는 한 그 찢어버린 부분은 손괴죄의 객체인 재물로 볼 수 없다.","ox":"O","m":"④","c":"A","tp":"재산범죄"},{"y":2023,"e":"국가직 9급","qn":20,"i":"N92023-20","t":"甲의 ㉡행위는 현금카드 사용권한 있는 자의 정당한 사용에 의한 것으로서 현금자동지급기 관리자의 의사에 반하거나 기망행위 및 그에 따른 처분행위가 없었으므로 별도로 절도죄나 사기죄의 구성요건에 해당하지 않는다.","c":"A","mc":{"s":"甲의 ㉡행위는 현금카드 사용권한 있는 자의 정당한 사용에 의한 것으로서 현금자동지급기 관리자의 의사에 반하거나 기망행위 및 그에 따른 처분행위가 없었으므로 별도로 절도죄나 사기죄의 구성요건에 해당하지 않는다.","d":"다음 사례에 대한 설명으로 옳은 것만을 모두 고르면? 甲은 ㉠ 권한 없이 A회사의 아이디와 패스워드를 입력하여 인터넷뱅킹에 접속한 다음 A회사의 예금계좌로부터 자신의 예금계좌로 합계 180,500,000원을 이체하는 내용의 정보를 입력하여 자신의 예금액을 증액시켰고, ㉡이후 자신의 해당 계좌에 연결된 자신의 현금카드를 사용하여 현금자동지급기에서 현금을 인출하였다.\nㄱ. 甲의 ㉠행위는 컴퓨터등사용사기죄를 구성한다.\nㄴ.\nㄷ. 甲이 ㉡행위로 인출한 현금은 ㉠행위로 취득한 예금채권에 기초한 것으로서 당초의 현금과 물리적인 동일성은 상실되었지만 액수에 의하여 표시되는 금전적 가치에는 아무런 변동이 없으므로 장물로서의 성질이 그대로 유지된다.\nㄹ. 甲이 ㉡행위로 돈을 인출하였다면 장물을 금융기관에 예치하였다가 인출한 것으로 볼 수 있어 장물취득죄가 성립한다.","o":["ㄱ, ㄴ","ㄱ, ㄹ","ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㄹ"],"a":1}},{"y":2024,"e":"국가직 9급","qn":15,"i":"N92024-15-1","t":"타인의 재물을 보관하는 사람이 단순히 반환을 거부한 사실만으로 횡령죄가 성립하는 것은 아니며, 반환거부의 이유 및 주관적인 의사 등을 종합하여 반환거부행위가 횡령행위와 같다고 볼 수 있을 정도이어야만 횡령죄가 성립할 수 있다.","ox":"O","m":"①","c":"A","tp":"횡령과 배임의 죄"},{"y":2024,"e":"국가직 9급","qn":15,"i":"N92024-15-2","t":"저당권설정계약에 따라 채권자에게 저당권설정의무를 부담하는 채무자가 제3자에게 먼저 담보물에 관한 저당권을 설정하거나 담보물을 양도하는 등으로 채권자의 채권실현에 위험을 초래 하더라도 배임죄가 성립한다고 할 수 없다.","ox":"O","m":"②","c":"A","tp":"횡령과 배임의 죄"},{"y":2024,"e":"국가직 9급","qn":15,"i":"N92024-15-3","t":"건물의 임차인이 임대인에 대한 임대차보증금반환채권을 제3자에게 양도하였는데도 임대인에게 채권양도 통지를 하지 않고 임대인으로부터 남아 있던 임대차보증금을 반환받아 보관하던 중 이를 개인적인 용도로 사용하면, 채권을 양수한 제3자를 피해자로 하는 횡령죄가 성립한다.","ox":"X","m":"③","c":"A","tp":"횡령과 배임의 죄"},{"y":2024,"e":"국가직 9급","qn":15,"i":"N92024-15-4","t":"주식회사의 대표이사가 대표권을 남용하는 등 그 임무에 위배하여 회사 명의로 의무를 부담하는 행위를 하더라도 상대방이 대표권 남용 사실을 알았거나 알 수 있었던 경우, 그 의무부담행위로 인하여 실제로 채무의 이행이 이루어졌다거나 회사가 민법상 불법행위책임을 부담하게 되었다는 등의 사정이 없는 이상 배임죄의 기수에 이른 것은 아니다.","ox":"O","m":"④","c":"A","tp":"횡령과 배임의 죄"},{"y":2024,"e":"국가직 9급","qn":16,"i":"N92024-16-1","t":"횡령죄의 교사범이 피교사자가 횡령한 물건을 그 사정을 알면서 취득하면 별도로 장물취득죄가 성립한다.","ox":"O","m":"①","c":"A","tp":"장물죄"},{"y":2024,"e":"국가직 9급","qn":16,"i":"N92024-16-2","t":"보수를 받고 본범을 위하여 일시 사용할 목적으로 장물을 건네받은 경우에는 장물을 취득한 것으로 볼 수 없다.","ox":"O","m":"②","c":"A","tp":"장물죄"},{"y":2024,"e":"국가직 9급","qn":16,"i":"N92024-16-3","t":"재산범죄를 저지른 이후에 별도의 재산범죄의 구성요건에 해당 하는 사후행위가 있었다면, 비록 그 행위가 불가벌적 사후행위로서 처벌의 대상이 되지 않는다 할지라도 그 사후행위로 인하여 취득한 물건은 장물이 될 수 있다.","ox":"O","m":"③","c":"A","tp":"장물죄"},{"y":2024,"e":"국가직 9급","qn":16,"i":"N92024-16-4","t":"장물죄에 있어서 본범의 국적ㆍ주소, 물건 소재지, 행위지 등이 외국과 관련되어 있어 그 행위에 대하여 우리 형법이 적용되지 아니하는 경우, 본범의 행위에 관한 법적 평가는 국제사법에 따른 준거법을 기준으로 하여야 한다.","ox":"X","m":"④","c":"A"},{"y":2024,"e":"국가직 9급","qn":19,"i":"N92024-19-1","t":"타인의 명의를 모용하여 발급받은 신용카드의 번호와 그 비밀번호를 이용하여 ARS 전화서비스나 인터넷 등을 통하여 신용대출을 받는 방법으로 재산상 이익을 취득하는 행위는 컴퓨터등사용사기죄에 해당한다.","ox":"O","m":"①","c":"A","tp":"신용카드 관련 범죄"},{"y":2024,"e":"국가직 9급","qn":19,"i":"N92024-19-2","t":"대금결제의 의사와 능력이 없으면서도 카드회사를 기망하여 신용카드를 발급받고 이를 사용한 경우, 이는 피해자인 카드회사의 기망당한 의사표시에 따른 카드발급에 터 잡아 이루어지는 사기의 포괄일죄에 해당한다.","ox":"O","m":"②","c":"A","tp":"신용카드 관련 범죄"},{"y":2024,"e":"국가직 9급","qn":19,"i":"N92024-19-3","t":"타인의 명의를 모용하여 신용카드를 발급받은 후 그 신용카드를 사용하여 현금자동지급기에서 현금대출을 받는 행위는, 카드회사에 의하여 미리 포괄적으로 허용된 행위라 할 수 없고 별도의 절도죄에 해당한다.","ox":"O","m":"③","c":"A","tp":"신용카드 관련 범죄"},{"y":2024,"e":"국가직 9급","qn":19,"i":"N92024-19-4","t":"예금주인 현금카드 소유자로부터 일정한 금액의 현금을 인출해 오라는 부탁을 받으면서, 건네받은 현금카드로 위임받은 금액을 초과하여 현금을 인출하고 그 차액 상당액의 현금에 대한 점유를 취득한 경우 횡령죄에 해당한다.","ox":"X","m":"④","c":"A","tp":"신용카드 관련 범죄"},{"y":2024,"e":"국가직 9급","qn":20,"i":"N92024-20","t":"손괴에 대한 설명으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"손괴에 대한 설명으로 옳은 것만을 모두 고르면?","d":"ㄱ. 재물을 절취하기 위해 야간에 피해자들이 운영하는 식당의 창문과 방충망을 물리적 훼손 없이 창틀에서 분리하여 놓고 침입한 행위는 특수절도죄의 손괴에 해당한다.\nㄴ. 다른 기관에 접수되어 있는 자기명의의 문서에 대하여 함부로 이를 무효화시켜 그 용도에 사용하지 못하게 하였다면 문서손괴죄의 손괴에 해당한다.\nㄷ. 자동문을 자동으로 작동하지 않고 수동으로만 개폐가 가능 하게 하여 일시적으로 자동잠금장치로서 역할을 할 수 없게 한 경우에는 재물손괴죄의 손괴에 해당한다.\nㄹ. 주차되어 있는 차량의 앞에 철근콘크리트 구조물을, 뒤에 굴삭기 크러셔를 바짝 붙여 놓아 해당 차량의 차주가 17 ～ 18시간 동안 차량을 운행할 수 없게 한 행위는 재물 손괴죄의 ‘재물의 효용을 해한 경우’에 해당한다.","o":["ㄱ, ㄴ","ㄴ, ㄷ","ㄷ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":4}},{"y":2025,"e":"국가직 9급","qn":14,"i":"N92025-14-1","t":"지입차주가 지입회사로부터 할부로 지입회사 소유의 자동차를 매수하면서 해당 자동차에 관하여 지입계약을 체결한 경우, 특별한 사정이 없는 한 지입차주가 그 할부대금을 완납하기 전까지는 지입차량을 지입차주의 실질적 재산이라고 보기 어려우므로, 지입 계약이 체결되었다는 사실만으로 곧바로 지입회사 운영자가 지입 차주와의 관계에서 지입차량에 관한 재산상 사무를 맡아 처리하는 ‘타인의 사무를 처리하는 자’에 해당하지 않는다.","ox":"O","m":"①","c":"A","tp":"횡령과 배임의 죄"},{"y":2025,"e":"국가직 9급","qn":14,"i":"N92025-14-2","t":"회사원이 스스로의 이익을 위하여 이용할 목적으로 재직 중에 영업비밀을 경쟁업체에 유출하거나 무단으로 반출한 경우, 그 유출 또는 반출행위 시에 업무상배임죄의 실행에 착수한 것일 뿐 기수에 도달한 것으로 볼 수 없다.","ox":"X","m":"②","c":"A","tp":"횡령과 배임의 죄"},{"y":2025,"e":"국가직 9급","qn":14,"i":"N92025-14-3","t":"채권양도인이 채무자에게 채권양도 통지를 하는 등으로 채권 양도의 대항요건을 갖추어 주지 않은 채 채무자로부터 채권을 추심하여 금전을 수령하여 임의로 처분한 경우, 횡령죄는 성립하지 않는다.","ox":"O","m":"③","c":"A","tp":"횡령과 배임의 죄"},{"y":2025,"e":"국가직 9급","qn":14,"i":"N92025-14-4","t":"타인의 재물을 보관하는 자가 보관하고 있는 재물을 영득할 의사로 은닉하였다면 이는 횡령죄를 구성하는 것이고 채권자들의 강제집행을 면탈하는 결과를 가져온다 하여 이와 별도로 강제 집행면탈죄를 구성하는 것은 아니다.","ox":"O","m":"④","c":"A","tp":"횡령과 배임의 죄"}],"7":[{"y":2015,"e":"국가직 9급","qn":3,"i":"N92015-03-1","t":"행위자에게 유죄의 재판을 하지 아니할 때에도 몰수만을 선고할 수 있으므로 실체판단에 들어가 공소사실을 인정하는 경우가 아닌 면소의 경우에도 원칙적으로 몰수할 수 있다.","ox":"X","m":"①","c":"A","tp":"몰수 및 추징"},{"y":2015,"e":"국가직 9급","qn":3,"i":"N92015-03-2","t":"공범자의 소유물은 그의 소추여부를 불문하고 몰수할 수 있다.","ox":"O","m":"②","c":"A","tp":"몰수 및 추징"},{"y":2015,"e":"국가직 9급","qn":3,"i":"N92015-03-3","t":"범죄행위로 인하여 주식을 취득하면서 그 대가를 지급하였더라도 그 주식 자체가 몰수되어야 하지만, 주식이 이미 처분되고 없어 그 가액상당을 추징할 때에도 대가로 지급한 금원을 뺀 나머지를 추징하여야 하는 것은 아니다.","ox":"O","m":"③","c":"A","tp":"몰수 및 추징"},{"y":2015,"e":"국가직 9급","qn":3,"i":"N92015-03-4","t":"몰수대상물건이 압수되어 있는가 하는 점 및 압수가 적법한 절차에 의하여 이루어졌는가 하는 점은 몰수의 요건이 아니다.","ox":"O","m":"④","c":"A","tp":"몰수 및 추징"},{"y":2015,"e":"국가직 9급","qn":16,"i":"N92015-16-1","t":"甲이 직무를 집행하는 공무원에 대하여 위험한 물건을 휴대 하여 고의로 상해한 경우 특수공무집행방해치상죄와 별도로 폭력행위 등 처벌에 관한 법률 위반(집단·흉기 등 상해)죄는 성립하지 않는다.","ox":"O","m":"①","c":"A"},{"y":2015,"e":"국가직 9급","qn":16,"i":"N92015-16-2","t":"공무원 甲이 위법사실을 발견하고도 직무상 의무에 따른 적절한 조치를 취하지 아니하고 위법사실을 적극적으로 은폐할 목적으로 허위공문서를 작성·행사한 경우 허위공문서작성죄 및 동행사죄와 직무유기죄의 실체적 경합이다.","ox":"X","m":"②","c":"A"},{"y":2015,"e":"국가직 9급","qn":16,"i":"N92015-16-3","t":"공무원 甲이 직무집행의 의사없이 또는 직무처리와 대가적 관계없이 乙을 공갈하자 乙이 외포심을 느껴 재물을 교부한 경우 甲에게는 공갈죄가 성립하지만 乙에게는 뇌물공여죄가 성립할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2015,"e":"국가직 9급","qn":16,"i":"N92015-16-4","t":"甲과 乙이 A의 돈을 빼앗자고 공모한 후 A를 강제로 승용차에 태우고 가면서 돈을 강취하고 상해를 가한 뒤에도 계속하여 상당한 거리를 진행하다가 교통사고로 인해 감금행위가 중단 되었다면 강도상해죄와 감금죄의 실체적 경합이다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"국가직 9급","qn":17,"i":"N92016-17-1","t":"피고인이 범죄사실을 자백하지 않고 부인한 경우 선고유예의 요건 중 ‘개전의 정상이 현저한 때’에 해당하지 않으므로 선고유예를 선고할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"국가직 9급","qn":17,"i":"N92016-17-2","t":"선고유예의 실효사유인 ‘형의 선고유예를 받은 자가 자격정지 이상의 형에 처한 전과가 발견된 때’란 형의 선고유예의 판결이 확정된 후에 전과가 발견된 경우를 말한다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"국가직 9급","qn":17,"i":"N92016-17-3","t":"형의 선고를 유예하는 판결을 하는 경우에 그 판결이유에서 선고할 형의 종류와 양을 정할 필요는 없고, 선고유예가 실효되는 경우에 형의 종류와 양을 정하게 된다.","ox":"X","m":"③","c":"A"},{"y":2016,"e":"국가직 9급","qn":17,"i":"N92016-17-4","t":"형의 선고유예를 받은 날로부터 1년을 경과한 때에는 면소된 것으로 간주한다.","ox":"X","m":"④","c":"A"},{"y":2016,"e":"국가직 9급","qn":19,"i":"N92016-19-1","t":"계속적으로 무면허운전을 할 의사를 가지고 여러 날에 걸쳐 무면허운전행위를 반복한 경우 도로교통법 위반죄의 포괄일죄로 볼 수 없다.","ox":"O","m":"①","c":"A","tp":"죄수"},{"y":2016,"e":"국가직 9급","qn":19,"i":"N92016-19-2","t":"피해자를 위협하여 항거불능케 한 후 1회 간음하고 2백미터쯤 오다가 다시 1회 간음한 경우 강간죄의 단순일죄가 성립한다.","ox":"O","m":"②","c":"A","tp":"죄수"},{"y":2016,"e":"국가직 9급","qn":19,"i":"N92016-19-3","t":"절도범이 체포 면탈의 목적으로 경찰관에게 폭행을 가한 경우 준강도죄와 공무집행방해죄의 상상적 경합이 성립한다.","ox":"O","m":"③","c":"A","tp":"죄수"},{"y":2016,"e":"국가직 9급","qn":19,"i":"N92016-19-4","t":"동일한 기회에 동일한 범죄의 태양으로 수회에 걸친 예금 인출행위로 수인의 피해자에 대해 업무상횡령행위를 행한 경우 업무상횡령죄의 포괄일죄가 성립한다.","ox":"X","m":"④","c":"A","tp":"죄수"},{"y":2017,"e":"국가직 9급","qn":7,"i":"N92017-07-1","t":"甲이 공무원 A에게 승용차 대금 명목으로 1,400만 원을 뇌물로 제공하기로 약속하였다면 甲으로부터 그 뇌물로 제공하기로 약속된 승용차 대금 명목의 금품을 추징해야 한다.","ox":"X","m":"①","c":"A","tp":"몰수와 추징"},{"y":2017,"e":"국가직 9급","qn":7,"i":"N92017-07-2","t":"甲이 A로 하여금 사기도박에 참여하도록 유인하기 위하여 고액의 수표를 제시해 보였다면 그 수표를 직접적으로 도박 자금으로 사용하지 않았더라도 몰수할 수 있다.","ox":"O","m":"②","c":"A","tp":"몰수와 추징"},{"y":2017,"e":"국가직 9급","qn":7,"i":"N92017-07-3","t":"수뢰자가 증뢰자로부터 뇌물을 교부받아 그대로 보관하였다가 증뢰자에게 뇌물 그 자체를 반환한 경우에는 증뢰자로부터 몰수 또는 추징한다.","ox":"O","m":"③","c":"A","tp":"몰수와 추징"},{"y":2017,"e":"국가직 9급","qn":7,"i":"N92017-07-4","t":"몰수의 취지가 범죄에 의한 이득의 박탈을 그 목적으로 하는 것이고 추징도 이러한 몰수의 취지를 관철하기 위한 것인 경우에는 추징가액의 산정은 재판선고시의 가격을 기준으로 하여야 한다.","ox":"O","m":"④","c":"A","tp":"몰수와 추징"},{"y":2017,"e":"국가직 9급","qn":8,"i":"N92017-08","t":"다음 사례에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"다음 사례에 대한 설명으로 옳은 것은?","d":"(다툼이 있는 경우 판례에 의함) 예비군중대장 甲이 예비군훈련을 받지 않게 해주는 대가로 乙로부터 180,000원을 교부받고 乙이 예비군훈련에 불참 하였음에도 불구하고 참석한 것처럼 예비군 중대학급편성부에 ‘참’이라는 도장을 찍어 허위공문서를 작성하고 이를 예비군 중대 사무실에 비치한 경우, 甲에게는 수뢰후부정처사죄, 허위공문서작성죄, 허위작성공문서행사죄가 성립한다.","o":["허위공문서작성죄와 허위작성공문서행사죄는 수뢰후부정처사죄와 각각 실체적 경합관계이다.","허위공문서작성죄와 허위작성공문서행사죄는 기능적 관점에서 목적과 수단의 관계에 있으므로 상상적 경합관계이다.","가장 중한 죄인 수뢰후부정처사죄를 경합범가중하여 처벌해야 한다.","연결효과이론은 위 3가지 죄 모두를 상상적 경합관계로 인정 하는 이론이다."],"a":4}},{"y":2018,"e":"국가직 9급","qn":19,"i":"N92018-19-1","t":"법정형에 징역형과 벌금형이 선택형으로 규정되어 있는 범죄에서 벌금형을 선택하여 처벌하는 경우에 노역장 유치기간은 법정형에서 정한 징역형의 상한을 초과하여 정할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"국가직 9급","qn":19,"i":"N92018-19-2","t":"벌금을 선고할 때에는 납입하지 아니하는 경우의 유치기간을 정하여 동시에 선고하여야 한다.","ox":"O","m":"②","c":"A","tp":"벌금형"},{"y":2018,"e":"국가직 9급","qn":19,"i":"N92018-19-3","t":"벌금을 납입하지 아니하는 자에 대한 노역장 유치기간은 벌금액수가 아무리 많더라도 3년을 초과할 수 없다.","ox":"O","m":"③","c":"A","tp":"벌금형"},{"y":2018,"e":"국가직 9급","qn":19,"i":"N92018-19-4","t":"선고하는 벌금이 5억 원 이상 50억 원 미만인 경우에는 500일 이상의 유치기간을 정하여야 한다.","ox":"O","m":"④","c":"A","tp":"벌금형"},{"y":2019,"e":"국가직 9급","qn":15,"i":"N92019-15","t":"형법 상 몰수의 대상은 범죄의 실행행위 자체에 사용한 물건에만 한정되고, 실행행위 착수 전 또는 실행행위 종료 후의 행위에 사용한 물건은 이에 해당하지 않는다.","c":"A","mc":{"s":"형법 상 몰수의 대상은 범죄의 실행행위 자체에 사용한 물건에만 한정되고, 실행행위 착수 전 또는 실행행위 종료 후의 행위에 사용한 물건은 이에 해당하지 않는다.","d":"다음 설명 중 옳지 않은 것만을 모두 고르면? (다툼이 있는 경우 판례에 의함)\nㄱ.\nㄴ. 하나의 죄에 대하여 징역형과 벌금형을 병과하는 경우 특별한 규정이 없더라도 징역형만을 작량감경하고 벌금형에는 작량감경을 하지 않을 수 있다.\nㄷ. 선고유예는 선고할 형이 1년 이하의 징역이나 금고, 자격정지 또는 벌금의 형인 경우에 한하고 구류형에 대하여는 선고를 유예할 수 없다.\nㄹ. 판결선고 전의 구금일수는 전부 또는 그 일부를 유기징역, 유기금고, 벌금이나 과료에 관한 유치 또는 구류에 산입한다.","o":["ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄴ, ㄹ","ㄱ, ㄷ, ㄹ"],"a":3}},{"y":2019,"e":"국가직 9급","qn":18,"i":"N92019-18-1","t":"절도범이 체포를 면탈할 목적으로 자신을 체포하려는 여러 명의 피해자에게 같은 기회에 폭행을 가하여 그 중 1인에게만 상해를 가하였다면 하나의 강도상해죄가 성립한다.","ox":"O","m":"①","c":"A","tp":"죄수"},{"y":2019,"e":"국가직 9급","qn":18,"i":"N92019-18-2","t":"절도범으로부터 장물보관 의뢰를 받은 자가 그 정을 알면서 장물을 인도받아 보관하고 있다가 임의 처분한 때에는 장물 보관죄가 성립하고 그 후의 횡령행위에 대해서는 횡령죄가 성립하지 않는다.","ox":"O","m":"②","c":"A","tp":"죄수"},{"y":2019,"e":"국가직 9급","qn":18,"i":"N92019-18-3","t":"피해자 명의의 신용카드를 부정사용하여 현금자동인출기에서 현금을 인출하고 이를 취득하였다면 신용카드부정사용죄와 절도죄가 성립하고 양죄는 실체적 경합관계에 있다.","ox":"O","m":"③","c":"A","tp":"죄수"},{"y":2019,"e":"국가직 9급","qn":18,"i":"N92019-18-4","t":"공무원이 직무관련자에게 제3자와 계약을 체결하도록 요구하여 계약을 체결하게 한 행위가 제3자뇌물수수죄와 직권남용권리 행사방해죄에 모두 해당하는 경우 양죄는 실체적 경합관계에 있다.","ox":"X","m":"④","c":"A","tp":"죄수"},{"y":2020,"e":"국가직 9급","qn":8,"i":"N92020-08-1","t":"상품을 절취하여 자신의 승용차에 싣고 간 경우, 그 승용차가 단순한 교통수단을 넘어 장물의 운반에 사용한 것이라고 인정된다면 이를 범죄행위에 제공한 물건으로 보아 몰수할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"국가직 9급","qn":8,"i":"N92020-08-2","t":"몰수나 추징이 공소사실과 관련이 있는 경우 그 공소사실에 관하여 이미 공소시효가 완성된 경우에도 몰수나 추징을 할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2020,"e":"국가직 9급","qn":8,"i":"N92020-08-3","t":"피고인의 소유물은 물론 공범자의 소유물도 몰수할 수 있으나, 공범자의 소유물은 공범자가 소추된 경우에 한하여 몰수할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2020,"e":"국가직 9급","qn":8,"i":"N92020-08-4","t":"집행을 종료함으로써 효력을 상실한 압수·수색영장에 기하여 다시 압수·수색을 실시하면서 몰수대상물건을 압수한 경우, 압수 자체가 위법하므로 그러한 압수물의 몰수 역시 효력이 없다.","ox":"X","m":"④","c":"A"},{"y":2020,"e":"국가직 9급","qn":20,"i":"N92020-20","t":"형을 임의적으로 감경 또는 면제할 수 있는 경우만을 모두 고르면?","c":"A","mc":{"s":"형을 임의적으로 감경 또는 면제할 수 있는 경우만을 모두 고르면?","d":"ㄱ. 자구행위가 그 정도를 초과하였지만 정황에 참작할 사유가 있는 경우\nㄴ. 실행 수단의 착오로 인하여 결과의 발생이 불가능하지만 위험성이 인정되는 경우\nㄷ. 직계혈족, 배우자, 동거친족 또는 동거가족의 재물을 절취한 경우\nㄹ. 피해자의 의사에 반하여 처벌할 수 없는 죄에 있어서 피해자에게 자복(自服)한 경우\nㅁ. 범인이 자의로 실행에 착수한 행위를 중지하거나 그 행위로 인한 결과의 발생을 방지한 경우","o":["ㄱ, ㄷ","ㄴ, ㅁ","ㄱ, ㄴ, ㄹ","ㄴ, ㄹ, ㅁ"],"a":3}},{"y":2021,"e":"국가직 9급","qn":9,"i":"N92021-09-1","t":"수인의 피해자에 대하여 각 피해자별로 기망행위를 하여 각각 재물을 편취한 경우에도 그 범의가 단일하고 범행방법이 동일한 경우에는 사기죄의 포괄일죄가 성립한다.","ox":"X","m":"①","c":"A"},{"y":2021,"e":"국가직 9급","qn":9,"i":"N92021-09-2","t":"동일한 저작권자의 여러 개의 저작물에 대한 침해행위가 단일하고 동일한 범의 아래 행하여졌다면 저작권법 위반의 포괄일죄가 성립한다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"국가직 9급","qn":9,"i":"N92021-09-3","t":"폭력행위 등 처벌에 관한 법률 제4조제1항에서는 그 법에 규정된 범죄행위를 목적으로 하는 단체를 구성하거나 이에 가입하는 행위 또는 구성원으로 활동하는 행위를 처벌하도록 규정하고 있으므로, 범죄단체를 구성하거나 이에 가입한 자가 나아가 구성원으로 활동하는 경우에는 폭력행위 등 처벌에 관한 법률 위반의 포괄일죄가 성립한다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"국가직 9급","qn":9,"i":"N92021-09-4","t":"비의료인이 의료기관을 개설하여 운영하는 도중 개설자 명의를 다른 의료인으로 변경한 경우에는 그 범의가 단일하고 범행 방법이 종전과 동일하므로 의료법 위반의 포괄일죄가 성립한다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"국가직 9급","qn":17,"i":"N92021-17-1","t":"판결선고 후 누범인 것이 발각된 때에는 그 선고한 형을 통산하여 다시 형을 정하여야 한다. 단, 선고한 형의 집행을 종료하거나 그 집행이 면제된 후에는 예외로 한다.","ox":"X","m":"①","c":"A","tp":"형법 상 형(刑)"},{"y":2021,"e":"국가직 9급","qn":17,"i":"N92021-17-2","t":"집행유예의 선고를 받은 자가 유예기간 중 벌금 이상의 형을 선고받아 그 판결이 확정된 때에는 집행유예의 선고는 효력을 잃는다.","ox":"X","m":"②","c":"A","tp":"형법 상 형(刑)"},{"y":2021,"e":"국가직 9급","qn":17,"i":"N92021-17-3","t":"가석방의 처분을 받은 자가 감시에 관한 규칙을 위배하거나 보호관찰의 준수사항을 위반한 때에는 가석방처분을 취소한다.","ox":"X","m":"③","c":"A","tp":"형법 상 형(刑)"},{"y":2021,"e":"국가직 9급","qn":17,"i":"N92021-17-4","t":"징역 또는 금고의 집행을 종료하거나 집행이 면제된 자가 피해자의 손해를 보상하고 자격정지 이상의 형을 받음이 없이 7년을 경과한 때에는 본인 또는 검사의 신청에 의하여 그 재판의 실효를 선고할 수 있다.","ox":"O","m":"④","c":"A","tp":"형법 상 형(刑)"},{"y":2023,"e":"국가직 9급","qn":4,"i":"N92023-04-1","t":"형을 가중ㆍ감경할 사유가 경합하는 경우에는 각칙 조문에 따른 가중, 형법 제34조제2항에 따른 가중, 누범 가중, 경합범 가중, 법률상 감경, 정상참작감경의 순으로 한다.","ox":"X","m":"①","c":"A","tp":"형벌"},{"y":2023,"e":"국가직 9급","qn":4,"i":"N92023-04-2","t":"판결선고전의 구금일수는 그 전부를 유기징역, 유기금고, 벌금이나 과료에 관한 유치 또는 구류에 산입한다.","ox":"O","m":"②","c":"A","tp":"형벌"},{"y":2023,"e":"국가직 9급","qn":4,"i":"N92023-04-3","t":"형을 병과할 경우에도 형의 전부 또는 일부에 대하여 선고를 유예할 수 있다.","ox":"O","m":"③","c":"A","tp":"형벌"},{"y":2023,"e":"국가직 9급","qn":4,"i":"N92023-04-4","t":"형의 선고를 유예하는 경우에 재범방지를 위하여 지도 및 원호가 필요한 때에는 보호관찰을 받을 것을 명할 수 있다.","ox":"O","m":"④","c":"A","tp":"형벌"},{"y":2023,"e":"국가직 9급","qn":16,"i":"N92023-16-1","t":"공범자의 소유물도 몰수할 수 있지만, 적어도 그 공범자가 소추되어야만 가능하다.","ox":"X","m":"①","c":"A","tp":"몰수와 추징"},{"y":2023,"e":"국가직 9급","qn":16,"i":"N92023-16-2","t":"몰수는 반드시 압수되어 있는 물건에 대하여만 하는 것이 아니므로 몰수대상물건이 압수되어 있는가 하는 점 및 적법한 절차에 의하여 압수되었는가 하는 점은 몰수의 요건이 아니다.","ox":"O","m":"②","c":"A","tp":"몰수와 추징"},{"y":2023,"e":"국가직 9급","qn":16,"i":"N92023-16-3","t":"몰수를 선고하기 위해서는 몰수의 요건이 공소가 제기된 공소사실과 관련되어 있어야 하고, 공소가 제기되지 않은 별개의 범죄사실을 법원이 인정하여 그에 관하여 몰수나 추징을 선고하는 것은 허용되지 않는다.","ox":"O","m":"③","c":"A","tp":"몰수와 추징"},{"y":2023,"e":"국가직 9급","qn":16,"i":"N92023-16-4","t":"몰수하기 불가능한 때에 추징하여야 할 가액은 범인이 그 물건을 보유하고 있다가 몰수의 선고를 받았더라면 잃게 될 이득상당액을 초과하여서는 아니 된다.","ox":"O","m":"④","c":"A","tp":"몰수와 추징"},{"y":2024,"e":"국가직 9급","qn":12,"i":"N92024-12-1","t":"국가정보원 직원이 동일한 사안에 관한 일련의 직무집행 과정에서 단일하고 계속된 범의로 일정 기간 계속하여 저지른 직권남용 행위에 대하여는 설령 그 상대방이 수인이라고 하더라도 직권남용 권리행사방해죄의 포괄일죄가 성립할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"국가직 9급","qn":12,"i":"N92024-12-2","t":"행정소송사건의 같은 심급이라도 변론기일을 달리하여 수차 증인으로 나가 수 개의 허위진술을 하였다면, 최초에 한 선서의 효력을 유지시킨 후 증언하였다고 하더라도 수 개의 위증죄가 성립한다.","ox":"X","m":"②","c":"A","tp":"포괄일죄"},{"y":2024,"e":"국가직 9급","qn":12,"i":"N92024-12-3","t":"같은 날 무면허운전 행위를 여러 차례 반복하였다면 그 범의의 단일성 내지 계속성이 인정되지 않거나 범행 방법 등이 동일하지 않은 경우라도 각 무면허운전 행위를 통틀어 포괄일죄로 처단 하여야 한다.","ox":"X","m":"③","c":"A"},{"y":2024,"e":"국가직 9급","qn":12,"i":"N92024-12-4","t":"포괄일죄로 되는 개개의 범죄행위가 법 개정의 전후에 걸쳐서 행하여진 경우에는 신ㆍ구법의 법정형의 경중을 비교하여 행위자에게 유리한 법을 적용하여 포괄일죄로 처단하여야 한다.","ox":"X","m":"④","c":"A"},{"y":2024,"e":"국가직 9급","qn":13,"i":"N92024-13-1","t":"집행유예의 선고를 받은 자가 유예기간 중 고의 또는 과실로 범한 죄로 금고 이상의 실형을 선고받아 그 판결이 확정된 때에는 집행유예의 선고는 효력을 잃는다.","ox":"X","m":"①","c":"A","tp":"집행유예와 선고유예"},{"y":2024,"e":"국가직 9급","qn":13,"i":"N92024-13-2","t":"실형을 선고받고 집행종료나 집행면제 후 3년이 지나지 않은 시점에서 범한 죄에 대하여 형을 선고하는 경우뿐만 아니라, 집행유예 기간 중에 범한 죄에 대하여 형을 선고할 때 이미 집행유예가 실효 또는 취소된 경우도 형법 제62조제1항 단서의 집행유예 결격사유에 해당한다.","ox":"O","m":"②","c":"A","tp":"집행유예와 선고유예"},{"y":2024,"e":"국가직 9급","qn":13,"i":"N92024-13-3","t":"형의 선고를 유예하는 경우에 재범방지를 위하여 지도 및 원호가 필요한 때에는 보호관찰을 받을 것을 명하여야 하며, 보호관찰을 명한 선고유예를 받은 자가 보호관찰기간 중에 준수사항을 위반 하고 그 정도가 무거운 때에는 유예한 형을 선고하여야 한다.","ox":"X","m":"③","c":"A","tp":"집행유예와 선고유예"},{"y":2024,"e":"국가직 9급","qn":13,"i":"N92024-13-4","t":"형의 선고유예를 받은 자에 대해 유예기간 중 자격정지 이상의 형에 처한 전과가 발견된 경우 유예한 형을 선고할 수 없다.","ox":"X","m":"④","c":"A","tp":"집행유예와 선고유예"},{"y":2025,"e":"국가직 9급","qn":11,"i":"N92025-11-1","t":"음주 또는 약물의 영향으로 정상적인 운전이 곤란한 상태에서 자동차를 운전하여 사람을 상해에 이르게 함과 동시에 다른 사람의 재물을 손괴한 때에는 특정범죄가중처벌등에관한법률위반 (위험운전치상)죄 외에 업무상과실 재물손괴로 인한 도로교통법 위반죄가 성립하고, 위 두 죄는 각각 보호법익이 다르므로 실체적 경합관계에 있다.","ox":"X","m":"①","c":"A","tp":"죄수(罪數)"},{"y":2025,"e":"국가직 9급","qn":11,"i":"N92025-11-2","t":"하나의 사건에 관하여 한 번 선서한 증인이 같은 기일에 여러 가지 사실에 관하여 기억에 반하는 허위의 진술을 한 경우 이는 하나의 범죄의사에 의하여 계속하여 허위의 진술을 한 것으로서 포괄하여 1개의 위증죄를 구성한다.","ox":"O","m":"②","c":"A","tp":"죄수(罪數)"},{"y":2025,"e":"국가직 9급","qn":11,"i":"N92025-11-3","t":"절취한 자기앞수표를 음식대금으로 교부하고 거스름돈을 환불 받은 행위는 절도의 불가벌적 사후처분행위로서 사기죄가 되지 아니한다.","ox":"O","m":"③","c":"A","tp":"죄수(罪數)"},{"y":2025,"e":"국가직 9급","qn":11,"i":"N92025-11-4","t":"수인의 피해자에 대해 각각 기망행위를 하여 재물을 편취한 경우에는 범의가 단일하고 범행방법이 동일하더라도 각 피해자의 피해법익은 독립한 것이므로 포괄하여 일죄가 되지 않고 피해자별로 독립한 사기죄가 성립한다.","ox":"O","m":"④","c":"A","tp":"죄수(罪數)"},{"y":2025,"e":"국가직 9급","qn":12,"i":"N92025-12-1","t":"대형할인매장에서 수회 상품을 절취하여 자신의 승용차에 싣고 간 경우, 이 승용차는 형법 제48조제1항제1호에 정한 ‘범죄 행위에 제공한 물건’으로 몰수할 수 있다.","ox":"O","m":"①","c":"A","tp":"몰수와 추징"},{"y":2025,"e":"국가직 9급","qn":12,"i":"N92025-12-2","t":"수인이 공모하여 뇌물을 수수한 경우에 몰수불능으로 그 가액을 추징하려면 어디까지나 개별적으로 추징할 것이며, 수수금품을 개별적으로 알 수 없을 때에는 평등하게 추징할 것이지 피고인 전원으로부터 수수한 금품의 가액을 공동으로 추징할 수 없다.","ox":"O","m":"②","c":"A","tp":"몰수와 추징"},{"y":2025,"e":"국가직 9급","qn":12,"i":"N92025-12-3","t":"甲이 정보통신망을 통하여 음란한 화상 또는 영상을 배포하고, 도박 사이트를 홍보하는 범죄행위에 이용한 웹사이트는 범죄 행위에 제공된 무형의 재산에 해당할 뿐이므로, 그 웹사이트 매각으로 취득한 대가는 형법 제48조제1항제2호, 제48조제2항이 규정한 추징의 대상에 해당하지 않는다.","ox":"O","m":"③","c":"A","tp":"몰수와 추징"},{"y":2025,"e":"국가직 9급","qn":12,"i":"N92025-12-4","t":"몰수나 추징이 공소사실과 관련이 있다면, 그 공소사실에 관하여 이미 공소시효가 완성되어 유죄의 선고를 할 수 없는 경우라도 몰수나 추징을 할 수 있다.","ox":"X","m":"④","c":"A","tp":"몰수와 추징"}],"6":[{"y":2015,"e":"국가직 9급","qn":5,"i":"N92015-05-1","t":"피고인이 포괄일죄 범행의 일부를 실행한 후 공범관계에서 이탈하였으나 다른 공범에 의하여 나머지 범행이 이루어진 경우 피고인이 다른 공범의 범죄실행을 저지하지 않은 이상 관여하지 않은 부분에 대하여도 죄책을 진다.","ox":"O","m":"①","c":"A","tp":"공모․공범관계의 이탈"},{"y":2015,"e":"국가직 9급","qn":5,"i":"N92015-05-2","t":"공모자가 공모에 주도적으로 참여하여 다른 공모자의 실행에 영향을 미친 때에는 범행 저지를 위하여 적극적으로 노력하는 등 실행에 미친 영향력을 제거하지 아니하는 한 공모자가 구속 되었다는 사유만으로 공모관계에서 이탈하였다고 할 수 없다.","ox":"O","m":"②","c":"A","tp":"공모․공범관계의 이탈"},{"y":2015,"e":"국가직 9급","qn":5,"i":"N92015-05-3","t":"교사범이 그 공범관계로부터 이탈하기 위해서는 피교사자가 범죄의 실행행위에 나아가기 전에 교사범에 의하여 형성된 피교사자의 범죄 실행의 결의를 해소해야 한다.","ox":"O","m":"③","c":"A","tp":"공모․공범관계의 이탈"},{"y":2015,"e":"국가직 9급","qn":5,"i":"N92015-05-4","t":"공모공동정범의 공모자 중 1인이 다른 공모자가 실행행위에 이르기 전에 그 공모관계에서 이탈한 때에는 그 이후의 다른 공모자의 행위에 관하여 공동정범으로서의 책임은 지지 않는다고 할 것이고 그 이탈의 표시는 명시적이어야 한다.","ox":"X","m":"④","c":"A","tp":"공모․공범관계의 이탈"},{"y":2015,"e":"국가직 9급","qn":7,"i":"N92015-07-1","t":"범행가담자간에 상명하복 관계가 있는 경우라도 범행에 공동 가공한 이상 공동정범이 성립하는 데 아무런 지장이 없다.","ox":"O","m":"①","c":"A"},{"y":2015,"e":"국가직 9급","qn":7,"i":"N92015-07-2","t":"甲은 전자회사직원 乙이 영업비밀을 경쟁업체에 유출하기 위하여 무단 반출하였다는 사실을 알고 몇 개월 후 乙에게 접근하여 영업비밀을 취득하려고 하였다면 업무상배임죄의 공동정범이 된다.","ox":"X","m":"②","c":"A"},{"y":2015,"e":"국가직 9급","qn":7,"i":"N92015-07-3","t":"이른바 딱지어음들을 발행하여 매매한 甲이 이를 사용한 사기의 실행행위에 직접 관여하지 않았더라도 그 사기범행에 관하여 암묵적, 순차적으로 공모하였다고 볼 수 있다면, 딱지 어음들의 전전유통경로나 중간 소지인들 및 그 기망방법을 구체적으로 몰랐더라도 사기죄의 공동정범이 된다.","ox":"O","m":"③","c":"A"},{"y":2015,"e":"국가직 9급","qn":7,"i":"N92015-07-4","t":"합동절도의 공모에는 참여하였으나 현장에서 실행행위를 직접 분담하지 아니한 자도 그가 현장에서 절도 범행을 실행한 2인 이상의 범인의 행위를 자기 의사의 수단으로 하여 합동절도의 범행을 하였다고 평가할 수 있는 정범성의 표지를 갖추고 있다면 합동절도의 공동정범이 된다.","ox":"O","m":"④","c":"A"},{"y":2015,"e":"국가직 9급","qn":19,"i":"N92015-19","t":"공범에 대한 설명 중 옳은 것(○)과 옳지 않은 것(×)을 순서대로 바르게 나열한 것은?","c":"A","mc":{"s":"공범에 대한 설명 중 옳은 것(○)과 옳지 않은 것(×)을 순서대로 바르게 나열한 것은?","d":"(다툼이 있는 경우 판례에 의함)\nㄱ. 정범의 실행착수 이전에 장래 실행행위를 미필적으로나마 예상하고 이를 용이하게 하기 위하여 방조한 경우에도 그 후 정범이 실행행위에 나아갔다면 종범이 성립할 수 있다.\nㄴ. 법원의 입찰사건에 관한 제반 업무를 담당하는 공무원이 자신이 맡고 있는 입찰사건의 입찰보증금이 사무원에 의해 계속적으로 횡령되고 있는 사실을 알았고, 이를 제지하고 즉시 상관에게 보고하는 등 결과발생을 쉽게 방지할 수 있음에도 불구하고 그 횡령행위를 방지하지 않은 경우 업무상횡령죄의 공동정범이 성립한다.\nㄷ. 강도의 공범자 중 1인이 강도의 기회에 피해자를 살해 하였다면 그는 강도살인기수의 죄책을 지는 것이고 다른 공범자는 고의의 공동이 없었더라도 피해자의 사망이 예견 가능했다면 강도치사의 죄책을 진다.\nㄹ. 내란죄와 같은 목적범의 경우 ‘국헌문란의 목적’을 가진 자가 그러한 목적이 없는 자를 이용하여 내란죄를 실행할 수는 없다. ㄱ ㄴ ㄷ ㄹ","o":["○ × ○ ○","○ × ○ ×","○ ○ × ○","× ○ × ○"],"a":2}},{"y":2016,"e":"국가직 9급","qn":6,"i":"N92016-06-1","t":"대향범은 2인 이상의 서로 대향된 행위의 존재를 필요로 하는 필요적 공범으로서 대향범 간에는 공범에 관한 형법 총칙규정이 적용된다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"국가직 9급","qn":6,"i":"N92016-06-2","t":"甲이 친구인 乙을 교사하여 乙 자신의 아버지를 살해하게 한 경우 乙에게는 존속살인죄의 정범이 성립하고, 甲에게는 보통살인죄의 교사범이 성립한다.","ox":"X","m":"②","c":"A","tp":"공범"},{"y":2016,"e":"국가직 9급","qn":6,"i":"N92016-06-3","t":"甲이 A를 협박하여 A가 스스로 자신의 콧등을 절단하게 한 경우 자상(自傷)은 상해죄의 구성요건에 해당하지 않으므로, 甲에게는 중상해죄의 간접정범이 성립하지 않는다.","ox":"X","m":"③","c":"A","tp":"공범"},{"y":2016,"e":"국가직 9급","qn":6,"i":"N92016-06-4","t":"변호사 아닌 자에게 고용되어 법률사무소의 개설·운영에 관여한 변호사의 행위가 일반적인 형법 총칙상의 공모, 교사 또는 방조에 해당된다고 하더라도 변호사를 변호사 아닌 자의 공범으로서 처벌할 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"국가직 9급","qn":8,"i":"N92016-08","t":"교사범에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"교사범에 대한 설명으로 옳지 않은 것은?","d":"","o":["교사범이 성립하기 위해 교사범의 교사가 정범의 범행에 대한 유일한 조건일 필요는 없다.","교사범의 교사행위에 의하여 피교사자가 범죄 실행을 결의하게 되었다 하더라도 피교사자에게 다른 원인이 있어 범죄를 실행한 경우 교사범은 성립하지 않는다.","사람을 살해할 것을 교사받은 자가 범죄실행을 거부하였다면, 살인을 교사한 자는 살인죄의 예비․음모에 준하여 처벌한다.","교사범이 성립하기 위해서는 교사자의 교사행위와 정범의 실행행위가 있어야 한다. 형 법 2 책형 2 쪽"],"a":2}},{"y":2016,"e":"국가직 9급","qn":20,"i":"N92016-20-1","t":"2인이 범행을 공모하여 실행에 착수한 후 그 중 한 사람이 자의로 중지한 경우 전체범죄가 기수에 이르렀다고 하여도 중지한 자에게는 미수가 성립한다.","ox":"X","m":"①","c":"A","tp":"공범"},{"y":2016,"e":"국가직 9급","qn":20,"i":"N92016-20-2","t":"‘효과 없는 교사’의 경우 교사자와 피교사자를 예비·음모에 준하여 처벌하고, ‘실패한 교사’의 경우 교사자만 예비·음모에 준하여 처벌한다.","ox":"O","m":"②","c":"A","tp":"공범"},{"y":2016,"e":"국가직 9급","qn":20,"i":"N92016-20-3","t":"甲이 乙에게 강도를 교사하였는데 乙이 절도를 범한 경우 甲은 절도죄의 교사범으로 처벌된다.","ox":"X","m":"③","c":"A","tp":"공범"},{"y":2016,"e":"국가직 9급","qn":20,"i":"N92016-20-4","t":"자기의 지휘, 감독을 받는 자를 방조하여 범죄의 결과를 발생하게 한 자는 정범에 정한 형의 장기 또는 다액에 그 2분의 1까지 가중한 형으로 처벌한다.","ox":"X","m":"④","c":"A","tp":"공범"},{"y":2017,"e":"국가직 9급","qn":10,"i":"N92017-10-1","t":"판례는 최근에 “공모자가 공모공동정범으로 인정되기 위해서는 그가 단순히 공모자에 그치는 것이 아니라 범죄에 대한 본질적 기여를 통한 기능적 행위지배가 존재하여야 한다”고 하여 공모공동정범의 성립범위를 제한하는 경향을 보이고 있다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"국가직 9급","qn":10,"i":"N92017-10-2","t":"이른바 ‘승계적 공동정범’의 경우 비록 그 범행에 가담할 때에 이미 종전의 범행을 알았다 하더라도 자신이 가담하기 이전에 타인이 행한 부분에는 죄책을 지지 않는다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"국가직 9급","qn":10,"i":"N92017-10-3","t":"공범자 중의 한 사람이 실행의 착수 이전에 공모관계에서 이탈하였더라도 그 이후 다른 공모자에 의하여 범행이 이루어졌다면 그 이탈자는 공동정범의 죄책을 진다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"국가직 9급","qn":10,"i":"N92017-10-4","t":"실행행위가 종료함과 동시에 범죄가 기수에 이르는 이른바 ‘즉시범’에서는 범죄가 기수에 이르기 이전에 가담하는 경우 에만 공동정범이 성립하고 범죄가 기수에 이른 이후에는 공동정범이 성립될 수 없다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"국가직 9급","qn":9,"i":"N92018-09-1","t":"도박의 습벽이 있는 甲이 도박의 습벽이 없는 A의 도박행위를 방조한 경우 甲에게는 상습도박죄의 방조범이 성립한다.","ox":"O","m":"①","c":"A","tp":"공범과 신분"},{"y":2018,"e":"국가직 9급","qn":9,"i":"N92018-09-2","t":"비신분자인 甲이 신분자인 A의 업무상횡령 행위를 교사하여 A로 하여금 업무상횡령을 하게 한 경우 甲에게는 단순횡령죄의 교사범이 성립하지만 업무상횡령죄의 교사범의 형으로 처벌된다.","ox":"X","m":"②","c":"A","tp":"공범과 신분"},{"y":2018,"e":"국가직 9급","qn":9,"i":"N92018-09-3","t":"의료인 甲이 의료인 아닌 A의 무면허의료행위에 공모하여 가공한 경우 甲은 의료법 위반(무면허의료행위)죄의 공동정범이 성립한다.","ox":"O","m":"③","c":"A","tp":"공범과 신분"},{"y":2018,"e":"국가직 9급","qn":9,"i":"N92018-09-4","t":"범인 甲이 도피하기 위하여 타인으로 하여금 허위의 자백을 하게 하는 등으로 범인도피죄를 범하게 하는 경우 그것이 방어권의 남용으로 볼 수 있을 때에는 범인도피교사죄에 해당할 수 있다.","ox":"O","m":"④","c":"A","tp":"공범과 신분"},{"y":2018,"e":"국가직 9급","qn":11,"i":"N92018-11-1","t":"공동정범은 공동가공의 의사와 그 공동의사에 의한 기능적 행위지배를 통한 범죄실행이라는 주관적·객관적 요건을 충족함으로써 성립하므로, 공모자 중 구성요건행위를 직접 분담하여 실행하지 아니한 사람도 위 요건을 충족하면 공모공동정범으로서의 죄책을 진다.","ox":"O","m":"①","c":"A","tp":"공범"},{"y":2018,"e":"국가직 9급","qn":11,"i":"N92018-11-2","t":"시간적 차이가 있는 독립된 폭행행위가 경합하여 사망의 결과가 일어나고, 그 사망의 원인된 행위가 판명되지 않는 경우 공동정범의 예에 의하여 처벌한다.","ox":"O","m":"②","c":"A","tp":"공범"},{"y":2018,"e":"국가직 9급","qn":11,"i":"N92018-11-3","t":"순차적 또는 암묵적으로 상통할 뿐 전체의 모의과정이 없었다면 공모관계가 성립하지 않으므로 공동정범으로 처벌할 수 없다.","ox":"X","m":"③","c":"A","tp":"공범"},{"y":2018,"e":"국가직 9급","qn":11,"i":"N92018-11-4","t":"합동범이 성립하기 위하여는 주관적 요건으로서의 공모와 객관적 요건으로서의 실행행위의 분담이 있어야 하고 그 실행행위에 있어서는 시간적으로나 장소적으로 협동관계에 있어야 한다.","ox":"O","m":"④","c":"A","tp":"공범"},{"y":2018,"e":"국가직 9급","qn":18,"i":"N92018-18-1","t":"교사를 받은 자가 범죄의 실행을 승낙하고 실행의 착수에 이르지 아니한 때 교사자의 경우 음모 또는 예비에 준하여 처벌한다.","ox":"O","m":"①","c":"A","tp":"교사범"},{"y":2018,"e":"국가직 9급","qn":18,"i":"N92018-18-2","t":"교사범이 그 공범관계로부터 이탈하기 위해서는 피교사자가 범죄의 실행행위에 나아가기 전에 교사범에 의하여 형성된 피교사자의 범죄 실행의 결의를 해소하는 것이 필요하다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"국가직 9급","qn":18,"i":"N92018-18-3","t":"교사를 받은 자가 범죄의 실행을 승낙하지 아니한 경우 피교사자는 음모 또는 예비에 준하여 처벌한다.","ox":"X","m":"③","c":"A","tp":"교사범"},{"y":2018,"e":"국가직 9급","qn":18,"i":"N92018-18-4","t":"피교사자가 이미 범죄의 결의를 가지고 있을 때에는 교사범이 성립할 여지가 없다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"국가직 9급","qn":20,"i":"N92018-20","t":"다음 중 판례가 긍정하는 것만을 모두 고른 것은?","c":"A","mc":{"s":"다음 중 판례가 긍정하는 것만을 모두 고른 것은?","d":"ㄱ. 편면적 방조에 있어서 공범종속성\nㄴ. 예비단계에 있어서 방조범 성립\nㄷ. 합동절도의 공동정범 성립\nㄹ. 허위공문서작성죄의 간접정범 성립\nㅁ. 강간치상죄의 동시범특례규정 적용","o":["ㄱ, ㄷ, ㄹ","ㄱ, ㄷ, ㅁ","ㄴ, ㄷ, ㄹ","ㄴ, ㄹ, ㅁ"],"a":1}},{"y":2019,"e":"국가직 9급","qn":16,"i":"N92019-16-1","t":"처벌되지 아니하는 타인의 행위를 적극적으로 유발하고 이를 이용 하여 자신의 범죄를 실현한 자는 간접정범의 죄책을 지고, 그 과정에서 타인의 의사를 부당하게 억압하여야 하는 것은 아니다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"국가직 9급","qn":16,"i":"N92019-16-2","t":"강제추행죄는 처벌되지 아니하는 타인을 도구로 삼아 피해자를 강제로 추행하는 간접정범의 형태로도 범할 수 있으나, 이때 피해자는 그 타인에 포함되지 않는다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"국가직 9급","qn":16,"i":"N92019-16-3","t":"공문서의 작성권한이 있는 공무원(A)의 직무를 보좌하는 공무원이 행사할 목적으로 그 직위를 이용하여 허위의 내용이 기재된 문서 초안을 그 정을 모르는 A에게 제출하여 결재 하도록 한 경우에는 허위공문서작성죄의 간접정범이 성립한다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"국가직 9급","qn":16,"i":"N92019-16-4","t":"자기에게 유리한 판결을 얻기 위해 증거가 조작되어 있다는 점을 알지 못하는 제3자를 이용하여 그를 소송의 당사자가 되게 하고 법원을 기망하여 소송 상대방의 재물을 취득하였다면 간접정범 형태의 소송사기죄가 성립한다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"국가직 9급","qn":3,"i":"N92020-03-1","t":"2인 이상이 상호 의사연락하에 과실행위를 함으로써 범죄가 되는 결과를 발생케 한 경우 과실범의 공동정범이 성립된다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"국가직 9급","qn":3,"i":"N92020-03-2","t":"3인 이상의 범인이 합동절도의 범행을 공모하였지만 범행 현장에 있지 않은 자에 대해서는 합동범의 공동정범을 인정할 수 없다.","ox":"X","m":"②","c":"A"},{"y":2020,"e":"국가직 9급","qn":3,"i":"N92020-03-3","t":"결과적 가중범의 공동정범은 행위를 공동으로 할 의사가 있으면 성립하고 그 결과를 공동으로 할 의사까지는 필요 없다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"국가직 9급","qn":3,"i":"N92020-03-4","t":"공모자가 공모에 주도적으로 참여하여 다른 공모자의 실행에 영향을 미친 때에는 그 영향력을 제거하지 아니하는 한 공모 관계에서 이탈하였다고 할 수 없다.","ox":"O","m":"④","c":"A","tp":"공동정범"},{"y":2020,"e":"국가직 9급","qn":7,"i":"N92020-07-1","t":"작위는 물론이고 부작위에 의한 종범도 성립할 수 있지만, 정범이 작위범인 경우에는 부작위에 의한 방조자에게 보증인적 지위가 인정되지 않으면 부작위에 의한 종범이 성립하지 않는다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"국가직 9급","qn":7,"i":"N92020-07-2","t":"종범이 성립하기 위해서는 방조자에게 자신이 피방조자의 범죄실행을 방조한다는 점에 대한 고의와 피방조자의 행위가 구성요건적 결과를 실현한다는 점에 대한 고의가 둘 다 있어야 한다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"국가직 9급","qn":7,"i":"N92020-07-3","t":"정범이 강도의 예비행위를 할 때 방조행위가 행해졌고 그 후에 정범이 강도의 실행에 착수하지 못했다면 방조자는 강도예비죄의 종범으로 처벌된다.","ox":"X","m":"③","c":"A"},{"y":2020,"e":"국가직 9급","qn":7,"i":"N92020-07-4","t":"간호보조원의 무면허 진료행위 후에 이를 의사가 진료부에 기재하는 행위는 무면허 의료행위의 방조에 해당한다.","ox":"O","m":"④","c":"A","tp":"종범"},{"y":2020,"e":"국가직 9급","qn":18,"i":"N92020-18","t":"대법원 판례가 인정하고 있지 않는 것만을 모두 고르면?","c":"A","mc":{"s":"대법원 판례가 인정하고 있지 않는 것만을 모두 고르면?","d":"ㄱ. 예비죄의 중지범\nㄴ. 진정결과적가중범의 공동정범\nㄷ. 부작위범 사이의 공동정범\nㄹ. 사후방조로서의 종범\nㅁ. 편면적 종범\nㅂ. 예비죄의 공동정범","o":["ㄱ, ㄹ","ㄱ, ㄴ, ㅂ","ㄱ, ㄹ, ㅂ","ㄴ, ㄷ, ㅁ"],"a":1}},{"y":2021,"e":"국가직 9급","qn":12,"i":"N92021-12-1","t":"甲이 사기 범행에 이용되리라는 사정을 알고서도 A에게 자신의 명의로 된 은행 예금계좌의 접근매체를 양도함으로써 A가 B를 속여 B로 하여금 현금을 위 계좌로 송금하게 한 경우, 甲은 사기죄의 방조범이 된다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"국가직 9급","qn":12,"i":"N92021-12-2","t":"은행지점장 甲이 정범인 부하직원들의 은행에 대한 배임행위를 인식하면서도 이를 방치한 경우 업무상배임죄의 방조범이 성립 한다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"국가직 9급","qn":12,"i":"N92021-12-3","t":"방조죄는 정범의 범죄에 종속하여 성립하는 것으로서, 방조의 대상이 되는 정범의 실행행위의 착수가 없으면 방조죄만 독립하여 성립할 수 없다.","ox":"O","m":"③","c":"A","tp":"방조범"},{"y":2021,"e":"국가직 9급","qn":12,"i":"N92021-12-4","t":"정범의 실행행위 전이나 실행행위 중에 정범을 방조하여 그 실행 행위를 용이하게 하는 것뿐만 아니라 정범의 범죄종료 후의 이른바 사후방조도 방조범으로 볼 수 있다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"국가직 9급","qn":10,"i":"N92023-10-1","t":"합동강도의 공범자 중 1인이 강도의 기회에 피해자를 살해한 경우, 다른 공모자가 살인의 공모를 하지 아니하였다고 하여도 그 살인행위나 치사의 결과를 예견할 수 없었던 경우가 아니면 강도치사죄의 죄책을 면할 수 없다.","ox":"O","m":"①","c":"A","tp":"합동범"},{"y":2023,"e":"국가직 9급","qn":10,"i":"N92023-10-2","t":"피고인이 다른 피고인들과 택시강도를 하기로 모의한 일이 있다고 하여도 다른 피고인들이 피해자에 대한 폭행에 착수하기 전에 겁을 먹고 미리 현장에서 도주해 버린 것이라면, 피고인을 특수강도의 합동범으로 다스릴 수는 없다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"국가직 9급","qn":10,"i":"N92023-10-3","t":"합동절도에서도 공동정범과 교사범ㆍ종범의 구별기준은 일반원칙에 따라야 하고, 그 결과 범행현장에 존재하지 아니한 범인도 공동 정범이 될 수 있으며, 상황에 따라서는 장소적으로 협동한 범인도 방조만 한 경우에는 종범으로 처벌될 수도 있다.","ox":"O","m":"③","c":"A","tp":"합동범"},{"y":2023,"e":"국가직 9급","qn":10,"i":"N92023-10-4","t":"합동범이 성립하기 위한 주관적 요건으로서 공모는 법률상 어떠한 정형을 요구하는 것이 아니어서 공범자 상호 간에 직접 또는 간접으로 범죄의 공동가공의사가 암묵리에 서로 상통하면 되지만, 적어도 그 모의과정은 사전에 있어야 한다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"국가직 9급","qn":14,"i":"N92023-14-1","t":"피교사자의 범행이 당초의 교사행위와 무관한 새로운 범죄 실행의 결의에 따른 것이라면, 교사자는 예비ㆍ음모에 준하는 죄책을 부담함은 별론으로 피교사자에 대한 교사범으로서의 죄책을 부담하지는 않는다.","ox":"O","m":"①","c":"A","tp":"공범"},{"y":2023,"e":"국가직 9급","qn":14,"i":"N92023-14-2","t":"피교사자가 교사자의 교사행위 당시에는 범행을 승낙하지 아니한 것으로 보여진다 하더라도 이후 그 교사행위에 의하여 범행을 결의한 것으로 인정된다면, 교사범의 성립에 영향이 없다.","ox":"O","m":"②","c":"A","tp":"공범"},{"y":2023,"e":"국가직 9급","qn":14,"i":"N92023-14-3","t":"형법상 방조행위는 정범이 범행을 한다는 정을 알면서 그 실행 행위를 용이하게 하는 직접ㆍ간접의 모든 행위를 가리키는 점에서 방조행위와 정범의 범죄 실현 사이에 반드시 인과관계를 필요로 하는 것은 아니다.","ox":"X","m":"③","c":"A","tp":"공범"},{"y":2023,"e":"국가직 9급","qn":14,"i":"N92023-14-4","t":"정범의 실행의 착수 이전에 장래의 실행행위를 예상하고 이를 용이하게 하기 위하여 방조한 경우에도 그 후 정범이 실행행위에 나아갔다면 종범이 성립할 수 있다.","ox":"O","m":"④","c":"A","tp":"공범"},{"y":2023,"e":"국가직 9급","qn":15,"i":"N92023-15-1","t":"물건의 소유자가 아닌 사람이 소유자의 권리행사방해 범행에 가담한 경우에는 절도죄가 성립할 뿐, 권리행사방해죄의 공범이 성립할 여지가 없다.","ox":"X","m":"①","c":"A","tp":"공범과 신분"},{"y":2023,"e":"국가직 9급","qn":15,"i":"N92023-15-2","t":"업무자라는 신분관계가 없는 자가 그러한 신분관계 있는 자와 공모하여 업무상배임죄를 저질렀다면, 그러한 신분관계가 없는 공범에 대하여는 단순배임죄에서 정한 형으로 처단하여야 한다.","ox":"O","m":"②","c":"A","tp":"공범과 신분"},{"y":2023,"e":"국가직 9급","qn":15,"i":"N92023-15-3","t":"간호사가 주도적으로 실시한 무면허의료행위에 의사가 간호사와 함께 공모하여 그 공동의사에 의한 기능적 행위지배가 있었다면, 의사도 무면허의료행위의 공동정범으로서의 죄책을 진다.","ox":"O","m":"③","c":"A","tp":"공범과 신분"},{"y":2023,"e":"국가직 9급","qn":15,"i":"N92023-15-4","t":"형법 제33조 소정의 신분이라 함은 남녀의 성별, 내ㆍ외국인의 구별, 친족관계, 공무원인 자격과 같은 관계뿐만 아니라 널리 일정한 범죄행위에 관련된 범인의 인적관계인 특수한 지위 또는 상태를 지칭한다.","ox":"O","m":"④","c":"A","tp":"공범과 신분"},{"y":2024,"e":"국가직 9급","qn":10,"i":"N92024-10-1","t":"형법 제127조는 공무원 또는 공무원이었던 자가 법령에 의한 직무상 비밀을 누설하는 행위만을 처벌하고 있을 뿐 직무상 비밀을 누설받은 상대방을 처벌하는 규정이 없으므로, 직무상 비밀을 누설받은 자에 대하여는 공범에 관한 형법총칙 규정을 적용하여 처벌할 수 없다.","ox":"O","m":"①","c":"A","tp":"공범의 종류"},{"y":2024,"e":"국가직 9급","qn":10,"i":"N92024-10-2","t":"뇌물공여죄와 뇌물수수죄 사이와 같은 이른바 대향범 관계에 있는 자는 서로 대향된 행위의 존재를 필요로 할 뿐 각자 자신의 구성요건을 실현하고 별도의 형벌규정에 따라 처벌되는 것이어서, 2인 이상이 가공하여 공동의 구성요건을 실현하는 공범관계에 있는 자와는 본질적으로 다르다.","ox":"O","m":"②","c":"A","tp":"공범의 종류"},{"y":2024,"e":"국가직 9급","qn":10,"i":"N92024-10-3","t":"구 정치자금법 제45조제1항의 정치자금을 기부한 자와 기부받은 자는 이른바 대향범인 필요적 공범관계에 있으므로, 정치자금을 기부하는 자의 범죄가 성립하지 않더라도 정치자금을 기부받는 자가 구 정치자금법이 정하지 않은 방법으로 정치자금을 제공 받는다는 의사를 가지고 받으면 정치자금부정수수죄가 성립한다.","ox":"O","m":"③","c":"A","tp":"공범의 종류"},{"y":2024,"e":"국가직 9급","qn":10,"i":"N92024-10-4","t":"쟁의행위 기간 중 그 쟁의행위로 중단된 업무의 수행을 위하여 당해 사업과 관계없는 자를 채용 또는 대체하는 사용자를 처벌 하는 노동조합 및 노동관계조정법 제91조, 제43조제1항을 사용자에게 채용 또는 대체되는 자의 행위에 대하여 일반적인 형법총칙상의 공범 규정을 적용하여 동법 위반죄의 공동정범, 교사범 또는 방조범으로 처벌할 수 있다.","ox":"X","m":"④","c":"A","tp":"공범의 종류"},{"y":2024,"e":"국가직 9급","qn":11,"i":"N92024-11-1","t":"공무원이 아닌 사람이 공무원과 공동가공의 의사와 이를 기초로 한 기능적 행위지배를 통하여 공무원의 직무에 관하여 뇌물을 수수하는 범죄를 실행하였다면 공무원이 직접 뇌물을 받은 것과 동일하게 평가할 수 있으므로 공무원과 비공무원에게 형법 제129조제1항에서 정한 뇌물수수죄의 공동정범이 성립한다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"국가직 9급","qn":11,"i":"N92024-11-2","t":"합동절도는 범행 현장에서 시간적, 장소적으로 협동관계를 이루어 절도의 실행행위를 분담하여 절도 범행을 하여야 하므로, 공모에는 참여하였으나 현장에 없는 자는 기능적 범행지배 유무를 불문하고 합동범의 공동정범이 성립할 수 없다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"국가직 9급","qn":11,"i":"N92024-11-3","t":"공모공동정범에 있어서 그 공모자 중 1인이 다른 공모자가 실행 행위에 이르기 전에 그 공모관계에서 이탈한 경우 그 이탈의 표시는 반드시 명시적임을 요하지 않는다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"국가직 9급","qn":11,"i":"N92024-11-4","t":"구성요건행위를 직접 분담하여 실행하지 않은 공모자가 공모 공동정범으로 인정되기 위해서는 전체 범죄에서 그가 차지하는 지위ㆍ역할, 범죄 경과에 대한 지배나 장악력 등을 종합하여 그가 단순한 공모자에 그치는 것이 아니라 범죄에 대한 본질적 기여를 통한 기능적 행위지배가 존재한다고 인정되어야 한다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"국가직 9급","qn":3,"i":"N92025-03-1","t":"공동가공의 의사는 타인의 범행을 인식하면서도 이를 제지하지 아니하고 용인하는 것만으로도 인정된다.","ox":"X","m":"①","c":"A","tp":"공동정범"},{"y":2025,"e":"국가직 9급","qn":3,"i":"N92025-03-2","t":"포괄일죄의 범행 도중에 공동정범으로 범행에 가담한 자가 그 범행에 가담할 때에 이미 이루어진 종전의 범행을 알았다면 전체 범행에 대하여 공동정범으로 책임을 진다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"국가직 9급","qn":3,"i":"N92025-03-3","t":"공모공동정범에 있어서 공모관계에서 이탈이 인정되기 위해서는 공모자가 공모에 의하여 담당한 기능적 행위지배를 해소하는 것이 필요하므로 공모자가 공모에 주도적으로 참여하여 다른 공모자의 실행에 영향을 미친 때에는 범행을 저지하기 위하여 적극적으로 노력하는 등 실행에 미친 영향력을 제거해야 한다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"국가직 9급","qn":3,"i":"N92025-03-4","t":"3인 이상이 합동절도를 모의한 후 2인 이상이 현장에서 범행을 실행한 경우, 직접 실행행위에 가담하지 않은 자는 그가 현장에서 절도 범행을 실행한 2인 이상의 범인의 행위를 자기 의사의 수단으로 하여 합동절도의 범행을 하였다고 평가할 수 있더라도 합동범의 공동정범이 인정되지 아니한다.","ox":"X","m":"④","c":"A"},{"y":2025,"e":"국가직 9급","qn":7,"i":"N92025-07-1","t":"간접정범을 통한 범행에서 피이용자는 간접정범의 의사를 실현 하는 수단으로서의 지위를 가질 뿐이므로, 피해자에 대한 사기 범행을 실현하는 수단으로서 타인을 기망하여 그를 피해자로부터 편취한 재물이나 재산상 이익을 전달하는 도구로서만 이용한 경우에는 편취의 대상인 재물 또는 재산상 이익에 관하여 피해자에 대한 사기죄가 성립할 뿐 도구로 이용된 타인에 대한 사기죄가 별도로 성립한다고 할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"국가직 9급","qn":7,"i":"N92025-07-2","t":"감금죄는 간접정범의 형태로도 행하여질 수 있는 것이므로, 인신 구속에 관한 직무를 행하는 자 또는 이를 보조하는 자가 피해자를 구속하기 위하여 진술조서 등을 허위로 작성한 후 이를 기록에 첨부하여 구속영장을 신청하고, 진술조서 등이 허위로 작성된 정을 모르는 검사와 영장전담판사를 기망하여 구속영장을 발부받은 후, 그 영장에 의하여 피해자를 구금하였다면 형법 제124조 제1항의 직권남용감금죄가 성립한다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"국가직 9급","qn":7,"i":"N92025-07-3","t":"자기에게 유리한 판결을 얻기 위해 소송상의 주장이 사실과 다름이 객관적으로 명백하거나 증거가 조작되어 있다는 정을 인식하지 못하는 제3자를 이용하여 그로 하여금 소송의 당사자가 되게 하고, 법원을 기망하여 소송 상대방의 재물 또는 재산상 이익을 취득하려 하였다면 간접정범의 형태에 의한 소송사기죄가 성립한다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"국가직 9급","qn":7,"i":"N92025-07-4","t":"‘정범배후의 정범’ 긍정설은 형법 제34조제1항이 어느 행위로 처벌되지 않는 자 또는 과실범으로 처벌되는 자를 이용한 경우 간접정범이 성립한다고 규정하여 간접정범 피이용자 범위를 명시적으로 제한하고 있다는 것을 중요한 논거로 한다.","ox":"X","m":"④","c":"A"}],"9":[{"y":2015,"e":"국가직 9급","qn":9,"i":"N92015-09-1","t":"집단표시에 의한 모욕은 개별구성원에 이르러서도 그 비난의 정도가 희석되지 않아 구성원 개개인의 사회적 평가를 저하시킬 만한 것으로 평가될 경우 구성원 개개인에 대한 모욕이 될 수 있다.","ox":"O","m":"①","c":"A","tp":"명예훼손죄 및 모욕죄"},{"y":2015,"e":"국가직 9급","qn":9,"i":"N92015-09-2","t":"개인 블로그의 비공개 대화방에서 상대방으로부터 비밀을 지키겠다는 말을 듣고 단지 일대일로 대화한 경우라면 상대방의 전파가능성 유무를 불문하고 공연성은 부정된다.","ox":"X","m":"②","c":"A","tp":"명예훼손죄 및 모욕죄"},{"y":2015,"e":"국가직 9급","qn":9,"i":"N92015-09-3","t":"甲이 A를 비방할 목적으로 출판물에 사실을 적시하여 명예를 훼손한 경우 형법 제310조(위법성의 조각)를 적용할 수 없다.","ox":"O","m":"③","c":"A","tp":"명예훼손죄 및 모욕죄"},{"y":2015,"e":"국가직 9급","qn":9,"i":"N92015-09-4","t":"A의 산후조리원을 이용한 甲이 임신, 육아 등과 관련한 유명 인터넷 카페나 자신의 블로그 등에 자신이 직접 겪은 불편사항 등을 9회에 걸쳐 후기 형태로 게시한 주요한 동기·목적이 공공의 이익을 위한 것이라면 산후조리원 이용대금 환불과 같은 다른 사익적 목적이나 동기가 내포되어 있다고 하여도 ‘비방할 목적’을 인정하기는 어렵다.","ox":"O","m":"④","c":"A","tp":"명예훼손죄 및 모욕죄"},{"y":2016,"e":"국가직 9급","qn":1,"i":"N92016-01","t":"강제추행죄가 성립하지 않는 경우는?","c":"A","mc":{"s":"강제추행죄가 성립하지 않는 경우는?","d":"","o":["가까이 접근하여 갑자기 뒤에서 껴안는 이른바 ‘기습추행’ 행위의 경우","유부녀인 피해자에 대하여 혼인 외 성관계 사실을 폭로하겠다는 등의 내용으로 협박하여 피해자를 추행한 경우","사람 및 차량의 왕래가 빈번한 도로에서 피해자에게 욕설을 하면서 단순히 바지를 내리고 자신의 성기를 피해자에게 보여준 경우","골프장 여종업원들이 거부의사를 밝혔음에도, 골프장 사장과의 친분관계를 내세워 함께 술을 마시지 않을 경우 신분상의 불이익을 가할 것처럼 협박하여 이른바 러브샷의 방법으로 술을 마시게 한 경우"],"a":3}},{"y":2017,"e":"국가직 9급","qn":18,"i":"N92017-18-1","t":"형법 제307조 제2항을 적용하기 위하여 적시된 사실이 허위의 사실인지 여부를 판단하는 경우, 적시된 사실의 내용 전체의 취지를 살펴볼 때 중요한 부분이 객관적 사실과 합치되면 세부에 있어서 진실과 약간 차이가 나거나 다소 과장된 표현이 있다 하더라도 이를 허위의 사실이라고 볼 수 없다.","ox":"O","m":"①","c":"A","tp":"명예훼손죄"},{"y":2017,"e":"국가직 9급","qn":18,"i":"N92017-18-2","t":"형법 제310조는 ‘오로지 공공의 이익에 관한 때’라고 적시되어 있으므로 행위자의 행위에 다른 사익적 목적이나 동기가 내포되어 있었다면 행위의 주요한 동기가 공공의 이익을 위한 것이라도 형법 제310조의 적용은 배제된다.","ox":"X","m":"②","c":"A","tp":"명예훼손죄"},{"y":2017,"e":"국가직 9급","qn":18,"i":"N92017-18-3","t":"집합적 명사를 쓴 경우에도 시간적·장소적 관련성 속에서 특정인을 가리키는 것이 명백하면, 이를 각자의 명예를 훼손 하는 행위라고 볼 수 있다.","ox":"O","m":"③","c":"A","tp":"명예훼손죄"},{"y":2017,"e":"국가직 9급","qn":18,"i":"N92017-18-4","t":"형법 제310조의 적용에서 적시된 사실이 공공의 이익에 관한 것이면 진실한 것이라는 증명이 없다 할지라도 행위자가 진실한 것으로 믿었고 또 그렇게 믿을 만한 상당한 이유가 있는 경우에는 위법성이 없다고 보아야 한다.","ox":"O","m":"④","c":"A","tp":"명예훼손죄"},{"y":2020,"e":"국가직 9급","qn":11,"i":"N92020-11-1","t":"엘리베이터 안에서 피해자들을 칼로 위협하여 자신의 실력적인 지배 하에 둔 다음 피해자들에게 자신의 자위행위 모습을 보여 주고 이를 외면하거나 피할 수 없게 한 행위는 강제추행에 해당한다.","ox":"O","m":"①","c":"A","tp":"강제추행의 죄"},{"y":2020,"e":"국가직 9급","qn":11,"i":"N92020-11-2","t":"강제추행죄는 폭행행위 자체가 추행행위라고 인정되는 경우도 포함하며, 이 경우의 폭행은 반드시 상대방의 의사를 억압할 정도의 것임을 요하지 않고 상대방의 의사에 반하는 유형력의 행사가 있는 이상 그 힘의 대소강약을 불문한다.","ox":"O","m":"②","c":"A","tp":"강제추행의 죄"},{"y":2020,"e":"국가직 9급","qn":11,"i":"N92020-11-3","t":"밤에 혼자 걸어가는 피해자(여, 17세)를 추행의 고의로 뒤따라 가다가 갑자기 껴안으려 하였으나 피해자가 뒤돌아보면서 소리치는 바람에 몸을 껴안는 추행의 결과에 이르지 못하고 행위자의 팔이 피해자의 몸에 닿지 않은 경우, 아동·청소년에 대한 강제추행미수죄에 해당하지 않는다.","ox":"X","m":"③","c":"A","tp":"강제추행의 죄"},{"y":2020,"e":"국가직 9급","qn":11,"i":"N92020-11-4","t":"강제추행죄의 성립에 필요한 주관적 구성요건으로 성욕을 자극·흥분·만족시키려는 동기나 목적이 있어야 하는 것은 아니다.","ox":"O","m":"④","c":"A","tp":"강제추행의 죄"},{"y":2020,"e":"국가직 9급","qn":19,"i":"N92020-19-1","t":"강제추행죄는 정범 자신이 직접 범죄를 실행하여야 성립하는 자수범이지만, 피해자를 도구로 삼아 피해자의 신체를 이용하여 추행행위를 한 경우에도 강제추행죄의 간접정범에 해당할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2020,"e":"국가직 9급","qn":19,"i":"N92020-19-2","t":"피해자가 심신상실 또는 항거불능의 상태에 있다고 인식하고 그러한 상태를 이용하여 간음할 의사로 피해자를 간음하였으나 피해자가 실제로는 심신상실 또는 항거불능의 상태에 있지 않았던 경우, 준강간죄의 미수범이 성립한다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"국가직 9급","qn":19,"i":"N92020-19-3","t":"계좌명의인이 개설한 예금계좌가 사기 범행에 이용되어 그 계좌에 피해자가 사기피해금을 송금·이체한 경우, 해당 계좌의 명의인은 피해자를 위하여 사기피해금을 보관하는 지위에 있다고 볼 수 없다.","ox":"X","m":"③","c":"A"},{"y":2020,"e":"국가직 9급","qn":19,"i":"N92020-19-4","t":"손자가 할아버지 소유 예금통장을 절취하여 이를 현금자동지급기에 넣고 조작하는 방법으로 예금 잔고를 자신의 거래은행 계좌로 이체한 경우, 손자에게 형법상 친족상도례를 적용할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"국가직 9급","qn":13,"i":"N92021-13-1","t":"강도계획 후에 피해자를 강제로 자신의 승용차에 태우고 가면서 돈을 빼앗고 상해를 가한 뒤에 계속하여 상당한 거리를 진행하여 가다가 교통사고를 일으켜 감금행위가 중단된 경우 감금죄와 강도상해죄의 실체적 경합범이 성립한다.","ox":"O","m":"①","c":"A","tp":"체포와 감금의 죄"},{"y":2021,"e":"국가직 9급","qn":13,"i":"N92021-13-2","t":"체포죄에서 체포의 수단과 방법은 불문하며, 체포의 고의로 타인의 신체적 활동의 자유를 현실적으로 침해하는 행위를 개시한 때 체포죄의 기수가 된다.","ox":"X","m":"②","c":"A","tp":"체포와 감금의 죄"},{"y":2021,"e":"국가직 9급","qn":13,"i":"N92021-13-3","t":"미성년자를 유인한 자가 계속하여 미성년자를 불법하게 감금한 경우 감금죄는 성립하지 않고 미성년자유인죄만 성립한다.","ox":"X","m":"③","c":"A","tp":"체포와 감금의 죄"},{"y":2021,"e":"국가직 9급","qn":13,"i":"N92021-13-4","t":"운전자가 피해자를 강제로 승용차에 태운 뒤 운전하여 가자 겁에 질린 피해자가 차에서 뛰어 내리다가 상해를 입은 경우 감금죄와 상해죄의 실체적 경합범이 성립한다.","ox":"X","m":"④","c":"A","tp":"체포와 감금의 죄"},{"y":2023,"e":"국가직 9급","qn":11,"i":"N92023-11","t":"주거침입죄의 실행의 착수는 구성요건의 일부를 실현하는 행위까지 요구하는 것은 아니고 범죄구성요건의 실현에 이르는 현실적 위험성을 포함하는 행위를 개시하는 것으로 족하다.","c":"A","mc":{"s":"주거침입죄의 실행의 착수는 구성요건의 일부를 실현하는 행위까지 요구하는 것은 아니고 범죄구성요건의 실현에 이르는 현실적 위험성을 포함하는 행위를 개시하는 것으로 족하다.","d":"주거침입의 죄에 대한 설명으로 옳은 것만을 모두 고르면?\nㄱ. 외부인이 주거 내에 현재하는 거주자의 현실적인 승낙을 받아 통상적인 출입방법에 따라 공동주거에 들어갔다 하더라도 그것이 부재중인 다른 거주자의 의사에 반하는 것으로 추정되는 경우 주거침입죄가 성립한다.\nㄴ. 관리자의 현실적인 승낙을 받아 건조물에 통상적인 출입 방법으로 들어간 경우에도 관리자의 가정적ㆍ추정적 의사는 고려되어야 하며, 그 승낙의 동기에 착오가 있었던 경우 승낙의 유효성에 영향을 미쳐 건조물침입죄가 성립할 수 있다.\nㄷ. 일반인의 출입이 허용된 음식점에 영업주의 승낙을 받아 통상적인 출입방법으로 들어갔다면 설령 행위자가 범죄 등을 목적으로 음식점에 출입하였거나 영업주가 행위자의 실제 출입목적을 알았더라면 출입을 승낙하지 않았을 것이라는 사정이 인정되더라도 주거침입죄에서 규정하는 침입행위에 해당하지 않는다. ㄹ.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":4}},{"y":2025,"e":"국가직 9급","qn":15,"i":"N92025-15-1","t":"입찰절차뿐만 아니라 공적ㆍ사적 경제주체의 임의의 선택에 따른 계약체결의 과정에 공정한 경쟁을 해하는 행위가 개재된 경우도 입찰방해죄로 처벌할 수 있다.","ox":"X","m":"①","c":"A","tp":"경매ㆍ입찰방해죄"},{"y":2025,"e":"국가직 9급","qn":15,"i":"N92025-15-2","t":"경매목적물을 매수할 의사나 능력 없이 오로지 경매목적물이 제3자에게 매각되는 것을 저지하고자 경매절차를 지연할 목적으로 타인 명의로 감정가와 현저하게 차이가 나는 금액으로 입찰을 반복하여 제3자의 매수를 사실상 봉쇄하여 경매절차를 형해화한 경우, 경매방해죄가 성립한다.","ox":"O","m":"②","c":"A","tp":"경매ㆍ입찰방해죄"},{"y":2025,"e":"국가직 9급","qn":15,"i":"N92025-15-3","t":"법률적으로 경매결과에 영향을 미칠 수 있는 행위뿐 아니라 경매에 참가하려는 자의 의사결정에 사실상 영향을 미칠 수 있는 행위도 경매방해죄에서 말하는 ‘경매의 공정을 해하는 행위’에 해당할 수 있다.","ox":"O","m":"③","c":"A","tp":"경매ㆍ입찰방해죄"},{"y":2025,"e":"국가직 9급","qn":15,"i":"N92025-15-4","t":"실질적인 단독입찰을 경쟁입찰인 것처럼 가장하여 그 입찰가격으로 낙찰되게 한 경우, 그것이 설사 동종업자 사이의 무모한 출혈경쟁을 방지하기 위한 수단에 불과하여 입찰가격에 있어 입찰실시자의 이익을 해하는 것이 아니었다 하더라도 입찰방해죄가 성립한다.","ox":"O","m":"④","c":"A","tp":"경매ㆍ입찰방해죄"},{"y":2025,"e":"국가직 9급","qn":19,"i":"N92025-19-1","t":"주거침입죄의 구성요건적 행위인 침입이란 주거의 사실상 평온 상태를 해치는 행위태양으로 주거에 들어가는 것을 의미하고, 침입에 해당하는지는 출입 당시 객관적ㆍ외형적으로 드러난 행위태양을 기준으로 판단함이 원칙이다.","ox":"O","m":"①","c":"A","tp":"사생활의 평온"},{"y":2025,"e":"국가직 9급","qn":19,"i":"N92025-19-2","t":"전자기록 등 특수매체기록에 봉함 기타 비밀장치가 되어 있지 않아도 이를 기술적 수단을 동원해서 알아낸 경우, 전자기록등 내용탐지죄가 성립한다.","ox":"X","m":"②","c":"A","tp":"사생활의 평온"},{"y":2025,"e":"국가직 9급","qn":19,"i":"N92025-19-3","t":"다른 사람과 공동으로 주거에 거주하거나 건조물을 관리하던 사람이더라도 공동생활관계에서 이탈하거나 주거 등에 대한 사실상의 지배ㆍ관리를 상실한 후 그 주거 등에 임의로 출입하면 주거침입죄가 성립할 수 있다.","ox":"O","m":"③","c":"A","tp":"사생활의 평온"},{"y":2025,"e":"국가직 9급","qn":19,"i":"N92025-19-4","t":"병원에서 분실된 진료기록의 일부를 우연히 습득한 교통사고 피해당사자가 이를 법원에 증거로 제출하더라도 업무상비밀누설죄가 성립하지 않는다.","ox":"O","m":"④","c":"A","tp":"사생활의 평온"}],"2":[{"y":2015,"e":"국가직 9급","qn":10,"i":"N92015-10-1","t":"의사가 업무상 과실로 인한 형사책임을 지기 위해서는 피해자의 상해와 의사의 설명의무 사이에 상당인과관계가 존재하여야 한다.","ox":"O","m":"①","c":"A","tp":"과실범"},{"y":2015,"e":"국가직 9급","qn":10,"i":"N92015-10-2","t":"의료사고에서 의사에게 과실이 있다고 하기 위해서는 결과 발생을 예견할 수 있고 또 회피할 수 있었는데도 이를 예견 하지 못하거나 회피하지 못하였음이 인정되어야 한다.","ox":"O","m":"②","c":"A","tp":"과실범"},{"y":2015,"e":"국가직 9급","qn":10,"i":"N92015-10-3","t":"행위자의 주의의무위반행위가 결과발생에 유일하거나 직접적인 원인일 필요는 없으며, 설령 피해자의 주의의무위반이 개입 되어 있더라도 인과관계는 단절되지 않는다.","ox":"O","m":"③","c":"A","tp":"과실범"},{"y":2015,"e":"국가직 9급","qn":10,"i":"N92015-10-4","t":"안전배려 내지 안전관리 사무에 계속적으로 종사하여 사회 생활면에서 하나의 지위로서의 계속성을 가지지는 않았지만 건물의 소유자로서 건물을 비정기적으로 수리하거나 건물의 일부분을 임대한 경우라면 업무상과실치상죄에 있어서의 ‘업무’가 인정된다.","ox":"X","m":"④","c":"A","tp":"과실범"},{"y":2015,"e":"국가직 9급","qn":18,"i":"N92015-18","t":"사실의 착오에 대한 설명으로 옳은 것만을 모두 고른 것은?","c":"A","mc":{"s":"사실의 착오에 대한 설명으로 옳은 것만을 모두 고른 것은?","d":"(다툼이 있는 경우 판례에 의함)\nㄱ. 甲이 살해의 고의로 A를 향해 총을 쏘았으나 알고 보니 B가 맞아 죽은 경우, 구체적 부합설에 따르면 A에 대한 살인미수와 B에 대한 과실치사의 상상적 경합이다.\nㄴ. 甲이 상해의 고의로 A를 향해 돌을 던졌으나 빗나가서 옆에 있던 A의 자동차 유리창을 깨뜨린 경우, 구체적 부합설에 따르면 A에 대한 상해미수죄가 성립한다.\nㄷ. 甲이 살해의 고의로 형 A를 향해 총을 쏘았으나 알고 보니 아버지 B가 맞아 죽은 경우, A에 대한 보통살인 미수와 B에 대한 과실치사죄가 성립한다.\nㄹ. 甲이 상해의 고의로 A를 향해 돌을 던졌으나 빗나가서 옆에 있던 B가 맞은 경우, 법정적 부합설에 따르면 B에 대한 상해기수죄가 성립한다.","o":["ㄱ, ㄷ","ㄴ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":3}},{"y":2016,"e":"국가직 9급","qn":3,"i":"N92016-03-1","t":"甲은 A를 살해하려고 기다리다가 그와 닮은 B를 A로 오인하여 살해한 경우 구체적 부합설에 따르면 B에 대한 살인죄가 성립한다.","ox":"O","m":"①","c":"A","tp":"사실의 착오"},{"y":2016,"e":"국가직 9급","qn":3,"i":"N92016-03-2","t":"甲은 형 A를 살해하려고 기다리다가 아버지 B를 A로 오인하여 살해한 경우 법정적 부합설에 따르면 보통살인죄의 미수와 존속살해죄의 상상적 경합이 된다.","ox":"X","m":"②","c":"A","tp":"사실의 착오"},{"y":2016,"e":"국가직 9급","qn":3,"i":"N92016-03-3","t":"甲이 A를 살해하려고 총을 쏘았으나 빗나가 옆에 있던 B가 맞아 사망한 경우 구체적 부합설에 따르면 A에 대한 살인미수죄와 B에 대한 과실치사죄의 상상적 경합이 된다.","ox":"O","m":"③","c":"A","tp":"사실의 착오"},{"y":2016,"e":"국가직 9급","qn":3,"i":"N92016-03-4","t":"甲이 A라고 생각하고 전화를 하여 협박하였는데 사실은 A가 아닌 B가 그 협박전화를 받은 경우 법정적 부합설에 따르면 B에 대한 협박죄가 성립한다.","ox":"O","m":"④","c":"A","tp":"사실의 착오"},{"y":2016,"e":"국가직 9급","qn":5,"i":"N92016-05-1","t":"공사현장감독인이 공사의 발주자에 의하여 현장감독에 임명된 것이 아니고, 건설업법상 요구되는 현장건설기술자의 자격도 없다면 업무상과실책임을 물을 수 없다.","ox":"X","m":"①","c":"A","tp":"과실범"},{"y":2016,"e":"국가직 9급","qn":5,"i":"N92016-05-2","t":"의사 甲이 수술 전에 피해자에 대한 혈청에 의한 간기능검사를 하였더라면 피해자가 사망하지 않았을 것임이 입증되지 않더라도 간기능검사를 시행하지 않은 甲의 과실과 피해자의 사망 사이에는 인과관계가 있다.","ox":"X","m":"②","c":"A","tp":"과실범"},{"y":2016,"e":"국가직 9급","qn":5,"i":"N92016-05-3","t":"환자의 주치의 겸 정형외과 전공의 甲이 같은 과 수련의 乙의 처방에 대한 감독의무를 소홀히 한 나머지, 환자가 乙의 잘못된 처방으로 인하여 상해를 입게 된 경우, 甲은 업무상 과실치상죄가 성립한다.","ox":"O","m":"③","c":"A","tp":"과실범"},{"y":2016,"e":"국가직 9급","qn":5,"i":"N92016-05-4","t":"과실범의 주의의무위반은 정상의 주의를 태만히 하는 것을 의미하고, 그 과실의 유무를 판단함에는 행위 당시의 행위자 자신이 기울일 수 있었던 주의 정도를 기준으로 판단한다.","ox":"X","m":"④","c":"A"},{"y":2016,"e":"국가직 9급","qn":11,"i":"N92016-11-1","t":"보호자의 간청에 따라 치료를 요하는 환자에 대하여 치료중단 및 퇴원을 허용하는 조치를 취함으로써 환자를 사망에 이르게 한 담당 전문의와 주치의에게는 부작위에 의한 살인죄의 공동정범이 성립한다.","ox":"X","m":"①","c":"A","tp":"부작위범"},{"y":2016,"e":"국가직 9급","qn":11,"i":"N92016-11-2","t":"부작위범의 작위의무에는 법적인 의무뿐만 아니라 도덕상 의무와 종교상 의무도 포함된다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"국가직 9급","qn":11,"i":"N92016-11-3","t":"인터넷 포털사이트 내 오락채널 총괄팀장과 오락채널 내 만화사업의 운영 직원은 콘텐츠제공업체들이 게재하는 음란 만화의 삭제를 요구할 조리상의 의무가 있다.","ox":"O","m":"③","c":"A","tp":"부작위범"},{"y":2016,"e":"국가직 9급","qn":11,"i":"N92016-11-4","t":"토지에 대하여 도시계획이 입안되어 있어 장차 협의매수되거나 수용될 것이라는 사정을 매수인에게 고지하지 아니하고 토지를 매도한 매도인에게는 신의칙상 고지의무가 없으므로 부작위에 의한 사기죄가 성립하지 않는다.","ox":"X","m":"④","c":"A","tp":"부작위범"},{"y":2016,"e":"국가직 9급","qn":18,"i":"N92016-18-1","t":"甲이 식당주인 A를 살해할 의사로 농약 1포를 숭늉그릇에 투입하여 식당에 놓아두었는데, 식당주인의 딸 B가 이를 마시고 사망한 경우, 甲은 살인죄가 아닌 과실치사죄가 성립한다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"국가직 9급","qn":18,"i":"N92016-18-2","t":"선박침몰 등과 같은 급박한 상황이 발생한 경우에 선박의 운항을 지배하고 있는 선장 甲이 자신에게 요구되는 개별적·구체적인 구호의무를 이행함으로써 사망의 결과를 쉽게 방지할 수 있음에도 이를 방관하여 승객의 사망을 초래한 경우, 甲은 부작위에 의한 살인죄가 성립한다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"국가직 9급","qn":18,"i":"N92016-18-3","t":"甲이 7세, 3세 남짓된 어린 자식들에게 함께 죽자고 자살을 권유하여 죽음에 이르게 한 경우 甲은 자살교사·방조죄가 성립한다.","ox":"X","m":"③","c":"A"},{"y":2016,"e":"국가직 9급","qn":18,"i":"N92016-18-4","t":"군인 甲이 하사 A를 살해할 목적으로 발사한 총탄에 이를 제지하려고 甲 앞으로 뛰어들던 병장 B가 맞아 사망한 경우 甲은 A에 대한 살인미수죄와 B에 대한 과실치사죄의 상상적 경합이 된다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"국가직 9급","qn":3,"i":"N92017-03-1","t":"상태범은 행위자의 행위가 위법상태를 한 번야기함으로 기수가 되고 동시에 종료되는 범죄로, 이미 야기한 위법상태에 포섭되는 기수 후의 행위는 불가벌적 사후행위가 된다.","ox":"O","m":"①","c":"A","tp":"구성요건의 유형"},{"y":2017,"e":"국가직 9급","qn":3,"i":"N92017-03-2","t":"구체적 위험범은 법익 침해의 결과 발생을 요하지는 않지만 법익 침해의 현실적 위험이 발생하여야 하는 범죄이다.","ox":"O","m":"②","c":"A","tp":"구성요건의 유형"},{"y":2017,"e":"국가직 9급","qn":3,"i":"N92017-03-3","t":"거동범은 행위자가 직접 거동을 하여야 하는 범죄로 간접 정범의 형태로 범할 수 없는 범죄이다.","ox":"X","m":"③","c":"A","tp":"구성요건의 유형"},{"y":2017,"e":"국가직 9급","qn":3,"i":"N92017-03-4","t":"부진정신분범은 신분이 범죄의 성립에 영향을 미치지 않지만 형의 경중에 영향을 미치는 범죄이다.","ox":"O","m":"④","c":"A","tp":"구성요건의 유형"},{"y":2017,"e":"국가직 9급","qn":4,"i":"N92017-04-1","t":"중앙선 표시가 있는 직선도로에서 특별한 사정이 없는 한 그 대향차선상의 차량이 중앙선을 넘어 반대차선에 진입하지 않으리라고 믿는 것이 우리의 경험칙에 합당하다.","ox":"O","m":"①","c":"A","tp":"과실범에서 신뢰의 원칙"},{"y":2017,"e":"국가직 9급","qn":4,"i":"N92017-04-2","t":"약사가 의약품을 판매하거나 조제함에 있어서 특별한 사정이 없는 한 그 약의 포장상의 표시를 신뢰하고 이를 사용한 경우에는 과실이 없다.","ox":"O","m":"②","c":"A","tp":"과실범에서 신뢰의 원칙"},{"y":2017,"e":"국가직 9급","qn":4,"i":"N92017-04-3","t":"의사가 환자에 대하여 다른 의사와 의료행위를 분담하는 경우에 다른 의사의 전공과목에 전적으로 속하는 사항에 대하여는 다른 의사가 하는 의료행위의 내용이 적절한 것인지의 여부를 확인하고 감독하여야 할 업무상 주의의무가 없다.","ox":"O","m":"③","c":"A","tp":"과실범에서 신뢰의 원칙"},{"y":2017,"e":"국가직 9급","qn":4,"i":"N92017-04-4","t":"횡단보도의 보행자 신호등이 적색으로 표시된 경우에도 운전자는 보행자가 적색신호를 무시하고 갑자기 뛰어나올 가능성에 대비하여 운전하여야 할 업무상의 주의의무가 있다.","ox":"X","m":"④","c":"A","tp":"과실범에서 신뢰의 원칙"},{"y":2017,"e":"국가직 9급","qn":5,"i":"N92017-05-1","t":"어떤 범죄가 작위와 동시에 부작위에 의하여도 실현될 수 있는 경우, 행위자가 작위에 의하여 타인의 법익을 침해하고 침해 상태를 부작위에 의해 유지하였더라도 작위에 의한 범죄로 봄이 원칙이다.","ox":"O","m":"①","c":"A","tp":"부작위범"},{"y":2017,"e":"국가직 9급","qn":5,"i":"N92017-05-2","t":"익사직전의 아이에 대한 보증인 지위가 인정되더라도 구조가 불가능한 상황에서는 부작위범이 성립할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"국가직 9급","qn":5,"i":"N92017-05-3","t":"부작위범에 있어서 작위의무는 윤리적 의무가 아니라 법적 의무이므로 사회상규 혹은 조리에 의한 작위의무는 발생하지 않는다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"국가직 9급","qn":5,"i":"N92017-05-4","t":"기망행위라는 특정한 행위방법을 요건으로 하는 사기죄의 경우에는 부작위에 의한 기망행위가 작위의 기망행위와 동등한 의미를 가진다고 판단될 때 부작위에 의한 사기죄가 성립된다.","ox":"O","m":"④","c":"A","tp":"부작위범"},{"y":2017,"e":"국가직 9급","qn":6,"i":"N92017-06-1","t":"고의는 일반적 주관적 불법요소로서 인적 행위불법의 핵심적 요소에 해당한다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"국가직 9급","qn":6,"i":"N92017-06-2","t":"목적범에서 ‘목적’은 범죄성립을 위하여 고의 외에 요구되는 초과주관적 위법요소이다.","ox":"O","m":"②","c":"A","tp":"주관적 불법요소"},{"y":2017,"e":"국가직 9급","qn":6,"i":"N92017-06-3","t":"사문서위조죄는 행위자가 ‘행사할 목적’으로 사문서를 위조할 것을 규정하고 있으므로 여기서의 목적은 일반적 주관적 불법요소에 해당한다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"국가직 9급","qn":6,"i":"N92017-06-4","t":"불법영득의사는 과실범에서는 있을 수 없고 고의범에서만 있을 수 있는 특수한 주관적 불법요소(초과 주관적 구성요건 요소)에 해당한다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"국가직 9급","qn":12,"i":"N92017-12-1","t":"행정상의 단속을 주안으로 하는 법규라 하더라도 명문규정이 있거나 해석상 과실범도 벌할 뜻이 명확한 경우를 제외하고는 고의가 있어야 벌할 수 있다.","ox":"O","m":"①","c":"A","tp":"주관적 구성요건요소"},{"y":2017,"e":"국가직 9급","qn":12,"i":"N92017-12-2","t":"목적범에서의 목적은 목적내용에 대한 적극적 의욕이나 확정적 인식까지는 요하지 않고 미필적 인식으로도 족하다.","ox":"O","m":"②","c":"A","tp":"주관적 구성요건요소"},{"y":2017,"e":"국가직 9급","qn":12,"i":"N92017-12-3","t":"공연음란죄는 행위의 음란성에 대한 의미의 인식 이외에 주관적으로 성욕의 흥분 또는 만족 등의 성적인 목적이 있어야 성립한다.","ox":"X","m":"③","c":"A","tp":"주관적 구성요건요소"},{"y":2017,"e":"국가직 9급","qn":12,"i":"N92017-12-4","t":"부진정부작위범의 고의는 법익침해의 결과발생을 방지할 법적 작위의무를 가지고 있는 사람이 의무를 이행함으로써 결과발생을 쉽게 방지할 수 있었음을 예견하고도 결과발생을 용인하고 이를 방관한 채 의무를 이행하지 아니한다는 인식을 하면 족하며, 이러한 작위의무자의 예견 또는 인식 등이 불확정적인 경우이더라도 미필적 고의로 인정될 수 있다.","ox":"O","m":"④","c":"A","tp":"주관적 구성요건요소"},{"y":2017,"e":"국가직 9급","qn":19,"i":"N92017-19-1","t":"甲이 고속도로 2차로를 따라 자동차를 운전하다가 1차로를 진행하던 乙의 차량 앞에 급하게 끼어든 후 곧바로 정차하여 乙의 차량은 급정차하였고 그 뒤를 따라오던 丙의 차량이 乙의 차량과 추돌하여 丙이 사망한 경우, 丙에게 안전거리 미확보의 과실이 인정된다면 甲의 정차행위와 丙의 사망 사이에는 인과관계가 없다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"국가직 9급","qn":19,"i":"N92017-19-2","t":"한의사인 甲이 乙에게 문진하여 과거 봉침을 맞고도 별다른 이상반응이 없었다는 답변을 듣고 부작용에 대한 충분한 사전 설명 없이 환부에 봉침시술을 하였는데 乙이 위 시술 직후 쇼크반응을 나타내는 등 상해를 입은 경우, 설명의무를 다하였다 하더라도 乙이 반드시 봉침시술을 거부하였을 것이라고 볼 수 없다면 甲의 설명의무 위반과 乙의 상해 사이에 상당인과관계를 인정하기는 어렵다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"국가직 9급","qn":19,"i":"N92017-19-3","t":"甲이 乙의 뺨을 때리고 오른손으로 목을 쳐 乙이 뒤로 넘어지면서 머리를 땅바닥에 부딪쳐 상해를 입었고 결국 乙은 병원치료를 받다가 합병증으로 사망에 이르게 되었으나 乙이 원래 앓고 있던 간경화 등의 질환이 그 합병증의 유발에 영향을 미친 경우, 甲의 乙에 대한 폭행행위와 乙의 사망 사이에는 인과관계가 없다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"국가직 9급","qn":19,"i":"N92017-19-4","t":"살인의 실행행위와 피해자의 사망과의 사이에 다른 사실이 개재되어 그 사실이 치사의 직접적인 원인이 되었다면 살인의 실행행위와 피해자의 사망과의 사이에 인과관계를 인정할 수 없다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"국가직 9급","qn":2,"i":"N92018-02-1","t":"부진정부작위범에서 사회상규 혹은 조리상 작위의무가 기대되는 경우 법적인 작위의무는 없다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"국가직 9급","qn":2,"i":"N92018-02-2","t":"부진정부작위범은 작위범에 비해 불법의 정도가 경하므로, 형법은 이를 임의적 감경사유로 규정하고 있다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"국가직 9급","qn":2,"i":"N92018-02-3","t":"부진정부작위범에서 부작위가 작위와 같이 평가될 수 있기 위해서는 부작위범에게 결과발생을 방지하여야 할 보증인지위가 있어야 한다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"국가직 9급","qn":2,"i":"N92018-02-4","t":"형법상 방조행위는 정범의 실행행위를 용이하게 하는 직·간접의 모든 행위를 가리키는 것으로서 부작위에 의해서는 성립되지 않는다.","ox":"X","m":"④","c":"A","tp":"부작위범"},{"y":2018,"e":"국가직 9급","qn":5,"i":"N92018-05","t":"다음 중 고의의 인식 대상에 해당하지 않는 것은?","c":"A","mc":{"s":"다음 중 고의의 인식 대상에 해당하지 않는 것은?","d":"","o":["형법 제347조 사기죄에서의 기망행위","형법 제262조 폭행치사죄에서의 사망의 결과","형법 제245조 공연음란죄에서의 공연성","형법 제129조제1항 수뢰죄에서의 공무원 또는 중재인이라는 신분"],"a":2}},{"y":2018,"e":"국가직 9급","qn":8,"i":"N92018-08-1","t":"甲은 A를 살해할 의사로 A의 물병에 독약을 탔으나 A의 개가 이 물을 마시고 죽은 경우 구체적 부합설에 따르면 살인미수죄와 손괴죄의 상상적 경합이 성립한다.","ox":"X","m":"①","c":"A","tp":"사실의 착오"},{"y":2018,"e":"국가직 9급","qn":8,"i":"N92018-08-2","t":"甲은 절취의 의사로 A의 지갑을 몰래 가지고 왔으나 알고 보니 그 지갑이 B의 지갑이었던 경우 법정적 부합설에 따르면 A에 대한 절도미수죄가 성립한다.","ox":"X","m":"②","c":"A","tp":"사실의 착오"},{"y":2018,"e":"국가직 9급","qn":8,"i":"N92018-08-3","t":"甲은 A를 살해할 의사로 돌로 내려쳐 정신을 잃고 늘어지자 A가 죽었다고 생각하고 A를 웅덩이에 묻었으나 사실은 A가 매장으로 인하여 질식사한 경우 판례에 따르면 A에 대한 살인미수죄와 과실치사죄의 상상적 경합이 성립한다.","ox":"X","m":"③","c":"A","tp":"사실의 착오"},{"y":2018,"e":"국가직 9급","qn":8,"i":"N92018-08-4","t":"甲은 A를 상해할 의사로 깨진 유리를 A에게 휘둘렀으나 甲을 말리려던 B가 끼어들며 유리에 찔려 부상을 입은 경우 구체적 부합설에 따르면 A에 대한 상해미수죄와 B에 대한 과실치상죄의 상상적 경합이 성립한다.","ox":"O","m":"④","c":"A","tp":"사실의 착오"},{"y":2019,"e":"국가직 9급","qn":1,"i":"N92019-01-1","t":"시간적 차이가 있는 독립된 상해행위나 폭행행위가 경합하여 사망의 결과가 일어나고 그 사망의 원인된 행위가 판명되지 아니한 경우에는 공동정범의 예에 의하여 처벌한다.","ox":"O","m":"①","c":"A","tp":"형법 제263조(동시범)"},{"y":2019,"e":"국가직 9급","qn":1,"i":"N92019-01-2","t":"처음에는 甲이, 그 다음에는 甲의 연락을 받고 온 乙과 丙이 함께 잡귀를 물리친다면서 피해자의 팔과 다리를 붙잡고 배와 가슴을 손과 무릎으로 힘껏 누르고 밟아 피해자가 복강내출혈로 사망에 이르렀으나 원인행위가 판명되지 아니한 경우에는 동시범의 문제가 발생하지 않는다.","ox":"O","m":"②","c":"A","tp":"형법 제263조(동시범)"},{"y":2019,"e":"국가직 9급","qn":1,"i":"N92019-01-3","t":"피고인은 자신의 행위와 상해의 결과 사이에 개별 인과관계가 존재하지 않음을 입증하더라도 상해의 결과에 대한 책임에서 벗어날 수 없다.","ox":"X","m":"③","c":"A","tp":"형법 제263조(동시범)"},{"y":2019,"e":"국가직 9급","qn":1,"i":"N92019-01-4","t":"형법 제263조는 상해와 폭행죄에 관한 특별규정으로서 그 보호법익을 달리하는 강간치상죄에는 적용할 수 없다.","ox":"O","m":"④","c":"A","tp":"형법 제263조(동시범)"},{"y":2019,"e":"국가직 9급","qn":5,"i":"N92019-05-1","t":"법인격 없는 사단과 같은 단체는 법인과 마찬가지로 사법상의 권리의무의 주체가 될 수 있음은 별론으로 하더라도 법률에 명문의 규정이 없는 한 범죄능력은 없다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"국가직 9급","qn":5,"i":"N92019-05-2","t":"특별한 근거규정이 없는 한 법인이 설립되기 이전에 자연인이 한 행위에 대해서는 양벌규정을 적용하여 법인을 처벌할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"국가직 9급","qn":5,"i":"N92019-05-3","t":"합병으로 인하여 소멸한 법인이 그 종업원 등의 위법행위에 대해 양벌규정에 따라 부담하던 형사책임은 합병으로 인하여 존속하는 법인에 승계되지 않는다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"국가직 9급","qn":5,"i":"N92019-05-4","t":"지방자치단체가 국가로부터 위임받은 사무를 처리하는 경우에도 지방자치단체는 국가기관과는 별도의 독립한 공법인이므로 양벌규정에 의한 처벌대상이 되는 법인에 해당한다.","ox":"X","m":"④","c":"A"},{"y":2019,"e":"국가직 9급","qn":8,"i":"N92019-08-1","t":"존재하지 않는 형벌법규를 존재하는 것으로 오인하고 행위한 때에도 그 행위에 위험성이 있으면 불능미수로 처벌할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"국가직 9급","qn":8,"i":"N92019-08-2","t":"형이 면제되는 친족관계가 있다고 오인하고 절도하였더라도 절도죄의 성립은 물론이고 처벌에도 아무런 영향이 없다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"국가직 9급","qn":8,"i":"N92019-08-3","t":"피교사자의 객체의 착오는 교사자에게 방법의 착오가 된다는 견해가 방법의 착오에 관한 구체적 부합설을 취하면, 甲이 乙에게 A를 살해할 것을 교사하였으나 乙이 B를 A로 오인하여 B를 살해한 경우 甲은 B에 대한 살인교사의 죄책을 진다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"국가직 9급","qn":8,"i":"N92019-08-4","t":"甲이 상해의 고의로 A를 구타하여 A가 정신을 잃자 사망한 것으로 오인하고, A가 자살한 것처럼 가장하기 위하여 A를 베란다 아래로 떨어뜨려 사망하게 한 경우에는 포괄하여 하나의 살인죄가 성립한다.","ox":"X","m":"④","c":"A"},{"y":2019,"e":"국가직 9급","qn":12,"i":"N92019-12","t":"甲이 성냥불로 담배에 불을 붙인 다음 그 성냥불이 꺼진 것을 확인하지 아니한 채 휴지가 들어 있는 플라스틱 휴지통에 던져 화재가 발생한 경우 ㄴ.","c":"A","mc":{"s":"甲이 성냥불로 담배에 불을 붙인 다음 그 성냥불이 꺼진 것을 확인하지 아니한 채 휴지가 들어 있는 플라스틱 휴지통에 던져 화재가 발생한 경우 ㄴ.","d":"다음 사례 중 甲에게 중과실이 인정되는 것만을 모두 고르면? (다툼이 있는 경우 판례에 의함)\nㄱ.  임차인이 甲으로부터 임차하여 사용하던 방의 문에 약간의 틈이 있다거나 연통 등 가스배출시설에 사소한 결함이 있는 정도의 하자로 인해 임차인이 그 방에서 연탄가스에 중독되어 사망한 경우\nㄷ. 甲이 84세 노인과 11세 아이를 상대로 안수기도를 하면서 피해자들의 배와 가슴 부분을 세게 때리고 누르는 행위를 노인에게는 약 20분간, 아이에게는 약 30분간 반복하여 사망하게 한 경우\nㄹ. 전기에 관한 전문지식이 없는 호텔오락실의 경영자 甲이 그 오락실 천정에 형광등을 설치하는 공사를 하면서 그 호텔의 전기보안담당자에게 아무런 통고를 하지 아니한 채 무자격전기기술자로 하여금 전기공사를 하게 하여 화재가 발생한 경우","o":["ㄱ, ㄷ","ㄴ, ㄷ","ㄱ, ㄴ, ㄹ","ㄱ, ㄷ, ㄹ"],"a":1}},{"y":2020,"e":"국가직 9급","qn":5,"i":"N92020-05-1","t":"의사가 자신의 환자에 대하여 다른 의사를 지휘·감독하는 지위에 있다면, 그 의료영역이 다른 의사에게 전적으로 위임된 경우라도 다른 의사의 의료행위 내용이 적절한 것인지를 확인하고 감독하여야 할 업무상 주의의무가 있다.","ox":"X","m":"①","c":"A","tp":"의료행위에 있어서 과실 여부"},{"y":2020,"e":"국가직 9급","qn":5,"i":"N92020-05-2","t":"내과의사가 신경과 전문의와의 협의진료 결과를 신뢰하여 뇌혈관계통 질환의 가능성을 배제하고 피해자의 증세 호전에 따라 퇴원조치한 경우, 피해자의 지주막하출혈을 발견하지 못한 데 대한 업무상과실이 인정된다.","ox":"X","m":"②","c":"A","tp":"의료행위에 있어서 과실 여부"},{"y":2020,"e":"국가직 9급","qn":5,"i":"N92020-05-3","t":"의료인의 과실 유무를 판단함에는 같은 업무와 직무에 종사하는 일반적 보통인의 주의 정도를 표준으로 하여야 하며, 사고 당시의 일반적 의학수준과 의료환경 등이 고려되어야 한다.","ox":"O","m":"③","c":"A","tp":"의료행위에 있어서 과실 여부"},{"y":2020,"e":"국가직 9급","qn":5,"i":"N92020-05-4","t":"의사는 적절한 진료방법을 선택할 상당한 범위의 재량을 갖는 것이어서, 어떤 진료방법을 선택하였더라도 진료 결과를 놓고 어느 하나만이 정당하고 이와 다른 조치를 취한 것에 과실이 있다고 할 수 없다.","ox":"X","m":"④","c":"A","tp":"의료행위에 있어서 과실 여부"},{"y":2020,"e":"국가직 9급","qn":6,"i":"N92020-06","t":"괄호 안에 기재된 범죄에 대한 미필적 고의가 인정되지 않는 것은?","c":"A","mc":{"s":"괄호 안에 기재된 범죄에 대한 미필적 고의가 인정되지 않는 것은?","d":"","o":["피고인이 만 12세의 피해자를 강간할 당시 피해자가 자신을 중학교 1학년이라 14세라고 하였고, 피해자는 키와 체중이 동급생보다 큰 편이었으며, 이들이 모텔에 들어갈 때 특별한 제지도 받지 아니하였다. (성폭력범죄의처벌등에관한특례법 위반－13세미만미성년자강간등)","피고인이 피해자의 머리나 가슴 등 치명적인 부위가 아닌 허벅지와 종아리 부위 등을 20여 회 힘껏 찔러 피해자가 과다실혈로 사망하였다. (살인)","피고인이 청소년으로 의심되는 피해자에게 단지 나이만 묻고 신분증 등으로 정확히 연령을 확인하지 않은 채 청소년인 피해자를 성매매 알선을 위한 종업원으로 고용하여 성매매 알선행위를 업으로 하였다. (아동․청소년의성보호에관한법률 위반－알선영업행위등)","피고인이 이미 도산이 불가피한 상황으로 대금지급이 불가능 하게 될 가능성을 충분히 인식하면서도 이러한 사정을 숨기고 피해자로부터 생산자재용 물품을 납품받았다. (사기)"],"a":1}},{"y":2020,"e":"국가직 9급","qn":9,"i":"N92020-09-1","t":"내란죄는 다수인이 한 지방의 평온을 해할 정도의 폭동을 하였을 때 이미 그 구성요건이 완전히 충족된다고 할 것이어서 상태범으로 봄이 상당하다.","ox":"O","m":"①","c":"A","tp":"범죄유형"},{"y":2020,"e":"국가직 9급","qn":9,"i":"N92020-09-2","t":"폭력행위 등 처벌에 관한 법률 제4조 소정의 ‘단체 등의 조직’죄는 같은 법에 규정된 범죄를 목적으로 한 단체 또는 집단을 구성함으로써 즉시 성립하고 그와 동시에 완성되는 즉시범이지 계속범이 아니다.","ox":"O","m":"②","c":"A","tp":"범죄유형"},{"y":2020,"e":"국가직 9급","qn":9,"i":"N92020-09-3","t":"직무유기죄는 직무를 수행하지 아니하는 위법한 부작위상태가 계속되는 한 가벌적 위법상태가 계속 존재한다고 할 것이므로 즉시범이라고 할 수 없다.","ox":"O","m":"③","c":"A","tp":"범죄유형"},{"y":2020,"e":"국가직 9급","qn":9,"i":"N92020-09-4","t":"군형법 제79조에 규정된 무단이탈죄는 허가 없이 근무장소 또는 지정장소를 일시이탈한 기간 동안 행위가 지속된다는 점에서 계속범에 해당한다.","ox":"X","m":"④","c":"A","tp":"범죄유형"},{"y":2021,"e":"국가직 9급","qn":1,"i":"N92021-01-1","t":"선행행위로 인한 부작위범의 경우 선행행위에 대한 고의·과실 혹은 유책·위법이 없는 경우에도 작위의무는 발생할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"국가직 9급","qn":1,"i":"N92021-01-2","t":"부작위범 사이의 공동정범은 다수의 부작위범에게 공통된 의무가 부여되어 있고, 그 의무를 공통으로 이행할 수 있을 때에만 성립한다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"국가직 9급","qn":1,"i":"N92021-01-3","t":"부진정부작위범의 성립요건으로서 작위의무는 법적 작위의무 이어야 하므로, 사회상규 혹은 조리상 작위의무가 기대되는 경우에는 인정되지 않는다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"국가직 9급","qn":1,"i":"N92021-01-4","t":"사기죄에 있어서 부작위에 의한 기망은 법률상 고지의무 있는 자가 일정한 사실에 관하여 상대방이 착오에 빠져 있음을 알면서도 이를 고지하지 아니하는 것을 말한다.","ox":"O","m":"④","c":"A","tp":"부작위범"},{"y":2021,"e":"국가직 9급","qn":2,"i":"N92021-02","t":"형법 상 범죄와 그 범죄의 유형을 바르게 연결한 것은?","c":"A","mc":{"s":"형법 상 범죄와 그 범죄의 유형을 바르게 연결한 것은?","d":"","o":["배임죄－침해범","범인도피죄－즉시범","모해위증죄－부진정 신분범","일반교통방해죄－구체적 위험범"],"a":3}},{"y":2021,"e":"국가직 9급","qn":7,"i":"N92021-07-1","t":"정상의 주의를 태만함으로 인하여 죄의 성립요소인 사실을 인식하지 못한 행위는 법률에 특별한 규정이 있는 경우에 한하여 처벌한다.","ox":"O","m":"①","c":"A","tp":"과실범과 결과적 가중범"},{"y":2021,"e":"국가직 9급","qn":7,"i":"N92021-07-2","t":"의료과오사건에서 의사의 과실이 있는지는 같은 업무 또는 분야에 종사하는 평균적인 의사가 보통 갖추어야 할 통상의 주의의무를 기준으로 판단하여야 한다.","ox":"O","m":"②","c":"A","tp":"과실범과 결과적 가중범"},{"y":2021,"e":"국가직 9급","qn":7,"i":"N92021-07-3","t":"형법상 결과적 가중범의 기본범죄에는 고의범·과실범뿐만 아니라 기수·미수도 포함된다.","ox":"X","m":"③","c":"A","tp":"과실범과 결과적 가중범"},{"y":2021,"e":"국가직 9급","qn":7,"i":"N92021-07-4","t":"부진정결과적 가중범에서 고의로 중한 결과를 발생하게 한 행위가 별도의 구성요건에 해당하고 그 고의범에 대하여 결과적 가중범에 정한 형보다 더 무겁게 처벌하는 규정이 없는 경우, 결과적 가중범이 고의범에 대하여 특별관계에 있으므로 결과적 가중범만 성립한다.","ox":"O","m":"④","c":"A","tp":"과실범과 결과적 가중범"},{"y":2021,"e":"국가직 9급","qn":10,"i":"N92021-10","t":"인과관계에 대한 설명으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"인과관계에 대한 설명으로 옳은 것만을 모두 고르면?","d":"(다툼이 있는 경우 판례에 의함)\nㄱ. 부작위범에 있어서 작위의무를 이행하였다면 결과가 발생하지 않았을 것이라는 관계가 인정될 경우 부작위와 그 결과 사이에 인과관계가 있다.\nㄴ. 사기죄는 타인을 기망하여 착오에 빠뜨리고 처분행위를 유발하여 재물을 교부받거나 재산상 이익을 얻음으로써 성립하는 것으로, 기망행위와 상대방의 착오 및 재물의 교부 또는 재산상 이익의 공여 사이에 순차적인 인과관계가 있어야 한다.\nㄷ. 의사가 설명의무를 위반한 채 의료행위를 하였다가 환자에게 상해의 결과가 발생한 경우, 의사에게 업무상과실로 인한 형사책임을 지우기 위해서는 의사의 설명의무 위반과 환자의 상해 사이에 상당인과관계가 존재하여야 한다.\nㄹ. 선행 교통사고와 후행 교통사고 중 어느 쪽이 원인이 되어 피해자가 사망에 이르게 되었는지 밝혀지지 않은 경우, 후행 교통사고를 일으킨 사람의 과실과 피해자의 사망 사이에 인과관계가 인정되기 위해서는 후행 교통사고를 일으킨 사람이 주의의무를 게을리하지 않았다면 피해자가 사망에 이르지 않았을 것이라는 사실이 입증되어야 한다.","o":["ㄱ, ㄷ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":4}},{"y":2021,"e":"국가직 9급","qn":18,"i":"N92021-18-1","t":"외교상기밀누설죄(제113조제1항), 공무상비밀누설죄(제127조) 및 업무상비밀누설죄(제317조제1항)는 신분범이다.","ox":"X","m":"①","c":"A","tp":"형법 상 범죄의 구성요건"},{"y":2021,"e":"국가직 9급","qn":18,"i":"N92021-18-2","t":"수뢰죄(제129조제1항), 증뢰죄(제133조제1항) 및 알선수뢰죄 (제132조)는 뇌물을 약속한 때에도 성립한다.","ox":"O","m":"②","c":"A","tp":"형법 상 범죄의 구성요건"},{"y":2021,"e":"국가직 9급","qn":18,"i":"N92021-18-3","t":"직권남용죄(제123조), 불법체포·감금죄(제124조) 및 폭행·가혹행위죄(제125조)의 행위주체는 같다.","ox":"X","m":"③","c":"A","tp":"형법 상 범죄의 구성요건"},{"y":2021,"e":"국가직 9급","qn":18,"i":"N92021-18-4","t":"사전수뢰죄(제129조제2항)와 사후수뢰죄(제131조제3항)는 범죄의 성립에 ‘부정한 청탁’을 요구한다.","ox":"X","m":"④","c":"A","tp":"형법 상 범죄의 구성요건"},{"y":2023,"e":"국가직 9급","qn":5,"i":"N92023-05-1","t":"부진정결과적 가중범의 경우에 중한 결과에 대한 고의범과 결과적 가중범의 법정형이 같은 경우에는 결과적 가중범만 성립하지만, 중한 결과에 대한 고의범의 법정형이 결과적 가중범보다 중한 경우에는 결과적 가중범과 중한 결과에 대한 고의범은 상상적 경합관계에 있다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"국가직 9급","qn":5,"i":"N92023-05-2","t":"사람이 현존하는 건조물을 방화하는 집단행위의 과정에서 일부 집단원만이 고의행위로 살상을 가한 경우, 다른 집단원이 그 결과를 예견할 수 있었더라도 현존건조물방화치사상죄의 죄책을 인정할 수 없다.","ox":"X","m":"②","c":"A","tp":"결과적 가중범"},{"y":2023,"e":"국가직 9급","qn":5,"i":"N92023-05-3","t":"결과적 가중범에 있어서 중한 결과를 같이 발생시킬 의사가 없었더라도 행위를 공동으로 할 의사가 있고 중한 결과가 예견 가능한 것이었다면 결과적 가중범의 공동정범이 성립한다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"국가직 9급","qn":5,"i":"N92023-05-4","t":"조문형식상 결과적 가중범에 대한 미수범처벌규정이 있더라도 이는 결합범에만 적용되고, 결과적 가중범의 경우에는 중한 결과가 발생한 이상 기본범죄가 미수에 그쳐도 결과적 가중범의 기수범이 된다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"국가직 9급","qn":6,"i":"N92023-06","t":"구성요건요소에 대한 착오사례가 아닌 것은?","c":"A","mc":{"s":"구성요건요소에 대한 착오사례가 아닌 것은?","d":"","o":["甲이 성명불상자 3명과 싸우다가 힘이 달리자 옆 차에서 식칼을 가지고 나와 이들 3명을 상대로 휘두르다가 이를 말리던 A에게 상해를 입힌 경우","甲이 6층 호텔방에서 상해의 의사로 A를 구타하여 A가 정신을 잃고 쓰러지자 사망한 것으로 착각하고, A가 자살한 것으로 위장하기 위해 6층 아래로 떨어뜨려 사망케 한 경우","甲이 저작권 침해물 링크사이트를 운영하던 중 그러한 링크행위가 범죄에 해당하지 않는다는 대법원 판결이 선고되자 자신의 행위는 죄가 되지 않는다고 생각하고 계속 운영한 경우","甲이 살해의도로 피해자 A를 몽둥이로 내리쳤으나 A의 등에 업힌 피해자 B가 맞아 현장에서 두개골절 및 뇌좌상으로 사망한 경우"],"a":3}},{"y":2023,"e":"국가직 9급","qn":7,"i":"N92023-07","t":"미필적 고의에 대한 설명으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"미필적 고의에 대한 설명으로 옳은 것만을 모두 고르면?","d":"ㄱ. “결과가 발생할지도 몰라. 하지만 그래도 할 수 없지.”라고 생각했으면 미필적 고의가 인정되지만, “결과가 발생할지도 몰라. 그러나 괜찮을 거야.”라고 생각한 경우는 인식 없는 과실에 해당한다.\nㄴ. 경찰관이 차량 약 30 cm 전방에 서서 교통차단의 이유를 설명하고 있는데 운전자가 신경질적으로 갑자기 좌회전하여 우측 앞 범퍼 부분으로 해당 경찰관의 무릎을 들이받은 경우, 이는 경찰관을 충격한다는 결과의 발생을 용인하는 내심의 의사가 있었다고 봄이 경험칙상 당연하다.\nㄷ. 대구지하철 화재 사고 현장을 수습하기 위한 청소 작업이 한참 진행되고 있는 시간 중에 실종자 유족들로부터 이의제기가 있었음에도 즉각 청소작업을 중단하도록 지시하지 않고 수사기관과 협의하거나 확인하지 않은 경우, 그러한 청소작업으로 인한 증거인멸의 결과가 발생할 가능성을 용인하는 내심의 의사가 있었다고 단정하기는 어렵다.\nㄹ. 행위자가 범죄사실이 발생할 가능성을 용인하고 있었는지는 행위자의 진술에 의존하지 않고 외부에 나타난 행위의 형태와 행위의 상황 등 구체적인 사정을 기초로 일반인이라면 범죄사실이 발생할 가능성을 어떻게 평가할 것인지를 고려하면서 객관적 제3자의 입장에서 그 심리상태를 추인하여야 한다.","o":["ㄱ, ㄴ","ㄱ, ㄹ","ㄴ, ㄷ","ㄴ, ㄷ, ㄹ"],"a":3}},{"y":2024,"e":"국가직 9급","qn":1,"i":"N92024-01-1","t":"명예훼손죄가 성립하기 위해서는 범죄구성요건의 주관적 요소로서 공연성에 대한 미필적 고의가 필요하므로 전파가능성에 대한 인식이 있음은 물론 나아가 그 위험을 용인하는 내심의 의사가 있어야 한다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"국가직 9급","qn":1,"i":"N92024-01-2","t":"준강간의 고의는 피해자가 심신상실 또는 항거불능의 상태에 있다는 것과 그러한 상태를 이용하여 간음한다는 구성요건적 결과 발생의 가능성을 인식하고 그러한 위험을 용인하는 내심의 의사를 말한다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"국가직 9급","qn":1,"i":"N92024-01-3","t":"업무상 배임죄의 일반적인 고의의 법리와는 달리 경영상 판단의 경우에는 단순히 본인에게 손해가 발생하였다는 결과만으로도 업무상 배임죄의 성립을 인정할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2024,"e":"국가직 9급","qn":1,"i":"N92024-01-4","t":"방조범이 성립하기 위해서는 정범의 실행을 방조한다는 방조의 고의와 정범의 행위가 구성요건에 해당한다는 점에 대한 정범의 고의가 있어야 한다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"국가직 9급","qn":2,"i":"N92024-02-1","t":"이른바 부진정 부작위범은 작위를 내용으로 하는 범죄를 부작위에 의하여 실현하는 경우를 말한다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"국가직 9급","qn":2,"i":"N92024-02-2","t":"부진정 부작위범의 작위의무는 법적 의무이어야 하므로 사회상규 혹은 조리상 작위의무가 기대되는 경우에는 인정되지 않는다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"국가직 9급","qn":2,"i":"N92024-02-3","t":"부작위범 사이의 공동정범은 다수의 부작위범에게 공통된 의무가 부여되어 있고 그 의무를 공통으로 이행할 수 있는 경우에 성립한다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"국가직 9급","qn":2,"i":"N92024-02-4","t":"위험의 발생을 방지할 의무가 있는 자뿐만 아니라 자기의 행위로 인하여 위험발생의 원인을 야기한 자도 그 위험발생을 방지하지 않은 때에는 그 발생된 결과에 의하여 처벌한다.","ox":"O","m":"④","c":"A","tp":"부작위범"},{"y":2024,"e":"국가직 9급","qn":7,"i":"N92024-07-1","t":"방조범이 성립하려면 방조행위가 정범의 범죄실현과 밀접한 관련이 있고 정범으로 하여금 구체적 위험을 실현시키거나 범죄결과를 발생시킬 가능성을 높이는 등으로 현실적 기여를 하였다고 평가할 수 있는 인과관계가 필요하다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"국가직 9급","qn":7,"i":"N92024-07-2","t":"실화죄에 있어서 공동의 과실이 경합되어 화재가 발생하여 적어도 각 과실이 화재의 발생에 대하여 하나의 조건이 된 경우라도, 원인된 행위가 밝혀지지 않았다면 그 원인을 제공한 사람들은 실화죄의 미수로 불가벌에 해당한다.","ox":"X","m":"②","c":"A","tp":"인과관계"},{"y":2024,"e":"국가직 9급","qn":7,"i":"N92024-07-3","t":"정범의 실행행위 중에 이를 용이하게 하는 경우뿐만 아니라 정범의 실행착수 전에 장래의 실행행위를 예상하고 이를 용이하게 하는 경우에도 방조행위로서 정범의 실행행위에 대한 인과관계를 인정할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"국가직 9급","qn":7,"i":"N92024-07-4","t":"교사자가 전화로 범행을 만류하는 취지의 말을 한 것만으로는 교사자의 교사행위와 정범의 실행행위 사이에 인과관계가 단절 되었다거나 교사자가 공범관계에서 이탈한 것으로 볼 수 없다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"국가직 9급","qn":2,"i":"N92025-02-1","t":"특정한 행위를 하지 아니하는 부작위가 형법적으로 부작위로서의 의미를 가지기 위해서는 보호법익의 주체에게 해당 구성요건적 결과발생의 위험이 있는 상황에서 행위자가 구성요건의 실현을 회피하기 위하여 요구되는 행위를 현실적ㆍ물리적으로 행할 수 있었음에도 하지 아니하였다고 평가될 수 있어야 한다.","ox":"O","m":"①","c":"A","tp":"부작위범"},{"y":2025,"e":"국가직 9급","qn":2,"i":"N92025-02-2","t":"경찰공무원이 지명수배 중인 범인을 발견하고도 직무상 의무에 따른 적절한 조치를 취하지 아니하고 오히려 범인을 도피하게 하는 행위를 하였다면, 그 직무위배의 위법상태는 범인도피행위 속에 포함되어 있다고 보아야 할 것이므로, 이와 같은 경우에는 작위범인 범인도피죄만이 성립하고 부작위범인 직무유기죄는 따로 성립하지 아니한다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"국가직 9급","qn":2,"i":"N92025-02-3","t":"피고인이 공사대금을 받을 목적으로 자신의 공사를 위하여 쌓아 두었던 건축자재를 공사 완료 후에 단순히 치우지 않은 행위는 업무방해죄의 실행행위인 위력으로서 피해자의 추가 공사 업무에 대한 적극적인 방해행위와 동등한 형법적 가치를 가진다.","ox":"X","m":"③","c":"A","tp":"부작위범"},{"y":2025,"e":"국가직 9급","qn":2,"i":"N92025-02-4","t":"부작위범 사이의 공동정범은 다수의 부작위범에게 공통된 의무가 부여되어 있고, 그 의무를 공통으로 이행할 수 있을 때에만 성립 한다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"국가직 9급","qn":4,"i":"N92025-04-1","t":"자동차의 운전자가 통상 예견되는 상황에 대비하여 결과를 회피할 수 있는 정도의 주의의무를 다하지 못한 것이 교통사고 발생의 직접적인 원인이 되었다면, 비록 자동차가 보행자를 직접 충격한 것이 아니고 보행자가 자동차의 급정거에 놀라 도로에 넘어져 상해를 입은 경우라고 할지라도 업무상 주의의무 위반과 교통사고 발생 사이에 상당인과관계를 인정할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"국가직 9급","qn":4,"i":"N92025-04-2","t":"피고인이 좌회전 금지구역에서 좌회전을 하는 도중 50여 미터 후방에서 따라오던 후행 차량이 중앙선을 넘어 피고인 차량 좌측으로 돌진하여 사고가 발생하였다면, 좌회전 금지구역에서 좌회전한 행위와 사고 발생 사이에는 상당인과관계를 인정할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"국가직 9급","qn":4,"i":"N92025-04-3","t":"교통방해치사상죄에 있어서는 교통방해 행위가 피해자의 사상 이라는 결과를 발생하게 한 유일하거나 직접적인 원인이 된 경우만이 아니라, 그 행위와 결과 사이에 피해자나 제3자의 과실 등 다른 사실이 개재된 때에도 그와 같은 사실이 통상 예견될 수 있는 것이라면 상당인과관계를 인정할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"국가직 9급","qn":4,"i":"N92025-04-4","t":"甲이 A를 호텔 객실에 감금 후 강간하려 하자 A가 완강히 반항 하던 중, 甲이 대실시간을 연장하고자 전화하는 사이에 창문으로 탈출하려다가 추락하여 사망하였다면, 甲의 강간미수행위와 A의 사망 간의 상당인과관계를 인정할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"국가직 9급","qn":6,"i":"N92025-06-1","t":"아동ㆍ청소년의 성보호에 관한 법률 제11조제5항에서 정한 성착취물소지죄는 아동ㆍ청소년성착취물임을 알면서 소지를 개시한 때부터 지배관계가 종료한 때까지 하나의 죄로 평가되는 이른바 계속범이다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"국가직 9급","qn":6,"i":"N92025-06-2","t":"범인도피죄는 범인을 도피하게 함으로써 기수에 이르지만, 범인 도피행위가 계속되는 동안에는 범죄행위도 계속되고 행위가 끝날 때 비로소 범죄행위가 종료된다.","ox":"O","m":"②","c":"A","tp":"계속범"},{"y":2025,"e":"국가직 9급","qn":6,"i":"N92025-06-3","t":"일반교통방해죄에서 교통방해행위는 계속범의 성질을 가지는 것이어서 교통방해를 유발한 집회에서 다른 참가자들에 의해 이미 교통의 흐름이 차단된 상태였다고 하더라도 교통방해를 유발한 다른 참가자들과 암묵적ㆍ순차적으로 공모하여 교통방해의 위법 상태를 지속시켰다고 평가할 수 있다면 일반교통방해죄가 성립 한다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"국가직 9급","qn":6,"i":"N92025-06-4","t":"직무유기죄는 그 직무를 수행하여야 하는 작위의무를 수행하지 아니함으로써 구성요건에 해당하는 사실이 있다면 곧바로 범죄가 완성되고 이후 가벌적 위법상태가 계속된다고 볼 수 없어 계속범이 아닌 즉시범이라 할 것이다.","ox":"X","m":"④","c":"A"},{"y":2025,"e":"국가직 9급","qn":8,"i":"N92025-08-1","t":"행정상의 단속을 주안으로 하는 법규라 하더라도 명문규정이 있거나 해석상 과실범도 벌할 뜻이 명확한 경우를 제외하고는 형법의 원칙에 따라 고의가 있어야 벌할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"국가직 9급","qn":8,"i":"N92025-08-2","t":"법령에 의하여 도급인에게 수급인의 업무에 관하여 구체적인 관리ㆍ감독의무가 부여되거나 도급인이 공사의 시공이나 개별 작업에 관하여 구체적으로 지시ㆍ감독하였다는 등의 사정이 없더라도 도급인에게는 수급인의 업무와 관련하여 사고방지에 필요한 안전조치를 할 주의의무가 있다.","ox":"X","m":"②","c":"A","tp":"과실"},{"y":2025,"e":"국가직 9급","qn":8,"i":"N92025-08-3","t":"개별 법령에서 일일이 그 근거나 내용이 명시되어 있지 않다면, 결과 발생에 즈음한 구체적인 상황에서 이와 관련된 제반 사정들을 종합적으로 평가하여 결과 발생에 대한 예견 및 회피 가능성을 기준으로 삼더라도 그 결과 발생을 방지하여야 할 주의의무를 인정할 수는 없다.","ox":"X","m":"③","c":"A","tp":"과실"},{"y":2025,"e":"국가직 9급","qn":8,"i":"N92025-08-4","t":"의사가 환자에 대하여 주된 의사의 지위에서 진료하는 경우, 다른 의사에게 그 관련된 협의진료를 의뢰한 경우처럼 서로 대등한 지위에서 각자의 의료영역을 나누어 환자 진료의 일부를 분담하였더라도 진료를 분담받은 다른 의사의 전적인 과실로 환자에게 발생한 결과에 대하여 책임을 인정할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2025,"e":"국가직 9급","qn":20,"i":"N92025-20-1","t":"기본범죄를 통하여 고의로 중한 결과를 발생하게 한 경우에 가중 처벌하는 부진정 결과적 가중범에서 고의범에 대하여 더 무겁게 처벌하는 규정이 없는 경우, 그 결과적 가중범과 고의범은 상상적 경합의 관계에 있다.","ox":"X","m":"①","c":"A","tp":"특수한 범죄형태"},{"y":2025,"e":"국가직 9급","qn":20,"i":"N92025-20-2","t":"부진정부작위범이 성립하기 위해서는 부작위행위자에게 침해 위협으로부터 법익을 보호해 주어야 할 법적 작위의무가 있어야 하고, 부작위로 인한 법익침해가 작위에 의한 법익침해와 동등한 형법적 가치가 있는 것으로서 범죄의 실행행위로 평가되어야 한다. 다만 여기서의 작위의무는 법령, 법률행위, 선행행위로 인한 경우에만 인정되고, 신의성실의 원칙이나 사회상규 혹은 조리상 작위의무가 기대되는 경우에는 인정되지 아니한다.","ox":"X","m":"②","c":"A","tp":"특수한 범죄형태"},{"y":2025,"e":"국가직 9급","qn":20,"i":"N92025-20-3","t":"황색 실선이나 황색 점선으로 된 중앙선이 설치된 도로의 어느 구역에서 좌회전이나 유턴이 허용되어 중앙선이 백색 점선으로 표시되어 있는 지점에서 안전표지에 따라 좌회전이나 유턴을 하기 위하여 중앙선을 넘어 운행하다가 반대편 차로를 운행하는 차량과 충돌하는 교통사고를 낸 경우, 교통사고처리 특례법상 중앙선 침범 사고에 해당하지 아니한다.","ox":"O","m":"③","c":"A","tp":"특수한 범죄형태"},{"y":2025,"e":"국가직 9급","qn":20,"i":"N92025-20-4","t":"의료과오사건에서 의사의 과실을 인정하려면 결과 발생을 예견할 수 있고 또 회피할 수 있었는데도 예견하거나 회피하지 못한 점을 인정할 수 있어야 한다. 의사의 과실이 있는지는 의사가 아닌 평균인이 보통 갖추어야 할 통상의 주의의무를 기준으로 판단하여야 하고, 사고 당시의 일반적인 의학 수준, 의료환경과 조건, 의료행위의 특수성 등을 고려하여야 한다.","ox":"X","m":"④","c":"A","tp":"특수한 범죄형태"}],"5":[{"y":2015,"e":"국가직 9급","qn":11,"i":"N92015-11-1","t":"정범이 예비단계에 그친 경우 이에 가공한 행위는 예비죄의 공동정범으로는 물론 방조범으로도 처벌할 수 없다.","ox":"X","m":"①","c":"A","tp":"예비․음모"},{"y":2015,"e":"국가직 9급","qn":11,"i":"N92015-11-2","t":"예비·음모를 처벌한다는 규정이 있더라도 그 형을 따로 정하고 있지 않은 경우에는 처벌할 수 없다.","ox":"O","m":"②","c":"A","tp":"예비․음모"},{"y":2015,"e":"국가직 9급","qn":11,"i":"N92015-11-3","t":"예비·음모를 처벌하는 경우에 있어 행위자가 자의로 실행의 착수를 포기하였더라도 중지범 규정을 적용할 수 없다.","ox":"O","m":"③","c":"A","tp":"예비․음모"},{"y":2015,"e":"국가직 9급","qn":11,"i":"N92015-11-4","t":"살인죄의 예비행위는 단순히 범행의 의사 또는 계획만으로는 부족하고, 객관적으로 보아 살인죄 실현에 실질적으로 기여할 수 있는 외적 행위를 필요로 한다.","ox":"O","m":"④","c":"A","tp":"예비․음모"},{"y":2016,"e":"국가직 9급","qn":4,"i":"N92016-04","t":"중지미수에 있어서 자의성이 인정되는 경우는?","c":"A","mc":{"s":"중지미수에 있어서 자의성이 인정되는 경우는?","d":"","o":["甲은 강간의 실행에 착수하였으나 A가 다음에 만나서 친해지면 응해주겠다는 취지로 간곡하게 부탁을 하자 실행을 중지한 경우","甲은 강간의 실행에 착수하였으나 A가 시장에 간 남편이 곧 돌아올 것이고 자신이 현재 임신 중이라고 말하자 실행을 중지한 경우","甲은 A를 살해하려고 A의 목과 왼쪽 가슴을 칼로 수회 찔렀으나 A의 가슴에서 피가 많이 흘러나오는 것을 보고 겁이 나서 실행을 중지한 경우","甲은 A의 주택을 불태우려고 주택 안의 장롱에 있던 의류에 불을 놓았으나 불길이 치솟는 것을 보고 겁이 나서 물을 부어 불을 끈 경우"],"a":1}},{"y":2017,"e":"국가직 9급","qn":9,"i":"N92017-09-1","t":"미수범은 법률에 특별한 규정이 있는 경우에 한하여 예외적으로 처벌된다.","ox":"O","m":"①","c":"A","tp":"범죄의 실현단계"},{"y":2017,"e":"국가직 9급","qn":9,"i":"N92017-09-2","t":"범죄의 결심은 원칙적으로 처벌하지 않지만, 교사 받은 자가 범죄의 실행을 승낙하고 실행에 착수하지 않았다면 음모 또는 예비에 준하여 처벌한다.","ox":"O","m":"②","c":"A","tp":"범죄의 실현단계"},{"y":2017,"e":"국가직 9급","qn":9,"i":"N92017-09-3","t":"음모란 2인 이상이 범죄의 의사를 공유하는 것으로, 2인 이상이 일정한 범죄의 실행에 대한 결심을 외부에 표시·전달 하는 것만으로도 음모죄가 성립한다.","ox":"X","m":"③","c":"A","tp":"범죄의 실현단계"},{"y":2017,"e":"국가직 9급","qn":9,"i":"N92017-09-4","t":"계속범의 경우 기수에 이르렀어도 범죄가 종료되지 않은 경우에는 그 범죄에 대한 방조와 정당방위의 성립이 가능하다.","ox":"O","m":"④","c":"A","tp":"범죄의 실현단계"},{"y":2017,"e":"국가직 9급","qn":13,"i":"N92017-13-1","t":"야간에 아파트에 침입하여 물건을 훔칠 의도하에 아파트의 베란다 철제난간까지 올라가 유리창문을 열려고 시도하였다면 야간주거침입절도죄의 실행에 착수한 것으로 보아야 한다.","ox":"O","m":"①","c":"A","tp":"실행의 착수"},{"y":2017,"e":"국가직 9급","qn":13,"i":"N92017-13-2","t":"사기죄는 편취의 의사로 기망행위를 개시한 때에 실행에 착수한 것으로 보아야 하므로, 사기도박에서도 사기적인 방법으로 도금을 편취하려고 하는 자가 상대방에게 도박에 참가할 것을 권유하는 등 기망행위를 개시한 때에 실행의 착수가 있는 것으로 보아야 한다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"국가직 9급","qn":13,"i":"N92017-13-3","t":"제1차 매수인으로부터 계약금 및 중도금 명목의 금원을 교부 받은 후 제2차 매수인에게 부동산을 매도하기로 하고 계약금만을 지급받은 뒤 더 이상의 계약 이행에 나아가지 않았다면 배임죄의 실행의 착수가 있었다고 볼 수 없다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"국가직 9급","qn":13,"i":"N92017-13-4","t":"양팔을 높이 들어 갑자기 뒤에서 껴안으려는 행위를 하는 경우 행위자의 팔이 피해자의 몸에 닿지 않으면 강제추행죄의 실행의 착수를 인정할 수 없다.","ox":"X","m":"④","c":"A"},{"y":2019,"e":"국가직 9급","qn":13,"i":"N92019-13-1","t":"허위 내용의 고소장을 경찰관에게 제출하였다면 무고죄는 기수에 이르고 그 후 고소장을 되돌려 받았더라도 무고죄의 성립에는 영향이 없다.","ox":"O","m":"①","c":"A","tp":"미수․기수"},{"y":2019,"e":"국가직 9급","qn":13,"i":"N92019-13-2","t":"피해자를 살해하려고 낫을 들고 피해자에게 다가서려고 하였으나 제3자가 이를 제지하여 피해자가 그 틈을 타서 도망함으로써 살인의 목적을 이루지 못했다면 살인미수죄로 처벌할 수 없다.","ox":"X","m":"②","c":"A","tp":"미수․기수"},{"y":2019,"e":"국가직 9급","qn":13,"i":"N92019-13-3","t":"강도의 기회에 강간의 결과가 발생하였더라도 강도가 기수에 이르지 못하였다면 강도강간의 미수에 불과하다.","ox":"X","m":"③","c":"A","tp":"미수․기수"},{"y":2019,"e":"국가직 9급","qn":13,"i":"N92019-13-4","t":"준강도죄의 기수 또는 미수는 구성요건적 행위인 폭행 또는 협박이 종료되었는가의 여부에 따라 결정된다.","ox":"X","m":"④","c":"A","tp":"미수․기수"},{"y":2020,"e":"국가직 9급","qn":2,"i":"N92020-02-1","t":"주거침입죄의 실행의 착수는 구성요건의 일부를 실현하는 행위까지 요구하는 것은 아니고 범죄구성요건의 실현에 이르는 현실적 위험성을 포함하는 행위를 개시하는 것으로 족하다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"국가직 9급","qn":2,"i":"N92020-02-2","t":"부동산 이중양도에 있어서 매도인이 제2차 매수인으로부터 계약금만을 지급받고 중도금을 수령한 바 없다면 배임죄의 실행의 착수가 있었다고 볼 수 없다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"국가직 9급","qn":2,"i":"N92020-02-3","t":"주간에 주거에 침입하여 야간에 절도를 범한 경우 주거침입을 한 때에 야간주거침입절도죄의 실행에 착수한 것으로 보는 것이 타당하다.","ox":"X","m":"③","c":"A","tp":"실행의 착수"},{"y":2020,"e":"국가직 9급","qn":2,"i":"N92020-02-4","t":"소매치기가 피해자의 상의 호주머니로부터 금품을 훔치려고 그 호주머니에 손을 뻗쳐 그 겉을 더듬은 때에는 절도죄의 실행에 착수하였다고 봄이 상당하다.","ox":"O","m":"④","c":"A","tp":"실행의 착수"},{"y":2021,"e":"국가직 9급","qn":8,"i":"N92021-08-1","t":"공동정범 중 1인이 다른 공범의 범행을 중지하게 하지 아니하고 자기만의 범의를 철회, 포기한 경우 중지미수로 인정될 수 없다.","ox":"O","m":"①","c":"A","tp":"미수․기수"},{"y":2021,"e":"국가직 9급","qn":8,"i":"N92021-08-2","t":"불능범과 구별되는 불능미수의 성립요건인 ‘위험성’은 행위자가 행위 당시에 인식한 사정을 놓고 일반인이 객관적으로 판단하여 결과 발생의 가능성이 있는지 여부를 따져야 한다.","ox":"O","m":"②","c":"A","tp":"미수․기수"},{"y":2021,"e":"국가직 9급","qn":8,"i":"N92021-08-3","t":"甲이 A에게 위조한 예금통장 사본 등을 보여주면서 외국 회사에서 투자금을 받았다고 거짓말하며 자금 대여를 요청한 후 A와 함께 그 입금 여부를 확인하기 위해 은행에 가던 중 범행이 발각될 것이 두려워 은행 입구에서 그 차용을 포기하고 돌아간 경우 사기죄의 장애미수에 해당한다.","ox":"O","m":"③","c":"A","tp":"미수․기수"},{"y":2021,"e":"국가직 9급","qn":8,"i":"N92021-08-4","t":"甲이 타인의 명의를 빌려 예금계좌를 개설한 후 통장과 도장은 명의인에게 보관시키고 자신은 위 계좌의 현금인출카드를 소지한 채 명의인을 기망하여 위 계좌로 돈을 송금하게 하였지만 그 돈을 인출하지 않고 있던 중 명의인이 이를 인출한 경우, 甲은 사기죄의 장애미수에 해당한다.","ox":"X","m":"④","c":"A","tp":"미수․기수"},{"y":2024,"e":"국가직 9급","qn":9,"i":"N92024-09-1","t":"甲이 A에게 위조한 통장 사본 등을 보여 주면서 투자금을 받았다고 거짓말하며 자금 대여를 요청하였으나 A와 함께 그 입금 여부를 확인하기 위해 은행에 가던 중 범행이 발각될 것이 두려워 차용을 포기하고 돌아간 경우, 사기죄의 중지미수가 성립한다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"국가직 9급","qn":9,"i":"N92024-09-2","t":"甲이 A가 심신상실 또는 항거불능의 상태에 있다고 인식하고 그러한 상태를 이용하여 간음할 의사로 A를 간음하였으나 실제로는 A가 심신상실 또는 항거불능의 상태에 있지 않았다면 甲에게 준강간죄의 장애미수가 성립한다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"국가직 9급","qn":9,"i":"N92024-09-3","t":"강도가 재물강취의 뜻을 재물의 부재로 이루지 못한 채 미수에 그쳤고 그 자리에서 항거불능의 상태에 빠진 피해자를 간음할 것을 결의하고 실행에 착수했으나 역시 미수에 그친 경우, 반항을 억압하기 위한 폭행으로 피해자에게 상해를 입혔다면 강도강간 미수죄와 강도치상죄가 성립하고 양 죄는 상상적 경합관계에 있다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"국가직 9급","qn":9,"i":"N92024-09-4","t":"甲이 소송에서 주장하는 권리가 존재하지 않는 사실을 알고 있으면서도 법원을 기망한다는 인식을 가지고 소를 제기하였지만, 상대방의 주소를 허위로 기재함으로써 소장의 유효한 송달이 되지 않는 경우 소송사기의 실행의 착수가 인정되지 않는다.","ox":"X","m":"④","c":"A","tp":"미수"},{"y":2025,"e":"국가직 9급","qn":10,"i":"N92025-10","t":"甲이 乙과 합동하여 피해자 A를 텐트 안으로 끌고 간 후 乙, 甲의 순으로 성관계를 하기로 하고 甲은 위 텐트 밖으로 나와 주변에서 망을 보고 乙은 A의 옷을 모두 벗기고 A의 반항을 억압한 후 A를 1회 간음하여 강간하고, 이어 甲이 위 텐트 안으로 들어가 A를 강간하려 하였으나 A가 반항을 하며 강간을 하지 말아 달라고 사정을 하여 강간을 하지 않은 경우 甲이 강간행위에 나아가지 않았다 하더라도 중지미수에 해당하지는 않는다.","c":"A","mc":{"s":"甲이 乙과 합동하여 피해자 A를 텐트 안으로 끌고 간 후 乙, 甲의 순으로 성관계를 하기로 하고 甲은 위 텐트 밖으로 나와 주변에서 망을 보고 乙은 A의 옷을 모두 벗기고 A의 반항을 억압한 후 A를 1회 간음하여 강간하고, 이어 甲이 위 텐트 안으로 들어가 A를 강간하려 하였으나 A가 반항을 하며 강간을 하지 말아 달라고 사정을 하여 강간을 하지 않은 경우 甲이 강간행위에 나아가지 않았다 하더라도 중지미수에 해당하지는 않는다.","d":"미수에 대한 설명으로 옳은 것만을 모두 고르면?\nㄱ. 법정에서 선서한 증인이 일단 기억에 반하는 허위의 진술을 하였다가 그 신문이 끝나기 전에 그 진술을 철회ㆍ시정한 경우에는 중지미수에 해당하므로 형을 감경하거나 면제한다.\nㄴ. 甲이 자신의 범행 전력 등을 생각하여 가책을 느낀 나머지 스스로 결의를 바꾸어 다른 공범자 乙의 침입 사실을 알려 그를 체포하게 하여 야간주거침입절도의 범행을 중지하게 한 경우, 甲에 대해서는 형을 감경하거나 면제하나, 乙에 대해서는 형을 감경할 수 없다.\nㄷ.\nㄹ. 중지범은 범죄의 실행에 착수한 후 자의로 그 행위를 중지한 때를 말하는 것이고 실행의 착수가 있기 전인 예비음모의 행위를 처벌하는 경우에 있어서 중지범의 관념은 이를 인정할 수 없다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":4}}],"4":[{"y":2015,"e":"국가직 9급","qn":12,"i":"N92015-12-1","t":"심신상실자란 심신장애로 인하여 사물을 변별할 능력이 없거나 의사를 결정할 능력이 결여된 자를 말한다.","ox":"O","m":"①","c":"A","tp":"책임"},{"y":2015,"e":"국가직 9급","qn":12,"i":"N92015-12-2","t":"음주운전 의사로 음주만취한 후 차를 운행하다가 교통사고를 일으킨 경우 음주시에 교통사고를 일으킬 위험성을 예견하였는데도 자의로 심신장애를 야기한 경우이므로 심신장애로 인한 형의 감경을 할 수 없다.","ox":"O","m":"②","c":"A","tp":"책임"},{"y":2015,"e":"국가직 9급","qn":12,"i":"N92015-12-3","t":"위법(성)의 인식은 그 범죄사실이 사회정의와 조리에 어긋난다는 것을 인식하는 것만으로는 부족하고 구체적인 해당 법조문에 대한 인식을 필요로 한다.","ox":"X","m":"③","c":"A","tp":"책임"},{"y":2015,"e":"국가직 9급","qn":12,"i":"N92015-12-4","t":"농아자가 음주 또는 약물로 인한 심신장애 상태에서 아동·청소년 대상 성폭력범죄를 범한 경우 형법 제11조에 따른 형의 감경을 하지 않을 수 있다.","ox":"O","m":"④","c":"A","tp":"책임"},{"y":2015,"e":"국가직 9급","qn":13,"i":"N92015-13-1","t":"심신미약자의 행위에 대해서는 필요적으로 형을 감경하여야 하지만, 반드시 치료감호처분이 부과되는 것은 아니다.","ox":"O","m":"①","c":"A","tp":"책임능력"},{"y":2015,"e":"국가직 9급","qn":13,"i":"N92015-13-2","t":"심신장애의 유무 및 정도의 판단은 정신의학적 판단으로서 전문감정인의 의견에 따라야 하며 법원이 독자적으로 판단할 수 있는 사항은 아니다.","ox":"X","m":"②","c":"A","tp":"책임능력"},{"y":2015,"e":"국가직 9급","qn":13,"i":"N92015-13-3","t":"충동을 억제하지 못하여 범죄를 저지르게 되는 현상은 정상인 에게서도 얼마든지 찾아볼 수 있으므로, 원칙적으로 충동조절 장애와 같은 성격적 결함은 형의 감면사유인 심신장애에 해당하지 아니한다.","ox":"O","m":"③","c":"A","tp":"책임능력"},{"y":2015,"e":"국가직 9급","qn":13,"i":"N92015-13-4","t":"평소 간질병 증세가 있었더라도 범행 당시 간질병이 발작하지 않았다면 심신장애 또는 심신미약의 경우에 해당하지 아니한다.","ox":"O","m":"④","c":"A","tp":"책임능력"},{"y":2016,"e":"국가직 9급","qn":2,"i":"N92016-02","t":"‘현재의 부당한 침해’라는 정당방위 상황이 객관적으로 존재하지 않음에도 불구하고 행위자는 존재하는 것으로 잘못 알고 방위행위를 한 경우, 이를 법률의 착오로 보고 ‘오인에 정당한 이유’가 있으면 책임이 조각된다는 견해는?","c":"A","mc":{"s":"‘현재의 부당한 침해’라는 정당방위 상황이 객관적으로 존재하지 않음에도 불구하고 행위자는 존재하는 것으로 잘못 알고 방위행위를 한 경우, 이를 법률의 착오로 보고 ‘오인에 정당한 이유’가 있으면 책임이 조각된다는 견해는?","d":"","o":["엄격책임설","제한적 책임설","소극적 구성요건표지이론","고의설"],"a":1}},{"y":2016,"e":"국가직 9급","qn":13,"i":"N92016-13","t":"형법 제16조의 ‘그 오인에 정당한 이유’가 있다고 인정되는 경우는?","c":"A","mc":{"s":"형법 제16조의 ‘그 오인에 정당한 이유’가 있다고 인정되는 경우는?","d":"","o":["지방자치단체장이 관행적으로 간담회를 열어 업무추진비 지출 형식으로 참석자들에게 음식물을 제공하는 것이 허용되는 행위라고 오인한 경우","광역시의회 의원이 선거구민들에게 의정보고서를 배부하기에 앞서 미리 관할 선거관리위원회 소속 공무원들에게 자문을 구하고 그들의 지적에 따라 수정한 의정보고서를 배부한 경우","일본 영주권을 가진 재일교포가 관세물품을 영리목적으로 구입한 것이 아니기 때문에 입국 시 관세신고를 하지 않아도 되는 것으로 오인한 경우","부동산중개업자가 부동산중개업협회의 자문을 통하여 인원수의 제한 없이 중개보조원을 채용하는 것이 허용되는 것으로 믿고서 제한인원을 초과하여 중개보조원을 채용한 경우"],"a":2}},{"y":2017,"e":"국가직 9급","qn":2,"i":"N92017-02","t":"적법행위에 대한 기대가능성 법리의 구체화로 볼 수 없는 것은?","c":"A","mc":{"s":"적법행위에 대한 기대가능성 법리의 구체화로 볼 수 없는 것은?","d":"","o":["위조통화취득 후 지정행사죄의 법정형이 위조통화행사죄보다 현저히 낮은 것","야간 기타 불안스러운 상태 하에서 공포, 경악, 흥분 또는 당황으로 인한 과잉방위를 벌하지 아니하는 것","도주죄의 법정형이 도주원조죄보다 현저히 낮은 것","사회통념상 허용될 만한 소극적 저항행위를 처벌하지 않는 것"],"a":4}},{"y":2017,"e":"국가직 9급","qn":15,"i":"N92017-15","t":"이 견해에 대한 설명 또는 비판으로 옳은 것은?","c":"A","mc":{"s":"이 견해에 대한 설명 또는 비판으로 옳은 것은?","d":"원인에 있어서 자유로운 행위의 가벌성 근거를 원인설정행위 자체에서 찾는 견해가 있다.","o":["책임능력 결함상태에서 구성요건 해당행위를 시작한 때에 실행의 착수가 있는 것으로 본다.","실행의 착수에 구성요건적 행위정형성이 결여되어 죄형법정 주의에 반할 위험이 있다.","행위와 책임의 동시존재 원칙의 예외를 인정하는 결과가 되어 책임주의에 반할 위험이 있다.","이 견해에 의하면 살인의 의사로 음주하여 만취하였으나 살해행위로 나아가지 않았다면 살인미수는 인정되지 않는다."],"a":2}},{"y":2018,"e":"국가직 9급","qn":4,"i":"N92018-04-1","t":"형법 제10조제3항은 고의에 의한 원인에 있어서의 자유로운 행위만이 아니라 과실에 의한 원인에 있어서의 자유로운 행위까지도 포함한다.","ox":"O","m":"①","c":"A","tp":"책임"},{"y":2018,"e":"국가직 9급","qn":4,"i":"N92018-04-2","t":"형법 제12조의 강요된 행위란 저항할 수 없는 폭력이나 생명, 신체에 위해를 가하겠다는 협박 등 다른 사람의 강요에 의하여 이루어진 행위를 의미한다.","ox":"O","m":"②","c":"A","tp":"책임"},{"y":2018,"e":"국가직 9급","qn":4,"i":"N92018-04-3","t":"적법행위의 기대가능성의 경우 행위 당시의 구체적인 상황하에 행위자 대신 사회적 평균인을 두고 이 평균인의 관점에서 그 기대가능성 유무를 판단하여야 한다.","ox":"O","m":"③","c":"A","tp":"책임"},{"y":2018,"e":"국가직 9급","qn":4,"i":"N92018-04-4","t":"소아기호증의 정신적 장애가 있는 자라면 범행 당시 정상적인 사물변별능력이나 행위통제능력이 있었더라도 형법 제10조의 심신장애로 볼 수 있다.","ox":"X","m":"④","c":"A","tp":"책임"},{"y":2018,"e":"국가직 9급","qn":14,"i":"N92018-14","t":"다음 사례에서 甲의 죄책에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"다음 사례에서 甲의 죄책에 대한 설명으로 옳은 것은?","d":"A는 하산하다가 야생 멧돼지에게 쫓겨 급히 도망치며 달리던 중 마침 甲의 전원주택을 발견하고 그 집으로 뛰어 들어가 몸을 숨겨 위기를 모면하였다. 집주인 甲은 A를 도둑으로 오인하여, 그를 쫓아내려는 의도로 “도둑이야!”라고 외쳤다. A가 자초지종을 설명하려고 다가가자 甲은 자신을 공격하려는 것으로 오인하여 그의 가슴을 힘껏 밀어 넘어뜨렸다.","o":["법률의 착오 중 포섭의 착오에 해당하는 사례로서 판례에 따르면 오인에 정당한 이유가 있는 경우 책임이 조각된다.","우연방위의 사례로서 甲에게는 주관적 정당화 요소가 결여 되었으므로 불능미수유추설에 따르면 폭행죄가 성립하지 않으므로 미수범으로 처벌된다.","허용구성요건의 착오에 해당하는 사례로서 법효과 제한적 책임설에 따르면 甲에게 폭행의 구성요건적 고의가 인정되나 책임고의가 부정되어 폭행죄가 성립하지 않는다.","오상방위의 사례로서 판례에 따르면 오인에 정당한 이유가 있는 경우 책임이 조각된다."],"a":3}},{"y":2019,"e":"국가직 9급","qn":6,"i":"N92019-06","t":"이미 유죄의 확정판결을 받은 피고인이 설사 자신의 형사사건에서 시종일관 그 범행을 부인하였다 하더라도, 이를 이유로 피고인에게 공범의 형사사건에서 사실대로 증언할 것을 기대할 가능성이 없다고 볼 수는 없다.","c":"A","mc":{"s":"이미 유죄의 확정판결을 받은 피고인이 설사 자신의 형사사건에서 시종일관 그 범행을 부인하였다 하더라도, 이를 이유로 피고인에게 공범의 형사사건에서 사실대로 증언할 것을 기대할 가능성이 없다고 볼 수는 없다.","d":"기대가능성에 대한 설명으로 옳은 것(O)과 옳지 않은 것(X)을 바르게 표시한 것은? (다툼이 있는 경우 판례에 의함)\nㄱ.\nㄴ. 피고인이 주종관계에 있는 공동피고인의 지시를 거절할 수가 없어 뇌물을 공여하였더라도 그와 같은 사정만으로 피고인에게 뇌물공여 이외의 반대행위를 기대할 수 없는 경우라고 볼 수는 없다.\nㄷ. 상관의 명령에 절대 복종하여야 한다는 것이 불문율로 되어있다면, 고문행위와 같은 중대하고도 명백한 위법 명령에 따른 행위라도 강요된 행위로서 적법행위에 대한 기대가능성이 없는 경우에 해당한다.\nㄹ. 영업정지처분에 대한 집행정지 결정이 잠정적으로 받아들여졌다는 사정만으로는 구 음반․비디오물 및 게임물에 관한 법률 위반으로 기소된 피고인에게 적법행위의 기대가능성이 없다고 볼 수는 없다. ㄱ ㄴ ㄷ ㄹ","o":["O O X O","O O X X","O X X O","X O O X"],"a":1}},{"y":2019,"e":"국가직 9급","qn":9,"i":"N92019-09","t":"이에 대한 설명으로 옳은 것은?","c":"A","mc":{"s":"이에 대한 설명으로 옳은 것은?","d":"甲은 乙의 애인 A를 자신의 애인 B로 오인하여 놀라게 할 생각 으로 뒤에서 그녀의 어깨를 껴안았는데, 乙은 甲을 성폭행범으로 오인하고 甲을 주먹으로 때려 전치 4주의 타박상을 입혔다.  (다툼이 있는 경우 판례에 의함)","o":["甲이 A를 B로 오인하였다고 하더라도 강제추행의 고의는 부정 되지 않으므로 甲은 A에 대한 강제추행의 죄책을 진다.","乙이 甲을 성폭행범으로 오인하였다고 하더라도 乙이 의도적 으로 甲을 때려 상해를 입힌 이상, 법효과제한적 책임설에 따르면 乙은 상해의 죄책을 진다.","엄격책임설에 따르면 乙이 甲을 성폭행범으로 오인하는데 정당한 이유가 인정된다면 상해죄의 구성요건해당성은 인정 되나 책임이 부정되어 상해죄는 성립하지 않는다.","만약 甲이 추행의 의사로 A를 뒤에서 팔을 벌려 껴안으려 했다면 A가 뒤돌아보면서 소리치는 바람에 A를 껴안지 못하였더라도 甲은 A에 대한 강제추행 기수의 죄책을 진다."],"a":3}},{"y":2020,"e":"국가직 9급","qn":1,"i":"N92020-01-1","t":"형사미성년자는 책임능력의 결여로 인하여 형사처벌의 대상이 되지는 않지만, 그 연령에 따라 소년법상 보호처분의 대상이 될 수 있다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"국가직 9급","qn":1,"i":"N92020-01-2","t":"정신적 장애가 있는 자라도 범행 당시 정상적인 사물변별 능력이나 행위통제능력이 있었다면 심신장애로 볼 수 없다.","ox":"O","m":"②","c":"A","tp":"책임능력"},{"y":2020,"e":"국가직 9급","qn":1,"i":"N92020-01-3","t":"심신장애의 유무 및 정도의 판단은 법률적 판단으로서 반드시 전문감정인의 의견에 기속되어야 하는 것은 아니므로, 정신 분열증의 경우에도 법원은 여러 사정을 종합하여 심신장애의 유무 및 정도를 독자적으로 판단할 수 있다.","ox":"O","m":"③","c":"A","tp":"책임능력"},{"y":2020,"e":"국가직 9급","qn":1,"i":"N92020-01-4","t":"농아자라도 행위 당시 사물을 변별하고 이에 따라 행위를 통제할 능력이 있는 경우에는 형을 감경하지 않는다.","ox":"X","m":"④","c":"A","tp":"책임능력"},{"y":2021,"e":"국가직 9급","qn":4,"i":"N92021-04-1","t":"심신장애는 생물학적 요소로서 정신병이나 정신박약 또는 비정상적 정신상태와 같은 정신적 장애가 있는 것만으로도 인정된다.","ox":"X","m":"①","c":"A","tp":"형법 제10조"},{"y":2021,"e":"국가직 9급","qn":4,"i":"N92021-04-2","t":"심신장애의 유무 및 정도의 판단은 사실적 판단이므로 법원 으로서는 전문감정인의 의견에 기속되어야 한다.","ox":"X","m":"②","c":"A","tp":"형법 제10조"},{"y":2021,"e":"국가직 9급","qn":4,"i":"N92021-04-3","t":"형법 제10조제3항은 고의에 의한 원인에 있어서의 자유로운 행위를 포함하고 과실에 의한 원인에 있어서의 자유로운 행위는 포함하지 않는다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"국가직 9급","qn":4,"i":"N92021-04-4","t":"무생물인 옷 등을 성적 각성과 희열의 자극제로 믿고 이를 성적 흥분을 고취시키는 데 쓰는 성주물성애증이라는 정신질환의 경우, 그 증상이 매우 심각하여 정신병이 있는 사람과 동등 하다고 평가할 수 있으면 심신장애를 인정할 수 있다.","ox":"O","m":"④","c":"A","tp":"형법 제10조"},{"y":2021,"e":"국가직 9급","qn":6,"i":"N92021-06-1","t":"위법성 인식의 체계적 지위에 관한 학설 중 고의설에 따르면 법률의 착오와 사실의 착오 모두 고의가 조각된다.","ox":"O","m":"①","c":"A","tp":"위법성 인식과 법률의 착오"},{"y":2021,"e":"국가직 9급","qn":6,"i":"N92021-06-2","t":"위법성 인식에 필요한 노력의 정도는 행위자 개인의 인식능력의 문제이므로 행위자가 속한 사회집단에 따라 달리 평가되어서는 안 된다.","ox":"X","m":"②","c":"A","tp":"위법성 인식과 법률의 착오"},{"y":2021,"e":"국가직 9급","qn":6,"i":"N92021-06-3","t":"형법 제16조의 법률의 착오는 처벌규정의 존재를 인식하지 못한 법률의 부지뿐만 아니라 일반적으로 범죄가 되는 행위 이지만 자기의 특수한 경우에는 법령에 의하여 허용되는 행위로 오인한 경우를 말한다.","ox":"X","m":"③","c":"A","tp":"위법성 인식과 법률의 착오"},{"y":2021,"e":"국가직 9급","qn":6,"i":"N92021-06-4","t":"형법 제16조에 따르면 법률의 착오에 있어서 오인에 정당한 이유가 있으면 벌하지 않으며 정당한 이유가 없는 경우에는 형을 감경할 수 있다.","ox":"X","m":"④","c":"A","tp":"위법성 인식과 법률의 착오"},{"y":2023,"e":"국가직 9급","qn":3,"i":"N92023-03-1","t":"강요된 자가 저항할 수 없는 폭력이나 자기 또는 친족의 생명ㆍ 신체에 대한 위해를 방어할 수 있는 방법이 없는 위해의 상태를 자초하였거나 예기하였다면 강요된 행위라고 할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"국가직 9급","qn":3,"i":"N92023-03-2","t":"상사의 지시에 의한 것이라 하여도 저항할 수 없는 폭력이나 자기 또는 친족의 생명ㆍ신체에 대한 위해를 방어할 방법이 없는 협박에 상당한 것이라고 인정되지 않는 이상 강요된 행위라고 할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"국가직 9급","qn":3,"i":"N92023-03-3","t":"강요된 행위에서 ‘저항할 수 없는 폭력’이란 심리적인 의미에 있어서 육체적으로 어떤 행위를 절대적으로 하지 아니할 수 없게 되는 경우와 윤리적 의미에 있어서 강압된 경우를 말한다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"국가직 9급","qn":3,"i":"N92023-03-4","t":"어떤 사람의 성장교육과정을 통하여 형성된 내재적인 관념 내지 확신으로 인하여 행위자 스스로의 의사결정이 사실상 강제되는 결과를 낳게 하는 경우는 강요된 행위라고 할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"국가직 9급","qn":9,"i":"N92023-09-1","t":"심신장애인의 행위인지 여부는 전문가의 감정, 그 행위의 전후 사정이나 기록에 나타난 제반자료를 종합하여 인정하되, 공판정 에서의 피고인의 태도를 고려하여서는 안 된다.","ox":"X","m":"①","c":"A","tp":"책임능력"},{"y":2023,"e":"국가직 9급","qn":9,"i":"N92023-09-2","t":"심신장애는 생물학적 요소 외에 심리학적 요소로서 정신병 또는 비정상적 정신상태와 같은 정신적 장애로 말미암아 사물에 대한 변별능력과 그에 따른 행위통제능력이 결여되거나 감소되었음을 요한다.","ox":"O","m":"②","c":"A","tp":"책임능력"},{"y":2023,"e":"국가직 9급","qn":9,"i":"N92023-09-3","t":"성적 측면에서의 성격적 결함에 따른 소아기호증은 그 증상이 심각하여 원래의 의미의 정신병이 있는 사람과 동등하다고 평가할 수 있더라도 심신장애를 인정할 여지는 없다.","ox":"X","m":"③","c":"A","tp":"책임능력"},{"y":2023,"e":"국가직 9급","qn":9,"i":"N92023-09-4","t":"위험의 발생을 예견할 수 있었는데도 자의로 심신장애를 야기한 경우는 원인에 있어서 자유로운 행위에 관한 형법 제10조제3항의 적용대상이 아니다.","ox":"X","m":"④","c":"A","tp":"책임능력"},{"y":2024,"e":"국가직 9급","qn":4,"i":"N92024-04-1","t":"자신의 범행이 구 부동산소유권 이전등기 등에 관한 특별조치법에 위반되는지를 몰랐다면, 이는 법률의 부지로 형법 제16조의 법률의 착오에 해당한다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"국가직 9급","qn":4,"i":"N92024-04-2","t":"사법경찰관직무취급을 하는 자가 참고인의 진술 내용을 피의자의 그것과 일치시키기 위해, 이미 적법하게 작성된 참고인진술조서를 찢어 버리고 진술인의 진술도 듣지 않고 그 내용을 일치시킨 새로운 진술조서를 만들었더라도, 그것이 수사기록의 체계화를 위하여 관례상 늘 있는 일이어서 적법한 것이라고 믿었다면 그렇게 오인함에 정당한 이유가 있는 때에 해당한다.","ox":"X","m":"②","c":"A","tp":"법률의 착오"},{"y":2024,"e":"국가직 9급","qn":4,"i":"N92024-04-3","t":"부동산중개업자가 아파트 분양권의 매매를 중개하면서 법이 허용하는 금액을 초과한 중개수수료를 수수한 것이 중개수수료 산정에 관한 지방자치단체의 조례를 잘못 해석한 데에 기인한 것이라면, 자신의 행위가 법령에 저촉되지 않는다고 오인함에 정당한 이유가 있는 때에 해당한다.","ox":"X","m":"③","c":"A","tp":"법률의 착오"},{"y":2024,"e":"국가직 9급","qn":4,"i":"N92024-04-4","t":"광역시의회 의원이 선거구민들에게 의정보고서를 배부하기에 앞서 미리 관할 선거관리위원회 소속 공무원들에게 자문을 구하고 그들의 지적에 따라 수정한 의정보고서를 배부한 경우 구 공직선거및선거부정방지법에 위반되지 않는다고 오인함에 정당한 이유가 있는 때에 해당한다.","ox":"O","m":"④","c":"A","tp":"법률의 착오"},{"y":2024,"e":"국가직 9급","qn":8,"i":"N92024-08-1","t":"고의설은 위법성 인식을 고의의 한 요소로 보지만, 책임설은 위법성 인식을 고의의 요소 아닌 별개의 책임 요소로 본다.","ox":"O","m":"①","c":"A","tp":"위법성의 인식"},{"y":2024,"e":"국가직 9급","qn":8,"i":"N92024-08-2","t":"제한고의설은 위법성 인식의 가능성만으로 고의 성립을 인정 하기도 하지만, 엄격고의설은 고의 성립에 현실적인 위법성 인식이 필요하다고 본다.","ox":"O","m":"②","c":"A","tp":"위법성의 인식"},{"y":2024,"e":"국가직 9급","qn":8,"i":"N92024-08-3","t":"엄격책임설은 위법성조각사유 전제사실 착오도 위법성 착오의 일종으로 취급하면 족하다고 보지만, 제한책임설은 위법성조각사유 전제사실 착오는 일반적인 위법성 착오와는 달리 취급하여야 한다고 본다.","ox":"O","m":"③","c":"A","tp":"위법성의 인식"},{"y":2024,"e":"국가직 9급","qn":8,"i":"N92024-08-4","t":"소극적 구성요건표지이론과 제한책임설은 모두 위법성조각사유 전제사실 착오가 있으면 구성요건적 고의가 조각된다고 본다.","ox":"X","m":"④","c":"A","tp":"위법성의 인식"},{"y":2025,"e":"국가직 9급","qn":1,"i":"N92025-01-1","t":"행정청의 허가가 있어야 함에도 불구하고 허가를 받지 아니하여 처벌대상의 행위를 한 경우라도, 허가를 담당하는 공무원이 허가를 요하지 않는 것으로 잘못 알려 주어 이를 믿었기 때문에 허가를 받지 아니한 것이라면 허가를 받지 않더라도 죄가 되지 않는 것으로 착오를 일으킨 데 대하여 정당한 이유가 있는 경우에 해당하여 처벌할 수 없다.","ox":"O","m":"①","c":"A","tp":"법률의 착오"},{"y":2025,"e":"국가직 9급","qn":1,"i":"N92025-01-2","t":"위법성의 인식에 필요한 노력의 정도는 구체적인 행위정황과 행위자 개인의 인식능력 그리고 행위자가 속한 사회집단에 따라 달리 평가되어서는 안 된다.","ox":"X","m":"②","c":"A","tp":"법률의 착오"},{"y":2025,"e":"국가직 9급","qn":1,"i":"N92025-01-3","t":"법률 위반 행위 중간에 일시적으로 판례에 따라 그 행위가 처벌 대상이 되지 않는 것으로 해석되었던 적이 있었다고 하더라도 그것만으로 자신의 행위가 처벌되지 않는 것으로 믿은 데에 정당한 이유가 있다고 할 수 없다.","ox":"O","m":"③","c":"A","tp":"법률의 착오"},{"y":2025,"e":"국가직 9급","qn":1,"i":"N92025-01-4","t":"범죄의 성립에 있어서 위법성의 인식은 그 범죄사실이 사회정의와 조리에 어긋난다는 것을 인식하는 것으로서 족하고 구체적인 해당 법조문까지 인식할 것을 요하는 것은 아니므로 형법상의 허위공문서작성죄에 해당되는 줄 몰랐다고 하더라도 그와 같은 사유만으로는 위법성의 인식이 없었다고 할 수 없다.","ox":"O","m":"④","c":"A","tp":"법률의 착오"},{"y":2025,"e":"국가직 9급","qn":13,"i":"N92025-13-1","t":"기대불가능한 사정이 없음에도 불구하고 그것이 있었다고 오인한 경우에 금지착오의 규정을 유추 적용하는 견해에 따르면 그 착오에 정당한 이유가 있으면 책임이 조각되고, 정당한 이유가 없으면 책임을 인정할 수 있다.","ox":"O","m":"①","c":"A","tp":"기대가능성"},{"y":2025,"e":"국가직 9급","qn":13,"i":"N92025-13-2","t":"자신의 강도상해 범행을 일관되게 부인하였으나 유죄판결이 확정된 피고인이 별건으로 기소된 공범의 형사사건에서 자신의 범행사실을 부인하는 증언을 한 경우, 피고인에게 기대가능성이 없으므로 위증죄가 성립하지 않는다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"국가직 9급","qn":13,"i":"N92025-13-3","t":"우연한 기회에 미리 출제될 시험문제를 알게 된 수험생인 피고인이 암기한 답을 답안지에 기재하여서는 아니된다는 것을 기대한다는 것은 보통의 경우 도저히 불가능하다.","ox":"O","m":"③","c":"A","tp":"기대가능성"},{"y":2025,"e":"국가직 9급","qn":13,"i":"N92025-13-4","t":"피고인이 비서라는 특수신분 때문에 주종관계에 있는 공동 피고인들의 지시를 거절할 수 없어 뇌물을 공여한 것이라 하더라도 그와 같은 사정만으로는 피고인에게 뇌물공여 이외의 반대행위를 기대할 수 없는 경우였다고 볼 수 없다.","ox":"O","m":"④","c":"A","tp":"기대가능성"}],"3":[{"y":2015,"e":"국가직 9급","qn":14,"i":"N92015-14-1","t":"甲이 교통사고를 가장한 보험사기를 공모한 乙의 승낙 하에 乙을 상해한 경우라도 상해죄가 성립한다.","ox":"O","m":"①","c":"A","tp":"피해자의 승낙"},{"y":2015,"e":"국가직 9급","qn":14,"i":"N92015-14-2","t":"피해자의 승낙은 법익침해 이전에 표시되어야 하며 승낙은 언제나 자유로이 철회할 수 있고 그 철회의 방법에 아무런 제한이 없다.","ox":"O","m":"②","c":"A"},{"y":2015,"e":"국가직 9급","qn":14,"i":"N92015-14-3","t":"피해자 乙이 살인을 승낙하지 않았음에도 불구하고 승낙이 있다고 오인하고 甲이 그를 살해한 경우 위법성조각사유의 전제사실에 대한 착오가 문제된다.","ox":"X","m":"③","c":"A","tp":"피해자의 승낙"},{"y":2015,"e":"국가직 9급","qn":14,"i":"N92015-14-4","t":"작성권한 없는 甲이 乙의 명의를 모용하여 사문서를 작성·수정 하였으나 행위 당시 이에 대한 명의자 乙의 명시적이거나 묵시적인 승낙이 있었다면 사문서의 위·변조죄가 성립하지 않는다.","ox":"O","m":"④","c":"A","tp":"피해자의 승낙"},{"y":2015,"e":"국가직 9급","qn":17,"i":"N92015-17","t":"공직선거후보자 乙이 연설 중 유권자들의 적절한 투표권 행사를 위해 다른 후보자 甲의 과거행적에 대한 신문에 게재된 자료를 제시하면서 후보자의 자질을 문제 삼자 甲이 물리력으로 乙의 연설을 중단시킨 경우 ㄷ.","c":"A","mc":{"s":"공직선거후보자 乙이 연설 중 유권자들의 적절한 투표권 행사를 위해 다른 후보자 甲의 과거행적에 대한 신문에 게재된 자료를 제시하면서 후보자의 자질을 문제 삼자 甲이 물리력으로 乙의 연설을 중단시킨 경우 ㄷ.","d":"甲의 행위가 정당방위에 해당하는 것만을 모두 고른 것은? (다툼이 있는 경우 판례에 의함)\nㄱ. 임차인 甲이 임대인의 수차의 요구에도 불구하고 기간이 만료된 방을 비워주지 못하겠다고 억지를 쓰고 횡포를 부리며 폭언하자 임대인의 며느리가 홧김에 그 방의 창문을 쇠스랑으로 부수었고, 이에 甲이 격분하여 배척 (빠루)을 휘둘러 구경꾼인 마을주민들을 상해한 경우\nㄴ.  검사가 참고인 조사를 받는 줄 알고 검찰청에 자진출석한 변호사사무실 사무장 乙을 객관적으로 합리적 근거 없이 긴급체포하려하자 변호사 甲이 이를 제지하는 과정에서 검사에게 상해를 가한 경우\nㄹ. 경찰관 乙이 현행범 甲을 체포하면서 진술거부권 등을 고지하지 아니한 채 체포하려고 하자 甲이 그 체포를 면하려고 반항하는 과정에서 乙에게 상해를 가한 경우","o":["ㄱ, ㄴ","ㄴ, ㄷ","ㄷ, ㄹ","ㄹ"],"a":3}},{"y":2016,"e":"국가직 9급","qn":12,"i":"N92016-12","t":"甲의 행위가 정당행위에 해당하는 것만을 모두 고른 것은?","c":"A","mc":{"s":"甲의 행위가 정당행위에 해당하는 것만을 모두 고른 것은?","d":"(다툼이 있는 경우 판례에 의함)\nㄱ. 甲은 자신의 승용차를 손괴하고 도망하려는 A를 도망 하지 못하게 멱살을 잡고 흔들어 A에게 전치 14일의 흉부찰과상을 입게 하였다.\nㄴ. 시장번영회 회장 甲은 1년 이상 관리비를 체납한 고액 체납자의 점포에 대하여 이사회의 결의와 시장번영회의 관리규정에 따라서 단전조치를 실시하였다.\nㄷ. 甲은 A를 상대로 한 목재대금청구소송의 계속 중, A가 양도소득세를 포탈한 사실을 발견하고 이를 이용하여 위 목재대금을 받아내기로 마음먹고 A에게 위와 같은 비위사실을 관계기관에 진정하겠다고 말하여 이에 겁을 먹은 A로부터 목재대금을 지급하겠다는 약속을 받아냈다.\nㄹ. X회사의 정기주주총회에 적법하게 참석한 주주 甲은 X회사 측이 X회사를 부실하게 운영하여 소수주주들에게 손해를 입혔다는 점을 주장하면서 강제로 X회사의 사무실을 뒤져 회계장부를 찾아냈다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":1}},{"y":2016,"e":"국가직 9급","qn":16,"i":"N92016-16","t":"방송사 기자인 甲이 구 국가안전기획부 정보수집팀이 타인 간의 사적 대화를 불법 녹음하여 생성한 도청자료인 녹음테이프와 녹취보고서를 입수한 후 이를 자사의 방송프로그램을 통하여 공개한 경우, 형법 제20조의 정당행위에 해당하지 않는다.","c":"A","mc":{"s":"방송사 기자인 甲이 구 국가안전기획부 정보수집팀이 타인 간의 사적 대화를 불법 녹음하여 생성한 도청자료인 녹음테이프와 녹취보고서를 입수한 후 이를 자사의 방송프로그램을 통하여 공개한 경우, 형법 제20조의 정당행위에 해당하지 않는다.","d":"다음 설명 중 옳은 것만을 모두 고른 것은? (다툼이 있는 경우 판례에 의함)\nㄱ. 甲은 동거녀가 자기의 지갑에서 현금을 꺼내가는 것을 보고도 아무런 만류를 하지 않았다면 이를 허용하는 묵시적 의사가 있다고 볼 수 있다.\nㄴ. 甲은 부도를 내고 도피한 피해자 상점의 물건들을 다른 채권자들이 취거해 갈 수 있다고 생각하고 자신의 청구권을 우선적으로 확보할 생각으로 무단 침입하여 피해자의 가구를 들고 나온 경우 정당한 자구행위로 볼 수 없다.\nㄷ.\nㄹ. 작성권한이 없는 甲이 사문서를 작성․수정함에 있어 그 명의자의 현실적 승낙은 없었지만 행위 당시의 모든 객관적 사정을 종합하여 명의자가 행위 당시 그 사실을 알았더라면 당연히 승낙했을 것이라고 추정되는 경우에는 사문서위․변조죄가 성립하지 않는다.","o":["ㄱ, ㄹ","ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":4}},{"y":2018,"e":"국가직 9급","qn":3,"i":"N92018-03-1","t":"甲이 경찰관의 불법한 체포를 면하려고 소극적으로 반항하는 과정에서 경찰관에게 경미한 상해를 가한 행위는 정당방위로 인정된다.","ox":"O","m":"①","c":"A","tp":"위법성조각사유"},{"y":2018,"e":"국가직 9급","qn":3,"i":"N92018-03-2","t":"여자 화장실 내에서 주저앉아 있는 여자 甲이 자신의 가방을 빼앗으려고 다가오는 남자의 어깨를 순간적으로 밀친 행위는 정당행위로 인정된다.","ox":"O","m":"②","c":"A","tp":"위법성조각사유"},{"y":2018,"e":"국가직 9급","qn":3,"i":"N92018-03-3","t":"한의사 면허나 자격이 없는 甲이 한약재 달인 물을 처방하는 등 소위 통합의학에 기초하여 환자를 진찰하여 처방하는 행위는 정당행위로 인정되지 않는다.","ox":"O","m":"③","c":"A","tp":"위법성조각사유"},{"y":2018,"e":"국가직 9급","qn":3,"i":"N92018-03-4","t":"甲이 피해자 A와 공모하여 교통사고를 가장하여 보험금을 편취할 목적으로 피해자 A에게 상해를 가한 행위는 A의 승낙에 의하여 위법성이 조각된다.","ox":"X","m":"④","c":"A","tp":"위법성조각사유"},{"y":2018,"e":"국가직 9급","qn":12,"i":"N92018-12-1","t":"甲이 주민들이 농기계 등으로 그 주변의 농경지나 임야에 통행하기 위해 이용하는 자신 소유의 도로에 깊이 1 m 정도의 구덩이를 판 경우 자구행위나 정당행위에 해당하지 않는다.","ox":"O","m":"①","c":"A","tp":"위법성조각사유"},{"y":2018,"e":"국가직 9급","qn":12,"i":"N92018-12-2","t":"甲이 자신의 아버지 A에게서 A 소유 부동산의 매매에 관한 권한 일체를 위임받아 이를 매도하였는데, 그 후 A가 갑자기 사망하자 부동산 소유권 이전에 사용할 목적으로 A가 甲에게 인감증명서 발급을 위임한다는 취지의 인감증명 위임장을 작성한 후 주민센터 담당직원에게 제출한 경우 사망한 명의자 A의 승낙이 추정되므로 위법성이 조각된다.","ox":"X","m":"②","c":"A","tp":"위법성조각사유"},{"y":2018,"e":"국가직 9급","qn":12,"i":"N92018-12-3","t":"甲이 스스로 야기한 강간범행의 와중에서 피해자 A가 甲의 손가락을 깨물며 반항하자 물린 손가락을 비틀며 잡아 뽑다가 A에게 치아결손의 상해를 입힌 경우 긴급피난에 해당하지 않는다.","ox":"O","m":"③","c":"A","tp":"위법성조각사유"},{"y":2018,"e":"국가직 9급","qn":12,"i":"N92018-12-4","t":"甲이 경찰관의 불심검문을 받아 운전면허증을 교부한 후 인근 주민들이 있는 가운데 경찰관에게 큰 소리로 욕설을 하였는데, 이를 이유로 경찰관이 모욕죄의 현행범으로 체포하려고 하자 반항하면서 경찰관에게 상해를 가한 경우 정당방위에 해당한다.","ox":"O","m":"④","c":"A","tp":"위법성조각사유"},{"y":2019,"e":"국가직 9급","qn":2,"i":"N92019-02-1","t":"정당방위는 자기 또는 타인의 법익에 대한 현재의 부당한 침해를 방어하기 위한 것으로서 상당성이 있어야 하므로, 정당한 침해에 대한 정당방위는 인정되지 않는다.","ox":"O","m":"①","c":"A","tp":"위법성조각사유"},{"y":2019,"e":"국가직 9급","qn":2,"i":"N92019-02-2","t":"긴급피난에 해당하려면 피난행위가 위난에 처한 법익을 보호하기 위한 유일한 수단이어야 하고, 피해자에게 가장 경미한 손해를 주는 방법을 택하여야 하며, 피난행위로 보전되는 이익은 이로 인해 침해되는 이익보다 우월해야 하고, 피난행위는 그 자체가 사회윤리나 법질서 전체의 정신에 비추어 적합한 수단이어야 한다.","ox":"O","m":"②","c":"A","tp":"위법성조각사유"},{"y":2019,"e":"국가직 9급","qn":2,"i":"N92019-02-3","t":"점유할 권리 없는 자의 점유라고 하더라도 그 주거의 사실상의 평온은 보호되어야 하므로, 권리자가 그 권리실행으로서 자력구제의 수단으로 건조물에 침입한 경우에도 주거침입죄가 성립한다.","ox":"O","m":"③","c":"A","tp":"위법성조각사유"},{"y":2019,"e":"국가직 9급","qn":2,"i":"N92019-02-4","t":"사문서를 수정할 당시 명의자가 현실적으로 승낙하지 않았다면, 설령 명의자가 그 사실을 알았다면 당연히 승낙했을 것이라고 추정되더라도 사문서변조죄가 성립한다.","ox":"X","m":"④","c":"A","tp":"위법성조각사유"},{"y":2019,"e":"국가직 9급","qn":7,"i":"N92019-07","t":"이에 대한 설명으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"이에 대한 설명으로 옳은 것만을 모두 고르면?","d":"甲은 평소 미워하던 乙과 우연히 마주치자 상해의 의사로 乙의 얼굴을 주먹으로 강타하여 코피가 나게 하였는데, 마침 그때 乙은 甲을 살해하려고 칼로 甲을 공격하려던 순간이었음이 밝혀졌다.\nㄱ. 위법성조각사유에 있어서는 주관적 정당화요소가 요구 되지 않는다는 견해에 따르면, 甲의 행위는 정당방위로서 위법성이 조각될 수 있다.\nㄴ. 판례에 따르면 정당방위가 성립하기 위하여는 행위자에게 방위의사가 있어야 하고 그 방위행위가 상당성이 있어야 하므로, 甲의 행위는 정당방위가 될 수 없다.\nㄷ. 위법성조각사유에 있어서는 주관적 정당화요소가 요구 되지만 위 사례에서는 결과반가치가 부정된다는 견해에 따르면, 甲은 상해죄의 불능미수로 처벌될 수 있다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":4}},{"y":2020,"e":"국가직 9급","qn":10,"i":"N92020-10-1","t":"쟁의행위가 추구하는 목적 중 일부가 정당하지 못한 경우에는 주된 목적 내지 진정한 목적을 기준으로 그 정당성 여부를 판단하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"국가직 9급","qn":10,"i":"N92020-10-2","t":"기업 구조조정의 실시로 근로자들의 지위나 근로조건의 변경이 필연적으로 수반되는 경우, 특별한 사정이 없더라도 이를 반대하는 쟁의행위의 정당성을 인정할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2020,"e":"국가직 9급","qn":10,"i":"N92020-10-3","t":"조합원의 민주적 의사결정이 실질적으로 확보된 때에는 쟁의 행위의 개시에 앞서 노동조합 및 노동관계조정법 제41조 제1항에 의한 투표절차를 거치지 아니한 경우에도 쟁의행위의 정당성은 상실되지 않는다.","ox":"X","m":"③","c":"A"},{"y":2020,"e":"국가직 9급","qn":10,"i":"N92020-10-4","t":"쟁의행위로서의 직장 또는 사업장시설 점거는 그 범위가 직장 또는 사업장시설 일부분에 그치고 사용자 측의 출입이나 관리지배를 배제하지 않는 병존적인 경우라도 이미 정당성의 한계를 벗어난 것이다.","ox":"X","m":"④","c":"A"},{"y":2020,"e":"국가직 9급","qn":17,"i":"N92020-17-1","t":"피무고자의 승낙을 받아 허위사실을 기재한 고소장을 수사기관에 제출하였다면 무고죄로 처벌할 수 없다.","ox":"X","m":"①","c":"A","tp":"피해자의 승낙"},{"y":2020,"e":"국가직 9급","qn":17,"i":"N92020-17-2","t":"사문서위조죄나 공정증서원본불실기재죄가 성립한 이후, 피해자의 동의 등으로 문서에 기재된 대로 효과의 승인을 받거나 등기가 실체적 권리관계에 부합하게 되더라도 이미 성립한 범죄에 아무런 영향이 없다.","ox":"O","m":"②","c":"A","tp":"피해자의 승낙"},{"y":2020,"e":"국가직 9급","qn":17,"i":"N92020-17-3","t":"피해자와 공모하여 보험금을 편취할 목적으로 교통사고를 가장하여 피해자에게 상해를 가하였다면 피해자의 승낙이 있었더라도 위법성이 조각되지 않는다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"국가직 9급","qn":17,"i":"N92020-17-4","t":"진단상 과오가 없었으면 당연히 설명받았을 내용을 설명받지 못한 피해자로부터 수술승낙을 받았다면, 그 승낙은 부정확한 설명에 근거한 것으로서 수술의 위법성을 조각할 수 없다.","ox":"O","m":"④","c":"A","tp":"피해자의 승낙"},{"y":2021,"e":"국가직 9급","qn":3,"i":"N92021-03-1","t":"회사의 임원이 임무위배행위로 재산상 이익을 취득하여 회사에 손해를 가한 경우, 그 임무위배행위에 대하여 사실상 대주주의 양해를 얻었다고 하더라도 업무상배임죄가 성립한다.","ox":"O","m":"①","c":"A","tp":"피해자의 승낙 또는 추정적 승낙"},{"y":2021,"e":"국가직 9급","qn":3,"i":"N92021-03-2","t":"명의자 이외의 자의 의뢰로 사문서를 작성하는 경우에 명의자의 명시적인 승낙이 없다는 것을 알았지만 명의자가 사문서 작성 사실을 알았다면 승낙하였을 것이라고 작성자가 기대하거나 예측한 것만으로도 승낙은 추정된다.","ox":"X","m":"②","c":"A","tp":"피해자의 승낙 또는 추정적 승낙"},{"y":2021,"e":"국가직 9급","qn":3,"i":"N92021-03-3","t":"피해자의 승낙은 개인적 법익을 훼손하는 경우에 법률상 이를 처분할 수 있는 사람의 승낙을 말할 뿐만 아니라 그 승낙이 윤리적, 도덕적으로 사회상규에 반하는 것이 아니어야 한다.","ox":"O","m":"③","c":"A","tp":"피해자의 승낙 또는 추정적 승낙"},{"y":2021,"e":"국가직 9급","qn":3,"i":"N92021-03-4","t":"피해자의 승낙이 객관적으로 존재하지 않음에도 불구하고 행위자는 그것이 존재한다고 오신한 때에는 위법성조각사유의 전제사실에 대한 착오의 문제가 된다.","ox":"O","m":"④","c":"A","tp":"피해자의 승낙 또는 추정적 승낙"},{"y":2021,"e":"국가직 9급","qn":11,"i":"N92021-11-1","t":"甲이 A를 강간하던 중 A가 손가락을 깨물며 반항하자, 甲이 물린 손가락을 비틀어 잡아 뽑다가 A에게 치아결손을 가한 행위는 긴급피난에 해당한다.","ox":"X","m":"①","c":"A","tp":"위법성조각사유"},{"y":2021,"e":"국가직 9급","qn":11,"i":"N92021-11-2","t":"경찰관이 현행범인으로서의 요건을 갖추지 못한 甲을 체포하려고 하자, 甲이 체포를 면하려고 반항하는 과정에서 경찰관에게 상해를 가한 행위는 정당방위에 해당한다.","ox":"O","m":"②","c":"A","tp":"위법성조각사유"},{"y":2021,"e":"국가직 9급","qn":11,"i":"N92021-11-3","t":"친권자 甲이 스스로의 감정을 이기지 못하고 야구방망이로 때릴 듯이 자녀 A에게 “죽여 버린다”고 말하여 협박한 행위는 정당행위에 해당한다.","ox":"X","m":"③","c":"A","tp":"위법성조각사유"},{"y":2021,"e":"국가직 9급","qn":11,"i":"N92021-11-4","t":"정당 당직자 甲이 국회 상임위원회 회의장 앞 복도에서 출입이 봉쇄된 회의장 출입구를 뚫을 목적으로 회의장 출입문 및 그 안쪽에 쌓여있던 집기를 손상한 행위는 정당행위에 해당한다.","ox":"X","m":"④","c":"A","tp":"위법성조각사유"},{"y":2023,"e":"국가직 9급","qn":2,"i":"N92023-02-1","t":"음란물이 문학적ㆍ예술적ㆍ사상적ㆍ과학적ㆍ의학적ㆍ교육적 표현 등과 결합되어 음란 표현의 해악이 상당한 방법으로 해소되거나 다양한 의견과 사상의 경쟁메커니즘에 의해 해소될 수 있는 정도에 이르렀다면, 이러한 결합표현물에 의한 표현행위는 형법 제20조에 정하여진 ‘사회상규에 위배되지 않는 행위’에 해당한다.","ox":"O","m":"①","c":"A","tp":"정당행위"},{"y":2023,"e":"국가직 9급","qn":2,"i":"N92023-02-2","t":"문언송신금지를 명한 가정폭력범죄의 처벌 등에 관한 특례법상 임시보호명령을 위반하여 피고인이 피해자에게 문자메시지를 보낸 경우 문자메시지 송신을 피해자가 양해 내지 승낙하였다면 형법 제20조의 정당행위에 해당한다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"국가직 9급","qn":2,"i":"N92023-02-3","t":"신문기자인 피고인이 고소인에게 2회에 걸쳐 증여세 포탈에 대한 취재를 요구하면서, 이에 응하지 않으면 자신이 취재한 내용대로 보도하겠다고 협박한 것은 특별한 사정이 없는 한 사회상규에 반하지 않는 행위이다.","ox":"O","m":"③","c":"A","tp":"정당행위"},{"y":2023,"e":"국가직 9급","qn":2,"i":"N92023-02-4","t":"의료인이 아닌 자가 찜질방 내에서 부항과 부항침을 놓고 일정한 금원을 받은 행위는 그 시술로 인한 위험성이 적다는 사정만으로 사회상규에 위배되지 않는 행위로 보기는 어렵다.","ox":"O","m":"④","c":"A","tp":"정당행위"},{"y":2023,"e":"국가직 9급","qn":8,"i":"N92023-08","t":"위법성조각사유의 주관적 정당화요소에 대한 설명으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"위법성조각사유의 주관적 정당화요소에 대한 설명으로 옳은 것만을 모두 고르면?","d":"ㄱ. 위법성조각을 위해 주관적 정당화요소가 필요하다고 보는 견해에 의하면, 형법 제21조제1항에서 ‘방위하기 위하여 한’은 정당방위의 주관적 정당화요소를 규정한 것으로 해석된다.\nㄴ. 판례는 위법성조각을 위해 방위의사나 피난의사와 같은 주관적 정당화요소가 요구된다고 본다.\nㄷ. 위법성조각을 위해 주관적 정당화요소가 필요 없다고 보는 견해에 의하면, 행위자가 행위 당시 존재하는 객관적 정당화사정을 인식하지 못한 채 범죄의 고의만으로 행위를 한 경우 고의기수범이 성립한다.\nㄹ. 위법성 판단에 행위반가치와 결과반가치가 모두 요구된다고 보는 이원적ㆍ인적 불법론의 입장에서는 주관적 정당화요소가 결여된 경우 행위반가치가 부정되므로 불능미수가 된다고 본다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":1}},{"y":2024,"e":"국가직 9급","qn":3,"i":"N92024-03-1","t":"형법 제20조에 따라 사회상규에 의한 정당행위를 인정하기 위한 요건 중 행위의 긴급성과 보충성은 수단의 상당성을 판단할 때 고려요소의 하나로 참작하여야 하고 이를 넘어 독립적인 요건으로 요구할 것은 아니다.","ox":"O","m":"①","c":"A","tp":"위법성조각사유"},{"y":2024,"e":"국가직 9급","qn":3,"i":"N92024-03-2","t":"시위방법의 하나인 삼보일배 행진은 시위의 목적달성에 필요한 합리적인 범위에서 사회통념상 용인될 수 있는 다소의 피해를 발생시킨 경우에 불과하고, 신고내용에 포함되지 않은 삼보일배 행진을 한 것이 신고제도의 목적 달성을 심히 곤란하게 하는 정도에 이른다고 볼 수도 없으므로 사회상규에 위반되지 않는 행위로 위법성이 조각된다.","ox":"O","m":"②","c":"A","tp":"위법성조각사유"},{"y":2024,"e":"국가직 9급","qn":3,"i":"N92024-03-3","t":"회사의 이익을 빼돌린다는 소문을 확인할 목적으로 피해자가 비밀번호를 설정하여 사용하던 회사 소유 컴퓨터의 하드디스크를 떼어내어 다른 컴퓨터에 연결한 다음, 의심이 드는 단어로 파일을 검색하여 메신저 대화 내용, 이메일 등을 출력한 행위는 사회통념상 허용될 수 있는 행위라고 볼 수 없다.","ox":"X","m":"③","c":"A","tp":"위법성조각사유"},{"y":2024,"e":"국가직 9급","qn":3,"i":"N92024-03-4","t":"어떠한 행위가 범죄구성요건에 해당하지만 정당행위라는 이유로 위법성이 조각된다는 것은 그 행위가 적극적으로 용인ㆍ권장된다는 의미가 아니라 단지 특정한 상황에서 그 행위가 범죄행위로서 처벌대상이 될 정도의 위법성을 갖추지 못하였다는 것을 의미한다.","ox":"O","m":"④","c":"A","tp":"위법성조각사유"},{"y":2024,"e":"국가직 9급","qn":5,"i":"N92024-05-1","t":"자구행위는 법률에서 정한 절차에 따라서는 청구권을 보전할 수 없는 경우에 할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"국가직 9급","qn":5,"i":"N92024-05-2","t":"소유권의 귀속에 관한 분쟁이 있어 민사소송이 계속중인 건조물에 관하여 현실적으로 관리인이 있음에도 위 건조물의 자물쇠를 쇠톱으로 절단하고 침입한 행위는 법정절차에 의하여 그 권리를 보전하기가 곤란하고 그 권리의 실행불능이나 현저한 실행곤란을 피하기 위해 상당한 이유가 있는 행위라고 할 수 없다.","ox":"O","m":"②","c":"A","tp":"자구행위"},{"y":2024,"e":"국가직 9급","qn":5,"i":"N92024-05-3","t":"자신이 소유하는 토지상에 도로가 무단으로 확장 개설되어 그대로 방치할 경우 불특정 다수인이 통행할 우려가 있다는 사정만으로는 법정절차에 의하여 자신의 청구권을 보전하는 것이 불가능한 경우에 해당한다고 볼 수 없다.","ox":"O","m":"③","c":"A","tp":"자구행위"},{"y":2024,"e":"국가직 9급","qn":5,"i":"N92024-05-4","t":"피해자에게 석고를 납품한 대금을 받지 못하고 있던 중 피해자가 화랑을 폐쇄하고 도주하자 야간에 폐쇄된 화랑의 베니어판 문을 미리 준비한 드라이버로 뜯어내고 피해자의 물건을 몰래 가지고 나온 경우 자구행위에 해당한다.","ox":"X","m":"④","c":"A"},{"y":2025,"e":"국가직 9급","qn":5,"i":"N92025-05-1","t":"위법성조각사유로서의 피해자의 승낙은 언제든지 자유롭게 철회할 수 있다고 할 것이고 그 철회의 방법에는 아무런 제한이 없다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"국가직 9급","qn":5,"i":"N92025-05-2","t":"피고인의 부정확 또는 불충분한 설명을 근거로 이루어진 승낙은 위법성을 조각할 유효한 승낙이라고 볼 수 없다.","ox":"O","m":"②","c":"A","tp":"피해자의 승낙"},{"y":2025,"e":"국가직 9급","qn":5,"i":"N92025-05-3","t":"甲이 乙에게 밍크 45마리는 자신에게 그 권리가 있다고 주장 하면서 가져간 데 대하여 乙의 묵시적인 동의가 있었다면, 甲의 주장이 후에 허위로 밝혀졌더라도 그 행위는 절도죄의 절취행위에 해당하지 않는다.","ox":"O","m":"③","c":"A","tp":"피해자의 승낙"},{"y":2025,"e":"국가직 9급","qn":5,"i":"N92025-05-4","t":"문서명의인이 생존하고 있다는 점이 문서의 중요한 내용을 이루거나 그 점을 전제로 문서가 작성되었더라도, 사망한 명의자의 승낙이 추정된다면 사문서위조죄의 성립은 부정된다.","ox":"X","m":"④","c":"A","tp":"피해자의 승낙"},{"y":2025,"e":"국가직 9급","qn":9,"i":"N92025-09-1","t":"긴급피난과 달리 과잉피난이 성립하기 위하여 피고인에게 반드시 피난의사가 있어야 하는 것은 아니다.","ox":"X","m":"①","c":"A"},{"y":2025,"e":"국가직 9급","qn":9,"i":"N92025-09-2","t":"집회장소 사용 승낙을 하지 않은 대학교 측의 요청에 따라 경찰관들이 대학교 출입문에서 신고된 대학교에서의 집회에 참가하려는 자의 출입을 저지하자 소정의 신고 없이 다른 장소로 장소를 옮겨서 집회를 한 것은 긴급피난에 해당한다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"국가직 9급","qn":9,"i":"N92025-09-3","t":"피난행위가 ‘위난에 처한 법익을 보호하기 위한 유일한 수단’ 이어야 함은 긴급피난에서 상당한 이유가 인정되기 위한 조건 중 하나이다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"국가직 9급","qn":9,"i":"N92025-09-4","t":"피난행위가 그 정도를 초과한 경우로서의 이른바 과잉피난에 대해서는 형을 감경할 수 있지만 면제할 수는 없다.","ox":"X","m":"④","c":"A","tp":"긴급피난"}],"12":[{"y":2015,"e":"국가직 9급","qn":15,"i":"N92015-15-1","t":"‘직무를 유기한 때’란 직장의 무단이탈, 직무의 의식적인 포기 등과 같이 국가의 기능을 저해하고 국민에게 피해를 야기시킬 가능성이 있는 경우를 가리킨다.","ox":"O","m":"①","c":"A","tp":"직무유기죄"},{"y":2015,"e":"국가직 9급","qn":15,"i":"N92015-15-2","t":"경찰관이 불법체류자의 신병을 출입국관리사무소에 인계하지 않고 훈방하면서 이들의 인적사항조차 기재해 두지 아니하였다면 직무유기죄가 성립한다.","ox":"O","m":"②","c":"A"},{"y":2015,"e":"국가직 9급","qn":15,"i":"N92015-15-3","t":"교육기관 등의 장이 징계의결을 집행하지 못할 법률상·사실상의 장애가 없는데도 징계의결서를 통보받은 날로부터 법정 시한이 지나도록 그 집행을 유보하는 모든 경우에 직무유기죄가 성립하는 것은 아니고, 그 유보가 의식적인 직무의 방임이나 포기에 해당한다고 볼 수 있는 경우에만 성립한다.","ox":"O","m":"③","c":"A"},{"y":2015,"e":"국가직 9급","qn":15,"i":"N92015-15-4","t":"직무집행의 의사로 자신의 직무를 수행한 경우에는 그 직무 집행의 내용이 위법한 것으로 평가되는 경우뿐만 아니라 형식적으로 또는 소홀히 직무를 수행한 탓으로 적절한 직무 수행에 이르지 못한 경우에도 직무유기죄는 성립한다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"국가직 9급","qn":16,"i":"N92017-16-1","t":"피의자에 대한 모해목적의 증거위조죄에서 ‘피의자’에는 수사 개시 이전의 단계에서 장차 형사입건될 가능성이 있는 대상자도 포함된다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"국가직 9급","qn":16,"i":"N92017-16-2","t":"선서무능력자로서 범죄현장을 목격하지 않은 사람으로 하여금 형사법정에서 범죄현장을 목격한 양 허위의 증언을 하도록 하는 것은 증거위조죄를 구성하지 않는다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"국가직 9급","qn":16,"i":"N92017-16-3","t":"참고인이 타인의 형사사건 등에 관하여 제3자와 대화를 하면서 허위로 진술하고 위와 같은 허위 진술이 담긴 대화 내용을 녹음한 녹음파일 또는 이를 녹취한 녹취록을 만들어 수사기관에 제출하는 것은 증거위조죄를 구성한다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"국가직 9급","qn":16,"i":"N92017-16-4","t":"타인의 형사사건과 관련하여 수사기관이나 법원에 제출하거나 현출되게 할 의도로 법률행위 당시에는 존재하지 아니하였던 처분문서를 사후에 그 작성일을 소급하여 작성하는 것은 증거위조죄를 구성한다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"국가직 9급","qn":17,"i":"N92017-17-1","t":"뇌물죄에서 말하는 ‘직무’에는 법령에 정하여진 직무뿐만 아니라 그와 관련 있는 직무, 과거에 담당하였거나 장래에 담당할 직무 외에 사무분장에 따라 현실적으로 담당하지 않는 직무라도 법령상 일반적인 직무권한에 속하는 직무 등 공무원이 그 직위에 따라 공무로 담당할 일체의 직무를 포함한다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"국가직 9급","qn":17,"i":"N92017-17-2","t":"뇌물죄는 직무집행의 공정성과 이에 대한 사회의 신뢰 및 직무행위의 불가매수성을 그 보호법익으로 하고 있고, 직무에 관한 청탁이나 부정한 행위를 필요로 하는 것은 아니기 때문에 수수된 금품의 뇌물성을 인정하는 데 특별한 청탁이 있어야만 하는 것은 아니다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"국가직 9급","qn":17,"i":"N92017-17-3","t":"뇌물죄에서 뇌물의 내용인 이익이라 함은 금전, 물품 기타의 재산적 이익뿐만 아니라 사람의 수요·욕망을 충족시키기에 족한 일체의 유형, 무형의 이익을 포함한다고 해석되고, 투기적 사업에 참여할 기회를 얻는 것도 이에 해당한다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"국가직 9급","qn":17,"i":"N92017-17-4","t":"뇌물수수죄와 뇌물공여죄는 필요적 공범관계에 있으므로 뇌물공여죄가 성립하기 위해서는 상대방 측에서 뇌물수수죄가 성립되어야 한다.","ox":"X","m":"④","c":"A","tp":"뇌물죄"},{"y":2017,"e":"국가직 9급","qn":20,"i":"N92017-20","t":"다음 설명 중 옳은 것만을 모두 고른 것은?","c":"A","mc":{"s":"다음 설명 중 옳은 것만을 모두 고른 것은?","d":"(다툼이 있는 경우 판례에 의함)\nㄱ. 외교상기밀누설죄는 공무원 또는 공무원이었던 자가 직무와 관련하여 알게 된 외교상 기밀을 누설한 때에 성립하는 신분범이다.\nㄴ. 직무유기죄에서 ‘직무를 유기한 때’란 공무원이 법령, 내규 등에 의한 추상적 충근의무를 태만히 하는 일체의 경우를 의미한다.\nㄷ. 인신구속에 관한 직무를 보조하는 자가 피해자를 구속 하기 위하여 진술조서 등을 허위로 작성한 후 검사와 영장전담판사를 기망하여 구속영장을 발부받아 피해자를 구금한 경우 직권남용감금죄가 성립한다.\nㄹ. 공무상비밀누설죄의 보호법익은 비밀 그 자체가 아니라 비밀의 누설에 의하여 위협받는 국가의 기능이다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄷ, ㄹ"],"a":4}},{"y":2018,"e":"국가직 9급","qn":10,"i":"N92018-10-1","t":"임명권자에 의하여 임용되어 공무에 종사하여 온 甲이 나중에 임용결격자이었음이 밝혀져 당초의 임용행위가 무효라고 하더라도 그가 공무원으로 계속 근무하면서 직무에 관하여 뇌물을 수수한 경우 수뢰죄로 처벌할 수 있다.","ox":"O","m":"①","c":"A","tp":"뇌물죄"},{"y":2018,"e":"국가직 9급","qn":10,"i":"N92018-10-2","t":"알선수뢰죄에서 ‘공무원이 그 지위를 이용하여’라 함은 친구 등 사적 관계를 이용하는 경우뿐만 아니라 다른 공무원이 취급하는 사무처리에 법률상이거나 사실상으로 영향을 줄 수 있는 관계에 있는 공무원이 그 지위를 이용하는 경우도 포함한다.","ox":"X","m":"②","c":"A","tp":"뇌물죄"},{"y":2018,"e":"국가직 9급","qn":10,"i":"N92018-10-3","t":"공무원 甲이 A주식회사로부터 뇌물을 받은 후 A회사에 유리하게 관계 법령을 해석하여 감액처분을 하였는데, 과세 대상에 관한 규정이 명확하지 않고 그에 관한 확립된 선례도 없어 甲의 처분이 위법하지 않은 경우 甲에게 수뢰후부정처사죄가 성립하지 않는다.","ox":"O","m":"③","c":"A","tp":"뇌물죄"},{"y":2018,"e":"국가직 9급","qn":10,"i":"N92018-10-4","t":"A가 오로지 공무원 甲을 함정에 빠뜨릴 의사로 직무와 관련되었다는 형식을 빌려 甲에게 금품을 공여한 경우 甲이 그 금품을 직무와 관련하여 수수한다는 의사를 가지고 받아들이면 수뢰죄가 성립한다.","ox":"O","m":"④","c":"A","tp":"뇌물죄"},{"y":2018,"e":"국가직 9급","qn":16,"i":"N92018-16","t":"甲에게 허위공문서작성죄가 성립하지 않는 경우는?","c":"A","mc":{"s":"甲에게 허위공문서작성죄가 성립하지 않는 경우는?","d":"","o":["준공검사관 공무원 甲이 정산설계서에 의하여 준공검사를 하지 않고도 준공검사를 하였다고 준공검사조서에 기재하였지만, 준공검사조서의 내용이 객관적으로 정산설계서 초안이나 그 후에 작성된 정산설계서 원본의 내용과 일치한 경우","건축담당 공무원 甲이 건축허가신청서를 접수․처리함에 있어 건축법상의 요건을 갖추지 못하고 설계된 사실을 알면서도 기안서인 건축허가통보서를 작성하여 건축허가서의 작성명의인인 군수의 결재를 받아 건축허가서를 작성한 경우","공무원 甲이 폐기물처리사업계획이 관계 법령의 규정에 적합하지 않음을 알았음에도 불구하고 적합하다는 내용의 통보서를 작성한 경우","공무원 甲이 A의 부탁을 받아 A가 세대주임에도 불구하고 A의 동거가족 B를 세대주인 것처럼 된 주민등록표를 작성한 경우"],"a":2}},{"y":2019,"e":"국가직 9급","qn":14,"i":"N92019-14-1","t":"자기의 형사사건에 관한 증거를 인멸하도록 타인에게 부탁하여 죄를 범하게 한 경우에는 증거인멸교사죄가 성립한다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"국가직 9급","qn":14,"i":"N92019-14-2","t":"자기를 위하여 타인으로 하여금 허위의 자백을 하게 하여 범인도피죄를 범하게 한 경우에는 범인도피교사죄가 성립한다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"국가직 9급","qn":14,"i":"N92019-14-3","t":"증인될 자를 자기를 위하여 도피하게 한 것이 다른 공범자의 증인을 도피하게 하는 결과가 된 경우에는 증인도피죄가 성립한다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"국가직 9급","qn":14,"i":"N92019-14-4","t":"자기의 형사사건에 관하여 타인에게 부탁하여 위증하게 한 경우에는 위증교사죄가 성립한다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"국가직 9급","qn":17,"i":"N92019-17-1","t":"알선수뢰죄가 성립하기 위해서는 적어도 다른 공무원이 취급 하는 사무의 처리에 법률상 또는 사실상으로 영향을 줄 수 있는 관계에 있는 공무원이 그 지위를 이용하는 경우이어야 한다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"국가직 9급","qn":17,"i":"N92019-17-2","t":"알선수뢰죄가 성립하기 위해서는 뇌물을 수수할 당시 반드시 상대방에게 알선에 의하여 해결을 도모하여야 할 현안이 존재하여야 할 필요는 없다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"국가직 9급","qn":17,"i":"N92019-17-3","t":"상대방으로 하여금 뇌물을 수수하는 자에게 잘 보이면 손해를 입을 염려가 없다는 정도의 막연한 기대감을 갖게 하고, 뇌물을 수수하는 자도 상대방이 그러한 기대감을 가질 것이라고 짐작 하면서 뇌물을 수수하였다면 알선수뢰죄가 성립한다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"국가직 9급","qn":17,"i":"N92019-17-4","t":"자동차를 뇌물로 제공한 경우 자동차등록원부에 뇌물수수자가 그 소유자로 등록되지 않았다고 하더라도 자동차의 사실상 소유자로서 실질적인 사용 및 처분권한이 있다면 자동차 자체를 뇌물로 취득한 것으로 보아야 한다.","ox":"O","m":"④","c":"A","tp":"알선수뢰죄"},{"y":2021,"e":"국가직 9급","qn":16,"i":"N92021-16-1","t":"객체가 되는 문서는 문서상 작성명의인이 명시되어 있지 않더라도 문서의 형식, 내용 등 문서 자체에 의하여 누가 작성하였는지를 추지할 수 있을 정도의 것이면 된다.","ox":"O","m":"①","c":"A","tp":"허위공문서작성죄"},{"y":2021,"e":"국가직 9급","qn":16,"i":"N92021-16-2","t":"‘직무에 관한 문서’라 함은 공무원이 직무권한 내에서 작성하는 문서를 말하며, 법률뿐 아니라 명령, 내규 또는 관례에 의한 직무집행의 권한으로 작성하는 경우도 포함된다.","ox":"O","m":"②","c":"A","tp":"허위공문서작성죄"},{"y":2021,"e":"국가직 9급","qn":16,"i":"N92021-16-3","t":"공증담당 변호사가 법무사의 직원으로부터 인증촉탁서류를 제출받은 후, 법무사가 공증사무실에 출석하여 사서증서의 날인이 당사자 본인의 것임을 확인한 바 없지만, 업계의 관행에 따라 그러한 확인을 한 것처럼 인증서에 기재한 경우에는 허위 공문서작성죄가 성립하지 아니한다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"국가직 9급","qn":16,"i":"N92021-16-4","t":"공무원이 고의로 법령을 잘못 적용하여 공문서를 작성한 경우에도 그 법령적용의 전제가 된 사실관계에 대한 내용에 거짓이 없다면 허위공문서작성죄가 성립하지 않는다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"국가직 9급","qn":20,"i":"N92021-20-1","t":"공무원의 직무적법성 여부는 행위 당시의 구체적 상황을 기초로 판단하여야 한다.","ox":"O","m":"①","c":"A","tp":"공무집행방해죄"},{"y":2021,"e":"국가직 9급","qn":20,"i":"N92021-20-2","t":"등기신청인이 제출한 허위의 소명자료 등에 대하여 심사권이 있는 등기공무원이 나름대로 충분히 심사를 하였음에도 이를 발견하지 못하여 등기가 마쳐지게 된 경우 위계에 의한 공무 집행방해죄가 성립하지 않는다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"국가직 9급","qn":20,"i":"N92021-20-3","t":"피의자가 적극적으로 허위의 증거를 조작하여 제출하고 그 증거 조작의 결과 수사기관이 그 진위에 관하여 나름대로 충실한 수사를 하더라도 제출된 증거가 허위임을 발견하지 못할 정도에 이르렀다면 위계에 의한 공무집행방해죄가 성립한다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"국가직 9급","qn":20,"i":"N92021-20-4","t":"가처분 신청 시 당사자가 허위의 주장을 하거나 허위의 증거를 제출한 경우 그것만으로는 법원에 대한 위계에 의한 공무집행 방해죄가 성립하지 않는다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"국가직 9급","qn":18,"i":"N92023-18-1","t":"타인의 주민등록표등본을 그와 아무런 관련 없는 사람이 마치 자신의 것인 것처럼 행사하는 행위는 공문서부정행사죄를 구성하지 아니한다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"국가직 9급","qn":18,"i":"N92023-18-2","t":"자동차 등의 운전자가 경찰공무원에게 다른 사람의 운전면허증 자체가 아니라 이를 촬영한 이미지파일을 휴대전화 화면 등을 통하여 보여주는 행위는 공문서부정행사죄를 구성하지 아니한다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"국가직 9급","qn":18,"i":"N92023-18-3","t":"경찰공무원으로부터 신분증의 제시를 요구받고 자신의 인적사항을 속이기 위하여 다른 사람의 운전면허증을 제시한 경우, 운전 면허증의 사용목적에 따른 행사로서 공문서부정행사죄가 성립한다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"국가직 9급","qn":18,"i":"N92023-18-4","t":"습득한 타인의 주민등록증을 자기 가족의 것이라고 제시하면서 그 주민등록증상의 명의로 이동전화 가입신청을 한 경우, 타인의 주민등록증을 본래의 사용용도인 신분확인용으로 사용한 것으로서 공문서부정행사죄가 성립한다.","ox":"X","m":"④","c":"A"},{"y":2024,"e":"국가직 9급","qn":18,"i":"N92024-18","t":"뇌물죄에 대한 설명으로 옳은 것만을 모두 고르면?","c":"A","mc":{"s":"뇌물죄에 대한 설명으로 옳은 것만을 모두 고르면?","d":"ㄱ. 뇌물죄에서 뇌물의 내용인 이익이라 함은 금전, 물품 기타의 재산적 이익뿐만 아니라 사람의 수요ㆍ욕망을 충족시키기에 족한 일체의 유형ㆍ무형의 이익을 포함하며, 제공된 것이 성적 욕구의 충족이라고 하여 달리 볼 것이 아니다.\nㄴ. 법령에 기한 임명권자에 의하여 임용되어 공무에 종사하여 온 사람이 나중에 임용결격자이었음이 밝혀져 당초의 임용 행위가 무효인 경우, 그가 임용행위라는 외관을 갖추어 실제로 공무를 수행하고 그 직무에 관하여 대가성 있는 재물을 수수하였다 하더라도 수뢰죄로 처벌할 수 없다.\nㄷ. 수의계약을 체결하는 공무원이 해당 공사업자와 적정한 금액 이상으로 계약금액을 부풀려서 계약하고 부풀린 금액을 자신이 되돌려받기로 사전에 약정한 다음 그에 따라 수수한 돈은 성격상 뇌물이 아니고 횡령금에 해당한다.\nㄹ. 형법 제130조의 제3자뇌물제공죄에 있어서 ‘부정한 청탁’은 묵시적 의사표시에 의해서도 가능하므로, 당사자 사이에 청탁에 대한 공통의 인식 없이 막연히 선처하여 줄 것이라는 기대로 제3자에게 금품을 공여한 경우에도 묵시적 의사표시에 의한 부정청탁이 있다고 보아야 한다.","o":["ㄱ, ㄷ","ㄱ, ㄹ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":1}},{"y":2025,"e":"국가직 9급","qn":16,"i":"N92025-16","t":"A가 기소중지자인 것을 알면서도 甲이 A의 부탁을 받고 다른 사람의 명의로 대신 임대차계약을 체결해 준 경우 ㄹ.","c":"A","mc":{"s":"A가 기소중지자인 것을 알면서도 甲이 A의 부탁을 받고 다른 사람의 명의로 대신 임대차계약을 체결해 준 경우 ㄹ.","d":"甲에게 범인은닉ㆍ도피죄가 성립되는 것만을 모두 고르면?\nㄱ. 범인이 아닌 甲이 수사기관에 범인임을 자처하고 허위진술을 하여 진범이 체포되거나 발견되는 데 장애를 준 경우\nㄴ. 甲이 乙로부터 “사기범행을 범하고 해외로 도주한 A에게 송금하여 달라.”는 부탁과 함께 받은 자기앞수표를 송금하지 않고 가명으로 예금하여 둔 경우\nㄷ.  폭행용의자 A의 인적사항을 묻는 경찰관의 질문에 甲이 허무인의 이름을 진술하고 구체적인 인적사항은 모른다고 진술한 경우","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":2}},{"y":2025,"e":"국가직 9급","qn":17,"i":"N92025-17","t":"甲에게 위계에 의한 공무집행방해죄가 성립되는 것만을 모두 고르면?","c":"A","mc":{"s":"甲에게 위계에 의한 공무집행방해죄가 성립되는 것만을 모두 고르면?","d":"ㄱ. 甲이 민사소송을 제기함에 있어 피고의 주소를 허위로 기재하여 법원공무원으로 하여금 변론기일소환장 등을 허위 주소에 송달하게 한 경우\nㄴ. 국립대학교의 전임교원 공채심사위원인 학과장 甲이 지원자 乙의 부탁을 받고 이미 논문접수가 마감된 학회지에 乙의 논문이 게재되도록 도운 이후 甲이 연구실적심사의 기준을 강화하자고 해당 학과에 제안한 경우\nㄷ. 변호사 甲이 접견을 핑계로 수용자를 위하여 휴대전화와 증권거래용 단말기를 구치소 내로 몰래 반입하여 이용하게 한 경우\nㄹ. 甲이 수사기관의 착오를 이용하여 적극적으로 피의사실에 관한 증거를 조작하여서 나름대로 충실한 수사를 하더라도 제출된 증거가 허위임을 발견하지 못할 정도인 경우","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":4}}],"11":[{"y":2015,"e":"국가직 9급","qn":20,"i":"N92015-20-1","t":"사문서위조나 공정증서원본불실기재가 성립한 후 피해자의 동의 또는 추인 등으로 문서에 기재된 대로 효과의 승인을 받거나 등기가 실체적 권리관계에 부합하게 되었더라도 이미 성립한 범죄에는 영향이 없다.","ox":"O","m":"①","c":"A","tp":"문서죄"},{"y":2015,"e":"국가직 9급","qn":20,"i":"N92015-20-2","t":"행사할 목적으로 권한 없이 타인 명의의 휴대전화 신규 가입 신청서를 작성한 후 이를 스캔한 이미지 파일을 제3자에게 이메일로 전송하여 컴퓨터 화면상으로 보게 한 경우 사문서 위조죄 및 위조사문서행사죄가 성립한다.","ox":"O","m":"②","c":"A","tp":"문서죄"},{"y":2015,"e":"국가직 9급","qn":20,"i":"N92015-20-3","t":"담뱃갑의 표면에 담배 제조회사와 담배의 종류를 구별·확인할 수 있는 특유의 도안이 표시되어 있는 경우 그 담뱃갑은 문서 등 위조의 대상인 도화에 해당한다.","ox":"O","m":"③","c":"A","tp":"문서죄"},{"y":2015,"e":"국가직 9급","qn":20,"i":"N92015-20-4","t":"공문서위조죄와 달리 사문서위조죄가 성립하기 위해서는 작성명의인이 실재하여야 한다.","ox":"X","m":"④","c":"A","tp":"문서죄"},{"y":2016,"e":"국가직 9급","qn":9,"i":"N92016-09-1","t":"甲이 지방세 수납업무를 일부 대행하는 A은행의 세금수납 영수증의 금액을 고치고 이를 관계서류에 첨부한 경우 공문서 변조 및 동 행사죄가 성립한다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"국가직 9급","qn":9,"i":"N92016-09-2","t":"甲이 외국에서 발행되고 유효기관이 경과한 국제운전면허증에 붙어있던 A의 사진을 떼어내고 그 자리에 자신의 사진을 붙인 후 이를 소지하고 우리나라 도로에서 운전을 한 경우 공문서 위조 및 동 행사죄가 성립한다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"국가직 9급","qn":9,"i":"N92016-09-3","t":"甲이 경력증명서 양식에 실재하지 않는 A한의원의 이름을 적고 임의로 만든 A한의원의 직인을 날인하여 작성한 경우 마치 명의인의 권한 내에서 작성된 문서라고 믿게 할 만한 형식과 외관의 경력증명서를 작성하였다면 사문서위조죄가 성립한다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"국가직 9급","qn":9,"i":"N92016-09-4","t":"A주식회사의 대표이사 甲은 실질적 운영자인 1인 주주 B의 구체적인 위임이나 승낙 없이 이미 퇴임한 전 대표이사 C를 대표이사로 표시하여 A회사 명의의 문서를 작성한 경우 사문서위조죄가 성립한다.","ox":"X","m":"④","c":"A"},{"y":2016,"e":"국가직 9급","qn":10,"i":"N92016-10","t":"다음 설명 중 옳은 것만을 모두 고른 것은?","c":"A","mc":{"s":"다음 설명 중 옳은 것만을 모두 고른 것은?","d":"(다툼이 있는 경우 판례에 의함)\nㄱ. 농촌주택에서 배출되는 생활하수의 배수관(소형 PVC관)을 토사로 막아 하수가 내려가지 못하게 한 경우 수리 방해죄가 성립한다.\nㄴ. 단순히 자신의 신용력을 증명하기 위하여 타인에게 보일 목적으로 통화를 위조한 경우 통화위조죄는 성립하지 않는다.\nㄷ. 기재사항이 누락되어 사법상 무효인 유가증권을 행사할 목적으로 위조하여 일반인으로 하여금 유효한 주권으로 오신시킬 정도의 외관을 갖춘 경우 유가증권위조죄가 성립한다.\nㄹ. 타인에 의하여 이미 위조된 약속어음의 기재사항을 권한 없이 변경한 경우 유가증권변조죄가 성립한다.","o":["ㄱ, ㄷ","ㄴ, ㄷ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":2}},{"y":2020,"e":"국가직 9급","qn":12,"i":"N92020-12-1","t":"일반교통방해죄는 교통이 불가능하거나 현저히 곤란한 상태가 발생하면 바로 기수가 되고 교통방해의 결과가 현실적으로 발생해야 하는 것은 아니다.","ox":"O","m":"①","c":"A","tp":"교통방해의 죄"},{"y":2020,"e":"국가직 9급","qn":12,"i":"N92020-12-2","t":"목장 소유자가 그 운영을 위해 목장용지 내에 임도를 개설하고 차량 출입을 통제하면서 인근 주민들의 일부 통행을 부수적으로 묵인한 경우, 그 임도는 일반교통방해죄의 객체인 ‘육로’에 해당한다.","ox":"X","m":"②","c":"A","tp":"교통방해의 죄"},{"y":2020,"e":"국가직 9급","qn":12,"i":"N92020-12-3","t":"공항 여객터미널 버스정류장 앞 도로 중 공항리무진 버스 외의 다른 차의 주차가 금지된 구역에서 밴 차량을 40분간 불법주차 하고 호객행위를 한 것만으로는 일반교통방해죄에 해당하지 아니한다.","ox":"O","m":"③","c":"A","tp":"교통방해의 죄"},{"y":2020,"e":"국가직 9급","qn":12,"i":"N92020-12-4","t":"업무상 과실로 교량을 손괴하여 자동차의 교통을 방해하고 그 결과 승객이 탑승한 자동차를 교량에서 추락시킨 경우에는 업무상 과실일반교통방해죄와 업무상 과실자동차추락죄가 성립하고, 양 죄는 상상적 경합관계에 있다.","ox":"O","m":"④","c":"A","tp":"교통방해의 죄"},{"y":2020,"e":"국가직 9급","qn":16,"i":"N92020-16-1","t":"위조의 요건을 구비한 이상 그 명의인이 허무인이거나 문서의 작성일자 전에 이미 사망하였다고 하더라도 문서위조죄가 성립하며, 이는 공문서뿐만 아니라 사문서의 경우에도 마찬가지이다.","ox":"O","m":"①","c":"A","tp":"문서의 죄"},{"y":2020,"e":"국가직 9급","qn":16,"i":"N92020-16-2","t":"문서 작성권한의 위임이 있는 경우라고 하더라도 그 위임을 받은 자가 위임받은 권한을 초월하여 문서를 작성한 경우 사문서위조죄가 성립한다.","ox":"O","m":"②","c":"A","tp":"문서의 죄"},{"y":2020,"e":"국가직 9급","qn":16,"i":"N92020-16-3","t":"타인의 대표자 또는 대리자가 그 대표 또는 대리명의로 문서를 작성할 권한을 가지는 경우, 그 지위를 남용하여 자기 또는 제3자의 이익을 도모할 목적으로 문서를 작성하였다 하더라도 자격모용사문서작성죄는 성립하지 아니한다.","ox":"O","m":"③","c":"A","tp":"문서의 죄"},{"y":2020,"e":"국가직 9급","qn":16,"i":"N92020-16-4","t":"불실의 사실이 기재된 공정증서의 정본을 그 정을 모르는 법원 직원에게 교부한 행위는 불실기재공정증서원본행사죄에 해당 한다.","ox":"X","m":"④","c":"A","tp":"문서의 죄"},{"y":2023,"e":"국가직 9급","qn":13,"i":"N92023-13-1","t":"일반교통방해죄는 추상적 위험범으로서 교통이 불가능하거나 또는 현저히 곤란한 상태가 발생하면 바로 기수가 되고 교통방해의 결과가 현실적으로 발생하여야 하는 것은 아니다.","ox":"O","m":"①","c":"A","tp":"교통방해의 죄"},{"y":2023,"e":"국가직 9급","qn":13,"i":"N92023-13-2","t":"집회 또는 시위가 신고된 내용과 다소 다르게 행해졌으나 신고된 범위를 현저히 일탈하지 않는 경우, 그로 인하여 도로의 교통이 방해를 받았다고 하더라도 특별한 사정이 없는 한 일반교통방해죄가 성립하지 않는다.","ox":"O","m":"②","c":"A","tp":"교통방해의 죄"},{"y":2023,"e":"국가직 9급","qn":13,"i":"N92023-13-3","t":"일반교통방해죄는 즉시범이므로 일단 동 죄의 기수에 이르렀다면 기수 이후 그러한 교통방해의 위법상태가 제거되기 전에 교통방해 행위에 가담한 자는 일반교통방해죄의 공동정범이 될 수 없다.","ox":"X","m":"③","c":"A","tp":"교통방해의 죄"},{"y":2023,"e":"국가직 9급","qn":13,"i":"N92023-13-4","t":"업무상과실로 인하여 교량을 손괴하여 자동차의 교통을 방해하고 그 결과 자동차를 추락시킨 경우, 업무상과실일반교통방해죄와 업무상과실자동차추락죄가 각각 성립하고 양 죄는 상상적 경합 관계에 있다.","ox":"O","m":"④","c":"A","tp":"교통방해의 죄"},{"y":2024,"e":"국가직 9급","qn":17,"i":"N92024-17-1","t":"문서 작성권한의 위임을 받은 자가 그 위임받은 권한의 범위 내라 하여도 이를 남용하여 문서를 작성하였다면 사문서위조죄가 성립한다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"국가직 9급","qn":17,"i":"N92024-17-2","t":"2인 이상의 연명으로 된 문서를 위조한 때에는 작성명의인의 수대로 수 개의 문서위조죄가 성립하고, 위 수 개의 문서위조죄는 상상적 경합관계에 있다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"국가직 9급","qn":17,"i":"N92024-17-3","t":"명의인을 기망하여 문서를 작성케 하는 경우는 서명ㆍ날인이 정당히 성립된 경우에도 기망자는 명의인을 이용하여 서명 날인자의 의사에 반하는 문서를 작성케 하는 것이므로 사문서위조죄가 성립한다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"국가직 9급","qn":17,"i":"N92024-17-4","t":"문서명의인이 이미 사망하였는데도 문서명의인이 생존하고 있다는 점이 문서의 중요한 내용을 이루거나 그 점을 전제로 문서가 작성되었다면, 그러한 내용의 문서에 관하여 사망한 명의자의 승낙이 추정된다는 이유로 사문서위조죄의 성립을 부정할 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"국가직 9급","qn":18,"i":"N92025-18-1","t":"甲이 만원권 지폐를 복사기에 복사하고 비슷한 크기로 잘랐으나 복사 상태가 흑백으로만 되어 있어 진정한 통화의 색채를 갖추지 못한 위조통화를 야간에 택시 요금으로 지불한 경우, 甲에게 통화위조죄 및 위조통화행사죄가 성립하지 않는다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"국가직 9급","qn":18,"i":"N92025-18-2","t":"A는 甲을 친생자인 것처럼 출생신고는 하였으나 입양의 요건을 갖추지 못한 채 지내오다, 이후 성인이 된 甲에 의해 살해된 경우, 甲에게 보통살인죄가 성립한다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"국가직 9급","qn":18,"i":"N92025-18-3","t":"甲이 자신과 A가 동업자금으로 구입하여 A가 관리하고 있던 포크레인 1대를 허락 없이 乙로 하여금 운전하여 가도록 한 경우, 甲에게 권리행사방해죄가 성립한다.","ox":"X","m":"③","c":"A"},{"y":2025,"e":"국가직 9급","qn":18,"i":"N92025-18-4","t":"특허발명에 대해 특허심판원의 무효심결이 내려진 후 확정되기 전에 甲이 “A가 생산ㆍ판매한 제품은 위 특허권을 침해한 제품 이다.”라는 사실을 인터넷을 통하여 적시하고 A의 거래처들에 같은 내용의 내용증명을 발송한 경우, 甲에게 허위사실 적시 명예훼손죄와 허위사실 유포 기타 위계에 의한 업무방해죄가 성립하지 않는다.","ox":"O","m":"④","c":"A"}],"8":[{"y":2019,"e":"국가직 9급","qn":10,"i":"N92019-10-1","t":"상해죄가 성립하기 위해서는 상해의 고의와 신체의 완전성을 해하는 행위 및 이로 인하여 발생하는 인과관계 있는 상해의 결과가 있어야 한다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"국가직 9급","qn":10,"i":"N92019-10-2","t":"신체의 외모에 변화가 생겼다고 하더라도 생리적 기능에 장애를 초래하지 아니한 이상 강제추행치상죄에서의 상해에 해당 한다고 할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"국가직 9급","qn":10,"i":"N92019-10-3","t":"오랜 시간 동안의 협박과 폭행을 이기지 못하고 실신하여 범인들이 불러온 구급차 안에서야 정신을 차리게 되었더라도 외부적으로 어떤 상처가 발생하지 않았다면 생리적 기능의 훼손이 있다고 할 수 없으므로 상해가 인정되지 아니한다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"국가직 9급","qn":10,"i":"N92019-10-4","t":"타인의 신체에 폭행을 가하여 보행불능, 수면장애, 식욕감퇴 등 기능의 장해를 일으킨 때에는 외관상 상처가 없더라도 상해를 입힌 경우에 해당한다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"국가직 9급","qn":14,"i":"N92020-14-1","t":"사실혼 관계에 있는 사람들 사이에서 유기죄가 성립하기 위해서는 단순한 동거 또는 간헐적인 정교관계를 맺고 있다는 사정만으로는 부족하고, 그 당사자 사이에 혼인 의사가 있고 사회관념상 혼인생활의 실체가 존재하여야 한다.","ox":"O","m":"①","c":"A","tp":"유기의 죄"},{"y":2020,"e":"국가직 9급","qn":14,"i":"N92020-14-2","t":"수혈이 최선의 치료방법이라는 의사의 권유에도 불구하고 어머니가 종교적 신념을 이유로 사망의 위험이 예견되는 딸에 대한 수혈을 거부함으로써 딸을 사망에 이르게 한 경우 유기치사죄가 성립한다.","ox":"O","m":"②","c":"A","tp":"유기의 죄"},{"y":2020,"e":"국가직 9급","qn":14,"i":"N92020-14-3","t":"유기죄가 성립하기 위해서는 행위자가 요부조자에 대한 보호 책임의 발생원인이 된 사실이 존재한다는 것을 인식하고 이에 기한 부조의무를 해태한다는 의식이 있음을 요한다.","ox":"O","m":"③","c":"A","tp":"유기의 죄"},{"y":2020,"e":"국가직 9급","qn":14,"i":"N92020-14-4","t":"자신의 주점에 손님으로 와서 수일 동안 식사는 한 끼도 하지 않은 채 계속하여 술을 마시고 만취한 피해자를 방치하여 저체온증 등으로 사망에 이르게 한 경우 유기치사죄가 성립하지 않는다.","ox":"X","m":"④","c":"A","tp":"유기의 죄"},{"y":2021,"e":"국가직 9급","qn":15,"i":"N92021-15","t":"학대죄의 ‘학대’란 육체적으로 고통을 주거나 정신적으로 차별대우를 하는 행위를 가리키는 것으로, 단순히 상대방의 인격에 대한 반인륜적 침해만으로는 부족하지만 유기에 준할 정도에 이를 것은 요하지 않는다.","c":"A","mc":{"s":"학대죄의 ‘학대’란 육체적으로 고통을 주거나 정신적으로 차별대우를 하는 행위를 가리키는 것으로, 단순히 상대방의 인격에 대한 반인륜적 침해만으로는 부족하지만 유기에 준할 정도에 이를 것은 요하지 않는다.","d":"유기죄와 학대죄에 대한 설명으로 옳은 것만을 모두 고르면? (다툼이 있는 경우 판례에 의함)\nㄱ. 유기죄에서 ‘계약상 의무’는 계약에 기한 주된 급부의무가 부조를 제공하는 것인 경우에 한정된다.\nㄴ. 술에 만취된 피해자가 경찰지구대로 운반되어 의자 위에 눕혀졌을 때 숨을 가쁘게 쿨쿨 내뿜고 자신의 수족과 의사도 자제할 수 없는 상태에 있음에도 불구하고 경찰관이 3시간여 동안이나 아무런 구호조치를 취하지 아니한 경우 유기죄의 범의를 인정할 수 있다.\nㄷ. 강간치상의 범행을 저지른 자가 그 범행으로 인하여 실신상태에 있는 피해자를 구호하지 아니하고 방치 하였더라도 유기죄는 성립하지 않는다. ㄹ.","o":["ㄱ, ㄷ","ㄱ, ㄹ","ㄴ, ㄷ","ㄴ, ㄹ"],"a":3}},{"y":2024,"e":"국가직 9급","qn":14,"i":"N92024-14-1","t":"사실혼 관계가 인정되는 경우에도 민법 규정의 취지 및 유기죄의 보호법익에 비추어 법률상 보호의무의 존재를 긍정하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"국가직 9급","qn":14,"i":"N92024-14-2","t":"형법 제271조제3항의 중유기죄는 유기죄를 지어 사람의 생명 또는 신체에 위험을 발생하게 한 경우에 성립한다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"국가직 9급","qn":14,"i":"N92024-14-3","t":"유기죄의 계약상 의무는 계약에 기한 주된 부조의무에 한정되지 아니하며, 계약의 목적달성을 위해 상대방의 생명ㆍ신체에 주의와 배려를 한다는 부수의무로서의 민사적 부조의무 또는 보호의무를 배제하는 것은 아니다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"국가직 9급","qn":14,"i":"N92024-14-4","t":"유기치사상죄에서 유기행위와 피해자의 사상이라는 결과 사이에 제3자의 행위가 일부 기여하였다고 할지라도 유기행위로 초래된 위험이 사상이라는 결과로 현실화된 경우라면 상당인과관계를 인정할 수 있다.","ox":"O","m":"④","c":"A","tp":"유기죄"}]};
window.PAIRS=[{"n":1,"s":0.439,"o":{"i":"N92024-06-2","t":"범죄의 성립과 처벌에 관하여 규정한 형벌법규 자체 또는 그로부터 수권 내지 위임을 받은 법령의 변경에 따라 범죄를 구성하지 아니하게 되거나 형이 가벼워진 경우에는, 종전 법령이 범죄로 정하여 처벌한 것이 부당하였다거나 과형이 과중하였다는 반성적 고려에 따라 변경된 것인지 여부를 따지지 않고 원칙적으로 형법 제1조제2항이 적용된다.","y":2024,"e":"국가직 9급"},"x":{"i":"N92023-01-3","t":"범죄 후 형벌법규의 위임을 받은 법령의 변경에 따라 범죄를 구성하지 아니하게 된 경우, 종전 법령이 범죄로 정하여 처벌한 것이 부당하였다는 반성적 고려에 따라 변경된 경우에 한하여 형법 제1조제2항이 적용된다.","y":2023,"e":"국가직 9급"}},{"n":10,"s":0.309,"o":{"i":"N92015-02-1","t":"중간생략등기형 명의신탁의 수탁자가 자기 명의로 신탁된 부동산을 임의처분한 경우 신탁자에 대한 횡령죄가 성립한다.","y":2015,"e":"국가직 9급"},"x":{"i":"N92015-02-2","t":"계약명의신탁의 명의수탁자가 악의의 소유자로부터 취득한 부동산을 임의처분한 경우 명의신탁자에 대한 횡령죄는 성립 하지 않지만 배임죄는 성립한다.","y":2015,"e":"국가직 9급"}},{"n":7,"s":0.4,"o":{"i":"N92023-04-4","t":"형의 선고를 유예하는 경우에 재범방지를 위하여 지도 및 원호가 필요한 때에는 보호관찰을 받을 것을 명할 수 있다.","y":2023,"e":"국가직 9급"},"x":{"i":"N92024-13-3","t":"형의 선고를 유예하는 경우에 재범방지를 위하여 지도 및 원호가 필요한 때에는 보호관찰을 받을 것을 명하여야 하며, 보호관찰을 명한 선고유예를 받은 자가 보호관찰기간 중에 준수사항을 위반 하고 그 정도가 무거운 때에는 유예한 형을 선고하여야 한다.","y":2024,"e":"국가직 9급"}},{"n":7,"s":0.383,"o":{"i":"N92025-11-4","t":"수인의 피해자에 대해 각각 기망행위를 하여 재물을 편취한 경우에는 범의가 단일하고 범행방법이 동일하더라도 각 피해자의 피해법익은 독립한 것이므로 포괄하여 일죄가 되지 않고 피해자별로 독립한 사기죄가 성립한다.","y":2025,"e":"국가직 9급"},"x":{"i":"N92021-09-1","t":"수인의 피해자에 대하여 각 피해자별로 기망행위를 하여 각각 재물을 편취한 경우에도 그 범의가 단일하고 범행방법이 동일한 경우에는 사기죄의 포괄일죄가 성립한다.","y":2021,"e":"국가직 9급"}},{"n":7,"s":0.316,"o":{"i":"N92016-17-2","t":"선고유예의 실효사유인 ‘형의 선고유예를 받은 자가 자격정지 이상의 형에 처한 전과가 발견된 때’란 형의 선고유예의 판결이 확정된 후에 전과가 발견된 경우를 말한다.","y":2016,"e":"국가직 9급"},"x":{"i":"N92024-13-4","t":"형의 선고유예를 받은 자에 대해 유예기간 중 자격정지 이상의 형에 처한 전과가 발견된 경우 유예한 형을 선고할 수 없다.","y":2024,"e":"국가직 9급"}},{"n":6,"s":0.508,"o":{"i":"N92018-18-1","t":"교사를 받은 자가 범죄의 실행을 승낙하고 실행의 착수에 이르지 아니한 때 교사자의 경우 음모 또는 예비에 준하여 처벌한다.","y":2018,"e":"국가직 9급"},"x":{"i":"N92018-18-3","t":"교사를 받은 자가 범죄의 실행을 승낙하지 아니한 경우 피교사자는 음모 또는 예비에 준하여 처벌한다.","y":2018,"e":"국가직 9급"}},{"n":6,"s":0.396,"o":{"i":"N92015-07-4","t":"합동절도의 공모에는 참여하였으나 현장에서 실행행위를 직접 분담하지 아니한 자도 그가 현장에서 절도 범행을 실행한 2인 이상의 범인의 행위를 자기 의사의 수단으로 하여 합동절도의 범행을 하였다고 평가할 수 있는 정범성의 표지를 갖추고 있다면 합동절도의 공동정범이 된다.","y":2015,"e":"국가직 9급"},"x":{"i":"N92025-03-4","t":"3인 이상이 합동절도를 모의한 후 2인 이상이 현장에서 범행을 실행한 경우, 직접 실행행위에 가담하지 않은 자는 그가 현장에서 절도 범행을 실행한 2인 이상의 범인의 행위를 자기 의사의 수단으로 하여 합동절도의 범행을 하였다고 평가할 수 있더라도 합동범의 공동정범이 인정되지 아니한다.","y":2025,"e":"국가직 9급"}},{"n":6,"s":0.385,"o":{"i":"N92024-11-3","t":"공모공동정범에 있어서 그 공모자 중 1인이 다른 공모자가 실행 행위에 이르기 전에 그 공모관계에서 이탈한 경우 그 이탈의 표시는 반드시 명시적임을 요하지 않는다.","y":2024,"e":"국가직 9급"},"x":{"i":"N92015-05-4","t":"공모공동정범의 공모자 중 1인이 다른 공모자가 실행행위에 이르기 전에 그 공모관계에서 이탈한 때에는 그 이후의 다른 공모자의 행위에 관하여 공동정범으로서의 책임은 지지 않는다고 할 것이고 그 이탈의 표시는 명시적이어야 한다.","y":2015,"e":"국가직 9급"}},{"n":2,"s":0.341,"o":{"i":"N92021-07-4","t":"부진정결과적 가중범에서 고의로 중한 결과를 발생하게 한 행위가 별도의 구성요건에 해당하고 그 고의범에 대하여 결과적 가중범에 정한 형보다 더 무겁게 처벌하는 규정이 없는 경우, 결과적 가중범이 고의범에 대하여 특별관계에 있으므로 결과적 가중범만 성립한다.","y":2021,"e":"국가직 9급"},"x":{"i":"N92025-20-1","t":"기본범죄를 통하여 고의로 중한 결과를 발생하게 한 경우에 가중 처벌하는 부진정 결과적 가중범에서 고의범에 대하여 더 무겁게 처벌하는 규정이 없는 경우, 그 결과적 가중범과 고의범은 상상적 경합의 관계에 있다.","y":2025,"e":"국가직 9급"}},{"n":2,"s":0.34,"o":{"i":"N92016-03-3","t":"甲이 A를 살해하려고 총을 쏘았으나 빗나가 옆에 있던 B가 맞아 사망한 경우 구체적 부합설에 따르면 A에 대한 살인미수죄와 B에 대한 과실치사죄의 상상적 경합이 된다.","y":2016,"e":"국가직 9급"},"x":{"i":"N92016-18-4","t":"군인 甲이 하사 A를 살해할 목적으로 발사한 총탄에 이를 제지하려고 甲 앞으로 뛰어들던 병장 B가 맞아 사망한 경우 甲은 A에 대한 살인미수죄와 B에 대한 과실치사죄의 상상적 경합이 된다.","y":2016,"e":"국가직 9급"}},{"n":2,"s":0.322,"o":{"i":"N92016-03-1","t":"甲은 A를 살해하려고 기다리다가 그와 닮은 B를 A로 오인하여 살해한 경우 구체적 부합설에 따르면 B에 대한 살인죄가 성립한다.","y":2016,"e":"국가직 9급"},"x":{"i":"N92016-03-2","t":"甲은 형 A를 살해하려고 기다리다가 아버지 B를 A로 오인하여 살해한 경우 법정적 부합설에 따르면 보통살인죄의 미수와 존속살해죄의 상상적 경합이 된다.","y":2016,"e":"국가직 9급"}},{"n":5,"s":0.574,"o":{"i":"N92021-08-3","t":"甲이 A에게 위조한 예금통장 사본 등을 보여주면서 외국 회사에서 투자금을 받았다고 거짓말하며 자금 대여를 요청한 후 A와 함께 그 입금 여부를 확인하기 위해 은행에 가던 중 범행이 발각될 것이 두려워 은행 입구에서 그 차용을 포기하고 돌아간 경우 사기죄의 장애미수에 해당한다.","y":2021,"e":"국가직 9급"},"x":{"i":"N92024-09-1","t":"甲이 A에게 위조한 통장 사본 등을 보여 주면서 투자금을 받았다고 거짓말하며 자금 대여를 요청하였으나 A와 함께 그 입금 여부를 확인하기 위해 은행에 가던 중 범행이 발각될 것이 두려워 차용을 포기하고 돌아간 경우, 사기죄의 중지미수가 성립한다.","y":2024,"e":"국가직 9급"}},{"n":4,"s":0.507,"o":{"i":"N92020-01-2","t":"정신적 장애가 있는 자라도 범행 당시 정상적인 사물변별 능력이나 행위통제능력이 있었다면 심신장애로 볼 수 없다.","y":2020,"e":"국가직 9급"},"x":{"i":"N92018-04-4","t":"소아기호증의 정신적 장애가 있는 자라면 범행 당시 정상적인 사물변별능력이나 행위통제능력이 있었더라도 형법 제10조의 심신장애로 볼 수 있다.","y":2018,"e":"국가직 9급"}},{"n":4,"s":0.483,"o":{"i":"N92018-04-1","t":"형법 제10조제3항은 고의에 의한 원인에 있어서의 자유로운 행위만이 아니라 과실에 의한 원인에 있어서의 자유로운 행위까지도 포함한다.","y":2018,"e":"국가직 9급"},"x":{"i":"N92021-04-3","t":"형법 제10조제3항은 고의에 의한 원인에 있어서의 자유로운 행위를 포함하고 과실에 의한 원인에 있어서의 자유로운 행위는 포함하지 않는다.","y":2021,"e":"국가직 9급"}},{"n":4,"s":0.3,"o":{"i":"N92023-09-2","t":"심신장애는 생물학적 요소 외에 심리학적 요소로서 정신병 또는 비정상적 정신상태와 같은 정신적 장애로 말미암아 사물에 대한 변별능력과 그에 따른 행위통제능력이 결여되거나 감소되었음을 요한다.","y":2023,"e":"국가직 9급"},"x":{"i":"N92021-04-1","t":"심신장애는 생물학적 요소로서 정신병이나 정신박약 또는 비정상적 정신상태와 같은 정신적 장애가 있는 것만으로도 인정된다.","y":2021,"e":"국가직 9급"}},{"n":3,"s":0.352,"o":{"i":"N92020-17-3","t":"피해자와 공모하여 보험금을 편취할 목적으로 교통사고를 가장하여 피해자에게 상해를 가하였다면 피해자의 승낙이 있었더라도 위법성이 조각되지 않는다.","y":2020,"e":"국가직 9급"},"x":{"i":"N92018-03-4","t":"甲이 피해자 A와 공모하여 교통사고를 가장하여 보험금을 편취할 목적으로 피해자 A에게 상해를 가한 행위는 A의 승낙에 의하여 위법성이 조각된다.","y":2018,"e":"국가직 9급"}},{"n":12,"s":0.413,"o":{"i":"N92019-17-1","t":"알선수뢰죄가 성립하기 위해서는 적어도 다른 공무원이 취급 하는 사무의 처리에 법률상 또는 사실상으로 영향을 줄 수 있는 관계에 있는 공무원이 그 지위를 이용하는 경우이어야 한다.","y":2019,"e":"국가직 9급"},"x":{"i":"N92018-10-2","t":"알선수뢰죄에서 ‘공무원이 그 지위를 이용하여’라 함은 친구 등 사적 관계를 이용하는 경우뿐만 아니라 다른 공무원이 취급하는 사무처리에 법률상이거나 사실상으로 영향을 줄 수 있는 관계에 있는 공무원이 그 지위를 이용하는 경우도 포함한다.","y":2018,"e":"국가직 9급"}},{"n":11,"s":0.41,"o":{"i":"N92020-16-2","t":"문서 작성권한의 위임이 있는 경우라고 하더라도 그 위임을 받은 자가 위임받은 권한을 초월하여 문서를 작성한 경우 사문서위조죄가 성립한다.","y":2020,"e":"국가직 9급"},"x":{"i":"N92024-17-1","t":"문서 작성권한의 위임을 받은 자가 그 위임받은 권한의 범위 내라 하여도 이를 남용하여 문서를 작성하였다면 사문서위조죄가 성립한다.","y":2024,"e":"국가직 9급"}}];
